insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 9/2015, de 28 de julio, de Régimen de Personal de la Policía Nacional (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-8468', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-08-policia-nacional', 'Tema 8. La Dirección General de la Policía y la Policía Nacional: escalas, acceso, disciplina y situaciones') on conflict (slug) do nothing;
