   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 4/2000, de 11 de enero, sobre derechos y libertades de los extranjeros en España y su integración social (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-544', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-11-infracciones-extranjeria', 'Tema 11. Infracciones y sanciones en materia de extranjería, expulsión y devolución') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-11-infracciones-extranjeria' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"La potestad sancionadora en materia de extranjería (LO 4/2000, art. 50)"},{"n":"2","title":"Tipos de infracciones (art. 51)"},{"n":"2.1","title":"Infracciones leves (art. 52)"},{"n":"2.2","title":"Infracciones graves (art. 53)"},{"n":"2.3","title":"Infracciones muy graves (art. 54)"},{"n":"3","title":"Sanciones: cuantías, órganos competentes y graduación (art. 55)"},{"n":"4","title":"Prescripción de las infracciones y de las sanciones (art. 56)"},{"n":"5","title":"La expulsión del territorio (art. 57)"},{"n":"6","title":"Efectos de la expulsión y devolución (art. 58)"},{"n":"7","title":"Efectos de la denegación de entrada (art. 60)"},{"n":"8","title":"Medidas cautelares, internamiento y procedimientos de expulsión (arts. 61-64)"}]'::jsonb, '["Art. 51.2 LO 4/2000: «Las infracciones administrativas establecidas en la presente Ley Orgánica se clasifican en leves, graves y muy graves.»","Art. 52.b) LO 4/2000: «b) El retraso, hasta tres meses, en la solicitud de renovación de las autorizaciones una vez hayan caducado.»","Art. 53.1.a) LO 4/2000: «a) Encontrarse irregularmente en territorio español, por no haber obtenido la prórroga de estancia, carecer de autorización de residencia o tener caducada más de tres meses la mencionada autorización, y siempre que el interesado no hubiere solicitado la renovación de la misma en el plazo previsto reglamentariamente.»","Art. 54.1.b) LO 4/2000: «b) Inducir, promover, favorecer o facilitar con ánimo de lucro, individualmente o formando parte de una organización, la inmigración clandestina de personas en tránsito o con destino al territorio español o su permanencia en el mismo, siempre que el hecho no constituya delito.»","Art. 55.1 LO 4/2000: «a) Las infracciones leves con multa de hasta 500 euros. b) Las infracciones graves con multa de 501 hasta 10.000 euros.»","Art. 55.1.c) LO 4/2000: «c) Las infracciones muy graves con multa desde 10.001 hasta 100.000 euros, excepto la prevista en el artículo 54.2.b), que lo será con una multa de 5.000 a 10.000 euros por cada viajero transportado o con un mínimo de 750.000 euros a tanto alzado, con independencia del número de viajeros transportados.»","Art. 55.2 LO 4/2000: «La imposición de sanciones por las infracciones administrativas establecidas en la presente Ley Orgánica corresponderá al Subdelegado del Gobierno o al Delegado del Gobierno en las Comunidades Autónomas uniprovinciales.»","Art. 56 LO 4/2000: «1. Las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses. 2. Las sanciones impuestas por infracciones muy graves prescribirán a los cinco años, las graves a los dos años y las impuestas por infracciones leves al año.»","Art. 57.1 LO 4/2000: «Cuando los infractores sean extranjeros y realicen conductas de las tipificadas como muy graves, o conductas graves de las previstas en los apartados a), b), c), d) y f) del artículo 53.1 de esta Ley Orgánica, podrá aplicarse, en atención al principio de proporcionalidad, en lugar de la sanción de multa, la expulsión del territorio español, previa la tramitación del correspondiente expediente administrativo y mediante la resolución motivada que valore los hechos que configuran la infracción.»","Art. 57.3 LO 4/2000: «En ningún caso podrán imponerse conjuntamente las sanciones de expulsión y multa.»","Art. 58.1 LO 4/2000: «La expulsión llevará consigo la prohibición de entrada en territorio español. La duración de la prohibición se determinará en consideración a las circunstancias que concurran en cada caso y su vigencia no excederá de cinco años.»","Art. 58.3 LO 4/2000: «No será preciso expediente de expulsión para la devolución de los extranjeros en los siguientes supuestos: a) Los que habiendo sido expulsados contravengan la prohibición de entrada en España. b) Los que pretendan entrar ilegalmente en el país.»","Art. 58.6 LO 4/2000: «Cuando la devolución no se pudiera ejecutar en el plazo de 72 horas, se solicitará de la autoridad judicial la medida de internamiento prevista para los expedientes de expulsión.»","Art. 60.1 LO 4/2000: «Los extranjeros a los que en frontera se les deniegue la entrada según lo previsto por el artículo 26.2 de esta Ley, estarán obligados a regresar a su punto de origen.»","Art. 62.2 LO 4/2000: «El internamiento se mantendrá por el tiempo imprescindible para los fines del expediente, siendo su duración máxima de 60 días, y sin que pueda acordarse un nuevo internamiento por cualquiera de las causas previstas en un mismo expediente.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"La potestad sancionadora y los tipos de infracciones","blocks":[{"text":"El régimen sancionador en materia de extranjería está en el Título III de la Ley Orgánica 4/2000. La potestad sancionadora se ajusta a lo que dispone esta ley, a su desarrollo reglamentario y a la ley general de procedimiento; el artículo 50 sigue citando la Ley 30/1992, hoy derogada y sustituida por las Leyes 39/2015 y 40/2015 (dato que no recoge el texto de la LO 4/2000 de la plataforma). Responden administrativamente quienes sean autores o participen en las infracciones (art. 51.1), que se clasifican en leves, graves y muy graves (art. 51.2).","refs":[{"ref":"Art. 50 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"se ajustará a la dispuesto en la misma y en sus disposiciones de desarrollo, y en la Ley 30/1992, de Régimen Jurídico de las Administraciones Públicas y del Procedimiento Administrativo Común."},{"ref":"Art. 51 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"Incurrirán en responsabilidad administrativa quienes sean autores o participen en cualquiera de las infracciones tipificadas en los artículos siguientes. 2. Las infracciones administrativas establecidas en la presente Ley Orgánica se clasifican en leves, graves y muy graves."}]}]},{"n":"2","title":"Infracciones leves (art. 52)","blocks":[{"text":"Son leves, entre otras: no comunicar o comunicar con retraso a las autoridades los cambios de nacionalidad, estado civil o domicilio; el retraso de hasta tres meses en pedir la renovación de las autorizaciones ya caducadas; trabajar por cuenta propia sin haber solicitado autorización cuando se tiene residencia temporal; trabajar en una ocupación, sector o ámbito geográfico no previsto en la autorización; y contratar trabajadores cuya autorización no les habilita para esa ocupación o ámbito, con una infracción por cada trabajador. También lo es que las entidades que atienden a menores extranjeros no acompañados no comuniquen a la autoridad su localización.","refs":[{"ref":"Art. 52.a) LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"La omisión o el retraso en la comunicación a las autoridades españolas de los cambios de nacionalidad, de estado civil o de domicilio"},{"ref":"Art. 52.b) LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"El retraso, hasta tres meses, en la solicitud de renovación de las autorizaciones una vez hayan caducado."},{"ref":"Art. 52.e) LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"incurriéndose en una infracción por cada uno de los trabajadores extranjeros ocupados."},{"ref":"Art. 52.f) LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"de la localización de personas menores de edad extranjeras no acompañadas"}]}]},{"n":"3","title":"Infracciones graves (art. 53)","blocks":[{"text":"La infracción grave más conocida es encontrarse irregularmente en España: no haber obtenido la prórroga de estancia, carecer de autorización de residencia o tenerla caducada más de tres meses sin haber pedido la renovación en plazo (art. 53.1.a). También son graves trabajar sin autorización de trabajo cuando no se tiene residencia válida; la ocultación dolosa o falsedad grave al comunicar los cambios personales o en los datos del padrón; incumplir las medidas de seguridad pública, de presentación periódica o de alejamiento; cometer una tercera infracción leve habiendo sido sancionado por dos de la misma naturaleza en el año anterior; salir por puestos no habilitados; e incumplir la obligación de solicitar la tarjeta de identidad de extranjero (art. 53.1).","refs":[{"ref":"Art. 53.1.a) LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"Encontrarse irregularmente en territorio español, por no haber obtenido la prórroga de estancia, carecer de autorización de residencia o tener caducada más de tres meses la mencionada autorización, y siempre que el interesado no hubiere solicitado la renovación de la misma en el plazo previsto reglamentariamente."},{"ref":"Art. 53.1.e) LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"La comisión de una tercera infracción leve, siempre que en un plazo de un año anterior hubiera sido sancionado por dos faltas leves de la misma naturaleza."},{"ref":"Art. 53.1.g) LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"Las salidas del territorio español por puestos no habilitados, sin exhibir la documentación prevista o contraviniendo las prohibiciones legalmente impuestas."}]},{"text":"El art. 53.2 añade otras graves que puede cometer cualquiera, español o extranjero: que el empresario no dé de alta en la Seguridad Social al trabajador cuya autorización solicitó; contraer matrimonio, simular relación afectiva o constituirse en representante legal de un menor con ánimo de lucro o para obtener indebidamente la residencia, si no es delito; promover la permanencia irregular de un extranjero invitado que sigue a su cargo; y que el titular de una vivienda consienta la inscripción en el padrón de un extranjero que no vive realmente en ella, con una infracción por cada persona inscrita. La letra f) del art. 53.1 todavía remite a la LO 1/1992 de seguridad ciudadana, derogada por la LO 4/2015.","refs":[{"ref":"Art. 53.2.b) LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"Contraer matrimonio, simular relación afectiva análoga o constituirse en representante legal de un menor, cuando dichas conductas se realicen con ánimo de lucro o con el propósito de obtener indebidamente un derecho de residencia, siempre que tales hechos no constituyan delito."},{"ref":"Art. 53.2.d) LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"Consentir la inscripción de un extranjero en el Padrón Municipal por parte del titular de una vivienda habilitado para tal fin, cuando dicha vivienda no constituya el domicilio real del extranjero. Se incurrirá en una infracción por cada persona indebidamente inscrita."},{"ref":"Art. 53.1.f) LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"previstas como graves en la Ley Orgánica 1/1992, de 21 de febrero, sobre Protección de la Seguridad Ciudadana."}]}]},{"n":"4","title":"Infracciones muy graves (art. 54)","blocks":[{"text":"Son muy graves: participar en actividades contrarias a la seguridad nacional o que puedan perjudicar las relaciones de España con otros países; inducir, promover, favorecer o facilitar con ánimo de lucro la inmigración clandestina, si no es delito; las conductas de discriminación racial, étnica, nacional o religiosa; contratar trabajadores extranjeros sin autorización previa de residencia y trabajo, con una infracción por cada trabajador; el empadronamiento consentido con ánimo de lucro; simular una relación laboral; y la tercera infracción grave tras dos sanciones graves de la misma naturaleza en un año (art. 54.1).","refs":[{"ref":"Art. 54.1.b) LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"Inducir, promover, favorecer o facilitar con ánimo de lucro, individualmente o formando parte de una organización, la inmigración clandestina de personas en tránsito o con destino al territorio español o su permanencia en el mismo, siempre que el hecho no constituya delito."},{"ref":"Art. 54.1.d) LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"La contratación de trabajadores extranjeros sin haber obtenido con carácter previo la correspondiente autorización de residencia y trabajo, incurriéndose en una infracción por cada uno de los trabajadores extranjeros ocupados"}]},{"text":"También son muy graves las infracciones de los transportistas: incumplir sus obligaciones de información, transportar extranjeros a España sin comprobar la validez de pasaportes, documentos y visados, y no hacerse cargo sin pérdida de tiempo del pasajero al que no se autoriza la entrada (art. 54.2). No es infracción transportar a la frontera a quien pide sin demora protección internacional y esta se admite a trámite (art. 54.3).","refs":[{"ref":"Art. 54.2.b) LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"El transporte de extranjeros por vía aérea, marítima o terrestre, hasta el territorio español, por los sujetos responsables del transporte, sin que hubieran comprobado la validez y vigencia"},{"ref":"Art. 54.3 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"no se considerará infracción a la presente Ley el hecho de transportar hasta la frontera española a un extranjero que, habiendo presentado sin demora su solicitud de protección internacional, ésta le sea admitida a trámite"}]}]},{"n":"5","title":"Sanciones, órganos competentes y graduación (art. 55)","blocks":[{"text":"Las multas son: leves, hasta 500 euros; graves, de 501 a 10.000 euros; muy graves, de 10.001 a 100.000 euros, salvo el transporte sin comprobar documentos, que se castiga con 5.000 a 10.000 euros por viajero o un mínimo de 750.000 euros a tanto alzado (art. 55.1). Sanciona el Subdelegado del Gobierno o el Delegado del Gobierno en las comunidades uniprovinciales; si la infracción es participar en actividades contrarias a la seguridad nacional, la competencia es del Secretario de Estado de Seguridad (art. 55.2). Las infracciones laborales se inician por acta de la Inspección de Trabajo y Seguridad Social.","refs":[{"ref":"Art. 55.1 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"a) Las infracciones leves con multa de hasta 500 euros. b) Las infracciones graves con multa de 501 hasta 10.000 euros."},{"ref":"Art. 55.1.c) LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"Las infracciones muy graves con multa desde 10.001 hasta 100.000 euros, excepto la prevista en el artículo 54.2.b), que lo será con una multa de 5.000 a 10.000 euros por cada viajero transportado o con un mínimo de 750.000 euros a tanto alzado"},{"ref":"Art. 55.2 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"La imposición de sanciones por las infracciones administrativas establecidas en la presente Ley Orgánica corresponderá al Subdelegado del Gobierno o al Delegado del Gobierno en las Comunidades Autónomas uniprovinciales."},{"ref":"Art. 55.2 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"la competencia sancionadora corresponderá al Secretario de Estado de Seguridad."}]},{"text":"Para graduar la sanción se aplica la proporcionalidad, valorando la culpabilidad, el daño o riesgo y su trascendencia (art. 55.3), y para la cuantía se atiende especialmente a la capacidad económica del infractor (art. 55.4). En la inmigración clandestina se decomisan los vehículos, embarcaciones, aeronaves y demás bienes utilizados (art. 55.5), y en la contratación sin autorización puede clausurarse el local de seis meses a cinco años (art. 55.6).","refs":[{"ref":"Art. 55.4 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"Para la determinación de la cuantía de la sanción se tendrá especialmente en cuenta la capacidad económica del infractor."},{"ref":"Art. 55.6 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"la clausura del establecimiento o local desde seis meses a cinco años."}]}]},{"n":"6","title":"Prescripción de las infracciones y de las sanciones (art. 56)","blocks":[{"text":"Las infracciones prescriben: las muy graves a los tres años, las graves a los dos años y las leves a los seis meses. Las sanciones prescriben: las de infracciones muy graves a los cinco años, las de graves a los dos años y las de leves al año. Si la sanción es la expulsión, la prescripción no empieza a contar hasta que transcurra el período de prohibición de entrada fijado, con un máximo de diez años.","refs":[{"ref":"Art. 56 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"1. Las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses. 2. Las sanciones impuestas por infracciones muy graves prescribirán a los cinco años, las graves a los dos años y las impuestas por infracciones leves al año."},{"ref":"Art. 56.3 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"la prescripción no empezará a contar hasta que haya transcurrido el período de prohibición de entrada fijado en la resolución con un máximo de diez años."}]}]},{"n":"7","title":"La expulsión del territorio (art. 57)","blocks":[{"text":"En las infracciones muy graves y en las graves de las letras a), b), c), d) y f) del art. 53.1, puede imponerse, por proporcionalidad y en lugar de la multa, la expulsión, previo expediente y resolución motivada (art. 57.1). También es causa de expulsión haber sido condenado, dentro o fuera de España, por conducta dolosa que constituya delito castigado con pena privativa de libertad superior a un año, salvo antecedentes cancelados (art. 57.2). Expulsión y multa no pueden imponerse nunca conjuntamente (art. 57.3), y la expulsión extingue cualquier autorización para permanecer en España (art. 57.4).","refs":[{"ref":"Art. 57.1 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"podrá aplicarse, en atención al principio de proporcionalidad, en lugar de la sanción de multa, la expulsión del territorio español, previa la tramitación del correspondiente expediente administrativo y mediante la resolución motivada"},{"ref":"Art. 57.2 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"que el extranjero haya sido condenado, dentro o fuera de España, por una conducta dolosa que constituya en nuestro país delito sancionado con pena privativa de libertad superior a un año, salvo que los antecedentes penales hubieran sido cancelados."},{"ref":"Art. 57.3 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"En ningún caso podrán imponerse conjuntamente las sanciones de expulsión y multa."}]},{"text":"Salvo seguridad nacional o reincidencia, no puede expulsarse a los nacidos en España con residencia legal en los últimos cinco años, a los residentes de larga duración, a quienes fueron españoles de origen ni a determinados perceptores de prestaciones (art. 57.5). Tampoco se ejecuta si vulnera el principio de no devolución o afecta a embarazadas con riesgo para la gestación o la salud (art. 57.6). Condenados por los delitos de los arts. 312.1, 313.1 y 318 bis CP son expulsados una vez cumplida la pena (art. 57.8).","refs":[{"ref":"Art. 57.5.a) LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"Los nacidos en España que hayan residido legalmente en los últimos cinco años."},{"ref":"Art. 57.6 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"La expulsión no podrá ser ejecutada cuando ésta conculcase el principio de no devolución, o afecte a las mujeres embarazadas"},{"ref":"Art. 57.8 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"la expulsión se llevará a efecto una vez cumplida la pena privativa de libertad."}]}]},{"n":"8","title":"Efectos de la expulsión y devolución (art. 58)","blocks":[{"text":"La expulsión lleva consigo una prohibición de entrada cuya vigencia no excede de cinco años (art. 58.1), aunque excepcionalmente puede llegar a diez si el extranjero es una amenaza grave para el orden público, la seguridad pública, la seguridad nacional o la salud pública (art. 58.2). No hace falta expediente de expulsión para la devolución de quienes contravienen una prohibición de entrada o pretenden entrar ilegalmente en el país (art. 58.3). Si piden protección internacional, no se les devuelve hasta que se inadmita a trámite su petición, y tampoco a embarazadas con riesgo (art. 58.4).","refs":[{"ref":"Art. 58.1 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"La expulsión llevará consigo la prohibición de entrada en territorio español. La duración de la prohibición se determinará en consideración a las circunstancias que concurran en cada caso y su vigencia no excederá de cinco años."},{"ref":"Art. 58.2 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"podrá imponerse un período de prohibición de entrada de hasta diez años."},{"ref":"Art. 58.3 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"No será preciso expediente de expulsión para la devolución de los extranjeros en los siguientes supuestos: a) Los que habiendo sido expulsados contravengan la prohibición de entrada en España. b) Los que pretendan entrar ilegalmente en el país."}]},{"text":"La devolución la acuerda la autoridad gubernativa competente para la expulsión (art. 58.5); si no puede ejecutarse en 72 horas, se pide al juez el internamiento (art. 58.6). La devolución por quebrantar una prohibición reinicia el cómputo de esta (art. 58.7). El inciso que fijaba una prohibición de tres años para la devolución por entrada ilegal fue anulado por la STC 17/2013. Por su parte, la disposición adicional décima permite rechazar en la frontera de Ceuta o Melilla a quien intenta superar los elementos de contención, respetando los derechos humanos.","refs":[{"ref":"Art. 58.5 y 58.6 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"La devolución será acordada por la autoridad gubernativa competente para la expulsión. 6. Cuando la devolución no se pudiera ejecutar en el plazo de 72 horas, se solicitará de la autoridad judicial la medida de internamiento prevista para los expedientes de expulsión."},{"ref":"Nota al art. 58.7 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"se declara inconstitucional y nulo el inciso destacado del apartado 7"},{"ref":"DA 10.ª LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"podrán ser rechazados a fin de impedir su entrada ilegal en España."}]}]},{"n":"9","title":"Efectos de la denegación de entrada (art. 60)","blocks":[{"text":"A quien se deniega la entrada en frontera está obligado a regresar a su punto de origen, y la resolución conlleva adoptar de inmediato las medidas para que regrese cuanto antes. Si el regreso va a retrasarse más de setenta y dos horas, la autoridad que denegó la entrada se dirige al Juez de Instrucción para que determine el lugar de internamiento (art. 60.1). Estos lugares no tienen carácter penitenciario y el internado solo está privado del derecho ambulatorio (art. 60.2). La detención se comunica al Ministerio de Asuntos Exteriores y a la embajada o consulado (art. 60.4).","refs":[{"ref":"Art. 60.1 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"estarán obligados a regresar a su punto de origen."},{"ref":"Art. 60.1 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"Cuando el regreso fuera a retrasarse más de setenta y dos horas, la autoridad que hubiera denegado la entrada se dirigirá al Juez de Instrucción para que determine el lugar donde hayan de ser internados hasta ese momento."},{"ref":"Art. 60.2 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"Los lugares de internamiento para extranjeros no tendrán carácter penitenciario"},{"ref":"Art. 60.2 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"Los extranjeros internados estarán privados únicamente del derecho ambulatorio."}]}]},{"n":"10","title":"Medidas cautelares, internamiento y procedimientos de expulsión (arts. 61-64)","blocks":[{"text":"Incoado un procedimiento en el que pueda proponerse la expulsión, el instructor puede acordar medidas cautelares: presentación periódica, residencia obligatoria, retirada del pasaporte, detención cautelar de hasta 72 horas previas a la solicitud de internamiento, o internamiento preventivo con autorización judicial (art. 61.1). El internamiento lo acuerda el Juez de Instrucción por auto motivado y dura lo imprescindible, con un máximo de 60 días y sin nuevo internamiento por las mismas causas en el mismo expediente (art. 62). No pueden ingresar menores (art. 62.4).","refs":[{"ref":"Art. 61.1.d) LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"Detención cautelar, por la autoridad gubernativa o sus agentes, por un período máximo de 72 horas previas a la solicitud de internamiento."},{"ref":"Art. 62.2 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"El internamiento se mantendrá por el tiempo imprescindible para los fines del expediente, siendo su duración máxima de 60 días, y sin que pueda acordarse un nuevo internamiento por cualquiera de las causas previstas en un mismo expediente."},{"ref":"Art. 62.4 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"No podrá acordarse el ingreso de menores en los centros de internamiento"}]},{"text":"El procedimiento preferente se aplica, entre otros casos, a la seguridad nacional y la inmigración clandestina; el interesado tiene 48 horas para alegar y la expulsión se ejecuta de forma inmediata, sin período de salida voluntaria (art. 63). En el ordinario, la resolución fija un plazo de cumplimiento voluntario de siete a treinta días (art. 63 bis.2); si vence sin salir, el extranjero es detenido y conducido al puesto de salida (art. 64.1).","refs":[{"ref":"Art. 63.4 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"para que alegue lo que considere adecuado, en el plazo de 48 horas"},{"ref":"Art. 63 bis.2 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"La duración de dicho plazo oscilará entre siete y treinta días y comenzará a contar desde el momento de la notificación de la citada resolución."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Tres clases de infracciones: leves, graves y muy graves. Estar en situación irregular es grave; facilitar con lucro la inmigración clandestina es muy grave.","refs":[{"ref":"Art. 51.2 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"se clasifican en leves, graves y muy graves."}]},{"text":"Retraso de hasta tres meses en pedir la renovación: leve; caducada más de tres meses sin pedirla: grave.","refs":[{"ref":"Art. 52.b) LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"El retraso, hasta tres meses, en la solicitud de renovación de las autorizaciones una vez hayan caducado."}]},{"text":"Multas: leves hasta 500 euros; graves de 501 a 10.000; muy graves de 10.001 a 100.000.","refs":[{"ref":"Art. 55.1.c) LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"Las infracciones muy graves con multa desde 10.001 hasta 100.000 euros"}]},{"text":"Sanciona el Subdelegado del Gobierno (o Delegado en uniprovinciales); en seguridad nacional, el Secretario de Estado de Seguridad.","refs":[{"ref":"Art. 55.2 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"corresponderá al Subdelegado del Gobierno o al Delegado del Gobierno en las Comunidades Autónomas uniprovinciales."}]},{"text":"Prescripción de infracciones 3 años, 2 años y 6 meses; de sanciones 5 años, 2 años y 1 año.","refs":[{"ref":"Art. 56.2 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"Las sanciones impuestas por infracciones muy graves prescribirán a los cinco años"}]},{"text":"Expulsión y multa nunca juntas. Condena dolosa con pena superior a un año: causa de expulsión.","refs":[{"ref":"Art. 57.3 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"En ningún caso podrán imponerse conjuntamente las sanciones de expulsión y multa."}]},{"text":"Prohibición de entrada por expulsión: máximo cinco años; excepcionalmente, hasta diez.","refs":[{"ref":"Art. 58.2 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"hasta diez años"}]},{"text":"Devolución sin expediente de expulsión; si no se ejecuta en 72 horas, internamiento judicial. Denegación de entrada con retraso de más de 72 horas: Juez de Instrucción.","refs":[{"ref":"Art. 58.6 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"Cuando la devolución no se pudiera ejecutar en el plazo de 72 horas"}]},{"text":"Internamiento en CIE: máximo 60 días, nunca menores.","refs":[{"ref":"Art. 62.2 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"siendo su duración máxima de 60 días"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-544'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-544', null, null, null, null
  from public.topics t where t.slug = 'pn-11-infracciones-extranjeria'
