insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 12/2009, de 30 de octubre, reguladora del derecho de asilo y de la protección subsidiaria (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-12-proteccion-internacional', 'Tema 12. La protección internacional, menores y personas vulnerables, apátridas y desplazados') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-12-proteccion-internacional' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"La protección internacional: objeto, asilo y protección subsidiaria (Ley 12/2009, arts. 1-5)"},{"n":"1.1","title":"Condiciones del asilo y de la protección subsidiaria (arts. 6-15)"},{"n":"2","title":"Reglas procedimentales para el reconocimiento de la protección internacional"},{"n":"2.1","title":"Presentación de la solicitud: derechos, obligaciones y efectos (arts. 16-19)"},{"n":"2.2","title":"No admisión y solicitudes en puestos fronterizos (arts. 20-22)"},{"n":"2.3","title":"Tramitación: órganos, procedimiento ordinario y de urgencia, recursos (arts. 23-29)"},{"n":"3","title":"Condiciones de acogida y centros de acogida (arts. 30-33)"},{"n":"4","title":"Intervención del ACNUR y efectos de la resolución (arts. 34-38)"},{"n":"5","title":"De los menores y otras personas vulnerables (arts. 46-48)"},{"n":"6","title":"Apátridas (LO 4/2000, art. 34) y desplazados (Ley 12/2009, disp. adic. segunda)"}]'::jsonb, '["Art. 2 Ley 12/2009: «El derecho de asilo es la protección dispensada a los nacionales no comunitarios o a los apátridas a quienes se reconozca la condición de refugiado en los términos definidos en el artículo 3 de esta Ley y en la Convención sobre el Estatuto de los Refugiados, hecha en Ginebra el 28 de julio de 1951, y su Protocolo, suscrito en Nueva York el 31 de enero de 1967.»","Art. 4 Ley 12/2009: «El derecho a la protección subsidiaria es el dispensado a las personas de otros países y a los apátridas que, sin reunir los requisitos para obtener el asilo o ser reconocidas como refugiadas, pero respecto de las cuales se den motivos fundados para creer que si regresasen a su país de origen en el caso de los nacionales o, al de su anterior residencia habitual en el caso de los apátridas, se enfrentarían a un riesgo real de sufrir alguno de los daños graves previstos en el artículo 10 de esta Ley»","Art. 5 Ley 12/2009: «La protección concedida con el derecho de asilo y la protección subsidiaria consiste en la no devolución ni expulsión de las personas a quienes se les haya reconocido»","Art. 16.1 Ley 12/2009: «Las personas nacionales no comunitarias y las apátridas presentes en territorio español tienen derecho a solicitar protección internacional en España.»","Art. 17.2 Ley 12/2009: «La comparecencia deberá realizarse sin demora y en todo caso en el plazo máximo de un mes desde la entrada en el territorio español o, en todo caso, desde que se produzcan los acontecimientos que justifiquen el temor fundado de persecución o daños graves.»","Art. 19.1 Ley 12/2009: «Solicitada la protección, la persona extranjera no podrá ser objeto de retorno, devolución o expulsión hasta que se resuelva sobre su solicitud o ésta no sea admitida.»","Art. 20.2 Ley 12/2009: «La no admisión a trámite prevista en este artículo deberá notificarse en el plazo máximo de un mes contado a partir de la presentación de la solicitud.»","Art. 21.4 Ley 12/2009: «Contra la resolución de inadmisión a trámite o de denegación de la solicitud se podrá, en el plazo de dos días contados desde su notificación, presentar una petición de reexamen que suspenderá los efectos de aquélla.»","Art. 23.1 Ley 12/2009: «La Oficina de Asilo y Refugio, dependiente del Ministerio del Interior, es el órgano competente para la tramitación de las solicitudes de protección internacional, sin perjuicio de las demás funciones que reglamentariamente se le atribuyan.»","Art. 24.3 Ley 12/2009: «Transcurridos seis meses desde la presentación de la solicitud sin que se haya notificado la correspondiente resolución, la misma podrá entenderse desestimada»","Art. 30.1 Ley 12/2009: «Se proporcionará a las personas solicitantes de protección internacional, siempre que carezcan de recursos económicos, los servicios sociales y de acogida necesarios con la finalidad de asegurar la satisfacción de sus necesidades básicas en condiciones de dignidad»","Art. 34 Ley 12/2009: «La presentación de las solicitudes de protección internacional se comunicará al ACNUR, quien podrá informarse de la situación de los expedientes, estar presente en las audiencias a la persona solicitante y presentar informes para su inclusión en el expediente.»","Art. 48.1 Ley 12/2009: «Los menores no acompañados solicitantes de protección internacional serán remitidos a los servicios competentes en materia de protección de menores y el hecho se pondrá en conocimiento del Ministerio Fiscal.»","Art. 34.1 LO 4/2000: «El Ministro del Interior reconocerá la condición de apátrida a los extranjeros que manifestando que carecen de nacionalidad reúnen los requisitos previstos en la Convención sobre el Estatuto de Apátridas, hecha en Nueva York el 28 de septiembre de 1954, y les expedirá la documentación prevista en el artículo 27 de la citada Convención.»","Disp. adic. segunda Ley 12/2009: «La protección temporal en caso de afluencia masiva de personas desplazadas será la prevista en el Reglamento sobre régimen de protección temporal en caso de afluencia masiva de personas desplazadas, aprobado por el Real Decreto 1325/2003, de 24 de octubre.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"La protección internacional: asilo y protección subsidiaria","blocks":[{"text":"La Ley 12/2009, dictada conforme al artículo 13.4 CE, fija los términos en que los nacionales de países no comunitarios y los apátridas pueden gozar en España de la protección internacional, que comprende el derecho de asilo y la protección subsidiaria (art. 1). El asilo es la protección que se dispensa a quienes se reconoce la condición de refugiado según la propia ley y la Convención de Ginebra de 28 de julio de 1951 y su Protocolo de Nueva York de 31 de enero de 1967 (art. 2).","refs":[{"ref":"Art. 1 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"tiene por objeto establecer los términos en que las personas nacionales de países no comunitarios y las apátridas podrán gozar en España de la protección internacional constituida por el derecho de asilo y la protección subsidiaria"},{"ref":"Art. 2 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"El derecho de asilo es la protección dispensada a los nacionales no comunitarios o a los apátridas a quienes se reconozca la condición de refugiado en los términos definidos en el artículo 3 de esta Ley y en la Convención sobre el Estatuto de los Refugiados, hecha en Ginebra el 28 de julio de 1951, y su Protocolo, suscrito en Nueva York el 31 de enero de 1967."}]},{"text":"Es refugiado quien, por fundados temores de ser perseguido por motivos de raza, religión, nacionalidad, opiniones políticas, pertenencia a determinado grupo social, de género, orientación sexual o identidad sexual, está fuera del país de su nacionalidad y no puede o no quiere acogerse a su protección (art. 3). La protección subsidiaria se dispensa a quien, sin reunir los requisitos del asilo, se enfrentaría a un riesgo real de sufrir daños graves si regresase a su país (art. 4). Ambas consisten en la no devolución ni expulsión y en los derechos del art. 36 (art. 5).","refs":[{"ref":"Art. 3 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"debido a fundados temores de ser perseguida por motivos de raza, religión, nacionalidad, opiniones políticas, pertenencia a determinado grupo social, de género, orientación sexual o de identidad sexual, se encuentra fuera del país de su nacionalidad"},{"ref":"Art. 4 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"sin reunir los requisitos para obtener el asilo o ser reconocidas como refugiadas, pero respecto de las cuales se den motivos fundados para creer que si regresasen a su país de origen"},{"ref":"Art. 5 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"La protección concedida con el derecho de asilo y la protección subsidiaria consiste en la no devolución ni expulsión de las personas a quienes se les haya reconocido"}]}]},{"n":"2","title":"Condiciones para el reconocimiento: persecución, daños graves, exclusión y denegación","blocks":[{"text":"Los actos de persecución deben ser lo bastante graves, por su naturaleza o reiteración, para constituir una violación grave de derechos fundamentales, y pueden consistir, entre otros, en violencia física o psíquica, incluida la sexual, medidas discriminatorias o penas desproporcionadas (art. 6). Para valorar los motivos, es indiferente que el solicitante posea realmente la característica que suscita la persecución si el perseguidor se la atribuye (art. 7.2). Pueden ser agentes de persecución el Estado, los partidos u organizaciones que lo controlen e incluso agentes no estatales cuando aquellos no puedan o no quieran proteger (art. 13).","refs":[{"ref":"Art. 6.2.a) Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"actos de violencia física o psíquica, incluidos los actos de violencia sexual"},{"ref":"Art. 7.2 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"será indiferente el hecho de que posea realmente la característica racial, religiosa, nacional, social o política que suscita la persecución, a condición de que el agente de persecución se la atribuya."},{"ref":"Art. 13.c) Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"agentes no estatales, cuando los agentes mencionados en los puntos anteriores, incluidas las organizaciones internacionales, no puedan o no quieran proporcionar protección efectiva"}]},{"text":"Los daños graves de la protección subsidiaria son tres: la condena a pena de muerte o el riesgo de su ejecución, la tortura y los tratos inhumanos o degradantes, y las amenazas graves contra la vida o integridad de los civiles por violencia indiscriminada en conflictos (art. 10). Quedan excluidos quienes hayan cometido delitos contra la paz, de guerra o contra la humanidad, delitos graves fuera del país de refugio o actos contrarios a las Naciones Unidas (arts. 8 y 11). Se deniega la protección a quien sea un peligro para la seguridad de España o, condenado por delito grave, una amenaza para la comunidad (arts. 9 y 12).","refs":[{"ref":"Art. 10 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"a) la condena a pena de muerte o el riesgo de su ejecución material; b) la tortura y los tratos inhumanos o degradantes en el país de origen del solicitante; c) las amenazas graves contra la vida o la integridad de los civiles motivadas por una violencia indiscriminada en situaciones de conflicto internacional o interno."},{"ref":"Art. 8.2.a) Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"han cometido un delito contra la paz, un delito de guerra o un delito contra la humanidad"},{"ref":"Art. 9 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"a) las personas que constituyan, por razones fundadas, un peligro para la seguridad de España;"}]}]},{"n":"3","title":"Presentación de la solicitud: derechos, obligaciones y efectos","blocks":[{"text":"Los nacionales no comunitarios y los apátridas presentes en España tienen derecho a solicitar protección internacional, con asistencia sanitaria, asistencia jurídica gratuita e intérprete (art. 16.1 y 2). Toda la información del procedimiento, incluido el mero hecho de haber presentado la solicitud, es confidencial (art. 16.4). La solicitud se presenta por comparecencia personal sin demora y como máximo en un mes desde la entrada o desde los hechos que justifican el temor; la entrada ilegal de quien reúna los requisitos no puede sancionarse (art. 17.2). Se formaliza mediante entrevista personal, siempre individual (art. 17.4).","refs":[{"ref":"Art. 16.1 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"Las personas nacionales no comunitarias y las apátridas presentes en territorio español tienen derecho a solicitar protección internacional en España."},{"ref":"Art. 16.4 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"Toda información relativa al procedimiento, incluido el hecho de la presentación de la solicitud, tendrá carácter confidencial."},{"ref":"Art. 17.2 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"La comparecencia deberá realizarse sin demora y en todo caso en el plazo máximo de un mes desde la entrada en el territorio español"},{"ref":"Art. 17.4 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"La solicitud se formalizará mediante entrevista personal que se realizará siempre individualmente."}]},{"text":"El solicitante tiene derecho, entre otros, a ser documentado, a que se comunique su solicitud al ACNUR y a la suspensión de cualquier devolución, expulsión o extradición; debe cooperar, aportar pruebas, dar sus huellas dactilares e informar de su domicilio (art. 18). Solicitada la protección, no puede ser objeto de retorno, devolución o expulsión hasta que se resuelva o se inadmita su solicitud (art. 19.1).","refs":[{"ref":"Art. 18.1.d) Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"a la suspensión de cualquier proceso de devolución, expulsión o extradición que pudiera afectar al solicitante"},{"ref":"Art. 19.1 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"Solicitada la protección, la persona extranjera no podrá ser objeto de retorno, devolución o expulsión hasta que se resuelva sobre su solicitud o ésta no sea admitida."}]}]},{"n":"4","title":"No admisión a trámite y solicitudes en puestos fronterizos","blocks":[{"text":"El Ministro del Interior, a propuesta de la Oficina de Asilo y Refugio, puede inadmitir por resolución motivada las solicitudes presentadas en territorio español por falta de competencia (cuando corresponda a otro Estado) o por falta de requisitos, por ejemplo si el solicitante procede de un tercer país seguro, reitera una solicitud ya denegada o es nacional de la UE (art. 20.1). La inadmisión debe notificarse en un mes desde la solicitud; si no, la solicitud queda admitida (art. 20.2). El art. 20 todavía remite al Reglamento (CE) 343/2003 y a la Directiva 2005/85/CE, normas europeas que no figuran en las fuentes de la plataforma.","refs":[{"ref":"Art. 20.1 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"El Ministro del Interior, a propuesta de la Oficina de Asilo y Refugio, podrá, mediante resolución motivada, no admitir a trámite las solicitudes"},{"ref":"Art. 20.2 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"La no admisión a trámite prevista en este artículo deberá notificarse en el plazo máximo de un mes contado a partir de la presentación de la solicitud."}]},{"text":"Si la solicitud se presenta en un puesto fronterizo por quien no reúne los requisitos de entrada, la inadmisión debe notificarse en un máximo de cuatro días (art. 21.1), plazo que también rige para denegarla en ciertos casos y que puede ampliarse hasta diez días si el ACNUR lo pide razonadamente (art. 21.2 y 3). Cabe una petición de reexamen en dos días, que suspende sus efectos (art. 21.4). Si vencen los plazos sin resolución, se sigue el procedimiento ordinario con entrada provisional (art. 21.5), y mientras tanto el solicitante permanece en las dependencias habilitadas (art. 22).","refs":[{"ref":"Art. 21.1 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"En todo caso, la resolución deberá ser notificada a la persona interesada en el plazo máximo de cuatro días desde su presentación."},{"ref":"Art. 21.3 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"se ampliará hasta un máximo de diez días por resolución del Ministro del Interior"},{"ref":"Art. 21.4 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"Contra la resolución de inadmisión a trámite o de denegación de la solicitud se podrá, en el plazo de dos días contados desde su notificación, presentar una petición de reexamen que suspenderá los efectos de aquélla."}]}]},{"n":"5","title":"Órganos y tramitación: procedimiento ordinario, urgencia y recursos","blocks":[{"text":"Tramita las solicitudes la Oficina de Asilo y Refugio, dependiente del Ministerio del Interior (art. 23.1). La Comisión Interministerial de Asilo y Refugio es un órgano colegiado adscrito a Interior con representantes de los departamentos de política exterior e interior, justicia, inmigración, acogida e igualdad (art. 23.2). Terminada la instrucción, la Comisión propone y el Ministro del Interior resuelve concediendo o denegando el asilo o la protección subsidiaria (art. 24.2). Pasados seis meses sin notificar la resolución, la solicitud puede entenderse desestimada (art. 24.3).","refs":[{"ref":"Art. 23.1 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"La Oficina de Asilo y Refugio, dependiente del Ministerio del Interior, es el órgano competente para la tramitación de las solicitudes de protección internacional"},{"ref":"Art. 24.2 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"se elevarán a estudio de la Comisión Interministerial de Asilo y Refugio, que formulará propuesta al Ministro del Interior, quien será el competente para dictar la correspondiente resolución"},{"ref":"Art. 24.3 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"Transcurridos seis meses desde la presentación de la solicitud sin que se haya notificado la correspondiente resolución, la misma podrá entenderse desestimada"}]},{"text":"Se aplica la tramitación de urgencia, entre otros casos, a solicitudes manifiestamente fundadas, de personas con necesidades específicas como los menores no acompañados, o presentadas sin justificación pasado el mes (art. 25.1); se sigue el procedimiento ordinario con los plazos reducidos a la mitad (art. 25.4). Basta con indicios suficientes de persecución o de daños graves para resolver favorablemente (art. 26.2). Las resoluciones ponen fin a la vía administrativa y admiten reposición potestativa y recurso contencioso-administrativo (art. 29.1).","refs":[{"ref":"Art. 25.1.b) Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"que hayan sido formuladas por solicitantes que presenten necesidades específicas, especialmente, por menores no acompañados"},{"ref":"Art. 25.4 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"Será de aplicación al presente procedimiento lo dispuesto en el artículo 24 de la Ley, salvo en materia de plazos que se verán reducidos a la mitad."},{"ref":"Art. 26.2 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"Para que se resuelva favorablemente la solicitud bastará que aparezcan indicios suficientes de persecución o de daños graves."}]}]},{"n":"6","title":"Condiciones de acogida y centros de acogida","blocks":[{"text":"A los solicitantes sin recursos económicos se les proporcionan los servicios sociales y de acogida necesarios para cubrir sus necesidades básicas en condiciones de dignidad (art. 30.1); si se comprueba que tienen medios, se les reclama el reembolso (art. 30.3). El Ministerio competente presta la acogida directamente, mediante contratos, por autorización de acción concertada o en centros subvencionados a organizaciones no gubernamentales (art. 31.1). La autorización de acción concertada puede alcanzar cuatro años, prorrogables de mutuo acuerdo por igual periodo. Se procura mantener la unidad familiar (art. 31.2). La ley no regula en detalle los Centros de Acogida a Refugiados: su normativa propia no está en las fuentes de la plataforma.","refs":[{"ref":"Art. 30.1 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"Se proporcionará a las personas solicitantes de protección internacional, siempre que carezcan de recursos económicos, los servicios sociales y de acogida necesarios con la finalidad de asegurar la satisfacción de sus necesidades básicas en condiciones de dignidad"},{"ref":"Art. 31.1 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"también será posible prestar los servicios de acogida a través de los centros subvencionados a organizaciones no gubernamentales."},{"ref":"Art. 31.1 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"que podrá alcanzar cuatro años prorrogables de mutuo acuerdo, por igual periodo"}]},{"text":"Los solicitantes serán autorizados a trabajar en los términos reglamentarios (art. 32). Las condiciones de acogida pueden reducirse o retirarse si el solicitante abandona sin permiso la residencia asignada, oculta recursos, ya se ha resuelto su solicitud, perturba gravemente la convivencia en el centro o termina el programa (art. 33.1).","refs":[{"ref":"Art. 32 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"Las personas solicitantes de protección internacional serán autorizadas para trabajar en España en los términos que reglamentariamente se establezcan."},{"ref":"Art. 33.1.a) Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"cuando la persona solicitante abandone el lugar de residencia asignado sin informar a la autoridad competente"}]}]},{"n":"7","title":"Intervención del ACNUR y efectos de la resolución","blocks":[{"text":"La presentación de las solicitudes se comunica al ACNUR, que puede informarse de los expedientes, estar presente en las audiencias y presentar informes, con acceso a los solicitantes incluso en dependencias fronterizas, CIE o centros penitenciarios (art. 34). La concesión supone, entre otros derechos, la protección contra la devolución, la autorización de residencia y trabajo permanente, documentos de identidad y viaje, la libertad de circulación y el acceso a educación, sanidad, vivienda y servicios sociales en las mismas condiciones que los españoles (art. 36.1).","refs":[{"ref":"Art. 34 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"La presentación de las solicitudes de protección internacional se comunicará al ACNUR, quien podrá informarse de la situación de los expedientes, estar presente en las audiencias a la persona solicitante y presentar informes para su inclusión en el expediente."},{"ref":"Art. 36.1.c) Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"la autorización de residencia y trabajo permanente"}]},{"text":"La inadmisión o denegación determina el retorno, la devolución, la expulsión, la salida obligatoria o el traslado al Estado responsable, salvo que la persona pueda quedarse por estancia o residencia o por razones humanitarias (art. 37). Fuera de España, los Embajadores pueden promover el traslado a España del solicitante que corra peligro para que presente la solicitud (art. 38).","refs":[{"ref":"Art. 37 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"determinarán, según corresponda, el retorno, la devolución, la expulsión, la salida obligatoria del territorio español o el traslado al territorio del Estado responsable del examen de la solicitud de asilo"},{"ref":"Art. 38 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"los Embajadores de España podrán promover el traslado del o de los solicitantes de asilo a España"}]}]},{"n":"8","title":"De los menores y otras personas vulnerables","blocks":[{"text":"Se tiene en cuenta la situación específica de las personas vulnerables, como menores, menores no acompañados, personas con discapacidad o de edad avanzada, mujeres embarazadas, familias monoparentales, víctimas de torturas, violaciones u otras formas graves de violencia y víctimas de trata de seres humanos, con un tratamiento diferenciado de sus solicitudes (art. 46.1 y 2). Los menores víctimas de abusos, explotación, tortura o conflictos armados reciben la asistencia sanitaria y psicológica adecuada (art. 47).","refs":[{"ref":"Art. 46.1 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"familias monoparentales con menores de edad, personas que hayan padecido torturas, violaciones u otras formas graves de violencia psicológica o física o sexual y víctimas de trata de seres humanos."},{"ref":"Art. 47 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"recibirán la asistencia sanitaria y psicológica adecuada y la asistencia cualificada que precisen."}]},{"text":"Los menores no acompañados solicitantes se remiten a los servicios de protección de menores y se informa al Ministerio Fiscal (art. 48.1). Si la minoría de edad no puede establecerse con seguridad, el Ministerio Fiscal dispone lo necesario para determinar la edad, con pruebas científicas prioritarias y urgentes de las instituciones sanitarias (art. 48.2). Además, se nombra un representante que actúe en nombre del menor (art. 48.3).","refs":[{"ref":"Art. 48.1 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"Los menores no acompañados solicitantes de protección internacional serán remitidos a los servicios competentes en materia de protección de menores y el hecho se pondrá en conocimiento del Ministerio Fiscal."},{"ref":"Art. 48.2 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"se pondrá el hecho en conocimiento inmediato del Ministerio Fiscal, que dispondrá lo necesario para la determinación de la edad del presunto menor"}]}]},{"n":"9","title":"Apátridas y desplazados","blocks":[{"text":"El Ministro del Interior reconoce la condición de apátrida a los extranjeros que, manifestando carecer de nacionalidad, reúnen los requisitos de la Convención de Nueva York de 28 de septiembre de 1954, y les expide la documentación del artículo 27 de esa Convención (art. 34.1 LO 4/2000). El indocumentado que no puede ser documentado por ningún país puede obtener, por razones excepcionales, un documento identificativo (art. 34.2). El art. 34.3 de la LO 4/2000 aún remite a la Ley 5/1984 de asilo, derogada por la Ley 12/2009.","refs":[{"ref":"Art. 34.1 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"El Ministro del Interior reconocerá la condición de apátrida a los extranjeros que manifestando que carecen de nacionalidad reúnen los requisitos previstos en la Convención sobre el Estatuto de Apátridas, hecha en Nueva York el 28 de septiembre de 1954"},{"ref":"Art. 34.3 LOEX","law":"LO 4/2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","quote":"Ley 5/1984, de 26 de marzo, reguladora del derecho de asilo y de la condición de refugiado"}]},{"text":"La protección temporal en caso de afluencia masiva de personas desplazadas es la del Reglamento aprobado por el Real Decreto 1325/2003, de 24 de octubre (disposición adicional segunda de la Ley 12/2009). Ese reglamento no está en las fuentes de la plataforma, por lo que su contenido no se desarrolla aquí.","refs":[{"ref":"Disp. adic. segunda Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"La protección temporal en caso de afluencia masiva de personas desplazadas será la prevista en el Reglamento sobre régimen de protección temporal en caso de afluencia masiva de personas desplazadas, aprobado por el Real Decreto 1325/2003, de 24 de octubre."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Asilo: condición de refugiado según la Convención de Ginebra de 1951 y el Protocolo de Nueva York de 1967; la orientación sexual y el género son motivos de persecución.","refs":[{"ref":"Art. 3 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"de género, orientación sexual o de identidad sexual"}]},{"text":"Protección subsidiaria: riesgo real de daños graves (pena de muerte, tortura, violencia indiscriminada).","refs":[{"ref":"Art. 10.a) Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"la condena a pena de muerte o el riesgo de su ejecución material"}]},{"text":"Solicitar en un mes como máximo desde la entrada; entrevista siempre individual; todo es confidencial.","refs":[{"ref":"Art. 17.2 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"en el plazo máximo de un mes desde la entrada en el territorio español"}]},{"text":"Plazos: inadmisión en territorio, un mes; en frontera, cuatro días (ampliable a diez); reexamen, dos días.","refs":[{"ref":"Art. 21.4 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"en el plazo de dos días contados desde su notificación"}]},{"text":"Tramita la Oficina de Asilo y Refugio; propone la Comisión Interministerial; resuelve el Ministro del Interior.","refs":[{"ref":"Art. 23.1 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"La Oficina de Asilo y Refugio, dependiente del Ministerio del Interior"}]},{"text":"Silencio de seis meses: desestimación. Urgencia: plazos reducidos a la mitad.","refs":[{"ref":"Art. 25.4 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"plazos que se verán reducidos a la mitad"}]},{"text":"Acción concertada de acogida: hasta cuatro años, prorrogables por igual periodo.","refs":[{"ref":"Art. 31.1 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"que podrá alcanzar cuatro años prorrogables de mutuo acuerdo"}]},{"text":"Menor no acompañado o edad dudosa: Ministerio Fiscal. Apátridas: los reconoce el Ministro del Interior. Desplazados: RD 1325/2003.","refs":[{"ref":"Art. 48.2 Ley 12/2009","law":"Ley 12/2009","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242","quote":"que dispondrá lo necesario para la determinación de la edad del presunto menor"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242', null, null, null, 'Otras normas citadas: LO 4/2000 (https://www.boe.es/buscar/act.php?id=BOE-A-2000-544)'
  from public.topics t where t.slug = 'pn-12-proteccion-internacional'
