insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 8/2011, de 28 de abril, medidas para la protección de las infraestructuras críticas (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-7630', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-15-infraestructuras-criticas', 'Tema 15. Protección de infraestructuras críticas y ciberseguridad') on conflict (slug) do nothing;
