insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 4/2015, de 27 de abril, del Estatuto de la víctima del delito (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-4606', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
