insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 7/2021, de 26 de mayo, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2021-8806', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-26-proteccion-datos', 'Tema 26. La protección de datos personales: LO 3/2018 y LO 7/2021') on conflict (slug) do nothing;
