insert into public.sources (title, url, kind, publisher, published_on) values ('FMI · La globalización: ¿Amenaza u oportunidad? (estudio temático, abril de 2000)', 'https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm', 'web_oficial'::public.source_kind, 'Fondo Monetario Internacional (organismo de las Naciones Unidas)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-28-globalizacion', 'Tema 28. Globalización y antiglobalización: conceptos, características, consecuencias, reacciones, movimiento antiglobalización y Foro Social Mundial') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-28-globalizacion' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Concepto de globalización: definición del FMI y acepciones del DLE"},{"n":"2","title":"Características: comercio exterior, movimientos de capital, migraciones y difusión de los conocimientos"},{"n":"3","title":"Consecuencias: crecimiento, desigualdades entre regiones y soberanía nacional"},{"n":"4","title":"Reacciones: antiglobalización y altermundismo"},{"n":"5","title":"Por una globalización justa (OIT, 2004): gobernanza, enfoque centrado en las personas y Foro Social Mundial"}]'::jsonb, '["FMI, ¿Qué es la globalización? FMI, «La globalización: ¿Amenaza u oportunidad?»: «La \"globalización\" económica es un proceso histórico, el resultado de la innovación humana y el progreso tecnológico. Se refiere a la creciente integración de las economías de todo el mundo, especialmente a través del comercio y los flujos financieros.»","FMI, ¿Qué es la globalización? FMI, «La globalización: ¿Amenaza u oportunidad?»: «El uso de este término se utiliza comúnmente desde los años ochenta, es decir, desde que los adelantos tecnológicos han facilitado y acelerado las transacciones internacionales comerciales y financieras.»","DLE, globalización 3 DLE (RAE): «Difusión mundial de modos, valores o tendencias que fomenta la uniformidad de gustos y costumbres.»","DLE, globalización 4 DLE (RAE): «Proceso por el que las economías y mercados, con el desarrollo de las tecnologías de la comunicación, adquieren una dimensión mundial, de modo que dependen cada vez más de los mercados externos y menos de la acción reguladora de los Gobiernos.»","FMI, Aspectos de la globalización FMI, «La globalización: ¿Amenaza u oportunidad?»: «Considérense cuatro aspectos de la globalización:»","FMI, Comercio exterior FMI, «La globalización: ¿Amenaza u oportunidad?»: «La participación del conjunto de países en desarrollo en el comercio mundial aumentó del 19% en 1971 al 29% en 1999.»","FMI, Movimientos de capital FMI, «La globalización: ¿Amenaza u oportunidad?»: «La inversión extranjera directa ha pasado a ser la categoría más importante.»","FMI, Migraciones FMI, «La globalización: ¿Amenaza u oportunidad?»: «Los trabajadores se desplazan de un país a otro en parte en busca de mejores oportunidades de empleo.»","FMI, Evolución en el siglo XX FMI, «La globalización: ¿Amenaza u oportunidad?»: «En el siglo XX hubo un crecimiento económico sin precedente, que casi quintuplicó el PIB mundial per cápita.»","FMI, Evolución en el siglo XX FMI, «La globalización: ¿Amenaza u oportunidad?»: «el crecimiento del ingreso per cápita se redujo a menos del 1% entre 1913 y 1950.»","FMI, Recuadro 1 FMI, «La globalización: ¿Amenaza u oportunidad?»: «En resumen, la globalización no reduce la soberanía nacional. Crea fuertes incentivos para que los países apliquen políticas económicas correctas.»","DLE, antiglobalización 1.b DLE (RAE): «Conjunto de movimientos sociales contrarios a la globalización económica.»","DLE, altermundismo DLE (RAE): «Movimiento reformista heterogéneo que se opone a la globalización del neoliberalismo y aboga por modelos económicos y sociales alternativos.»","OIT, Sinopsis OIT, «Por una globalización justa» (2004): «Consideramos que los problemas que hemos descrito no se deben a la globalización en sí, sino a deficiencias en su gobernanza.»","OIT, Sinopsis OIT, «Por una globalización justa» (2004): «Un enfoque centrado en las personas. La piedra angular de una globalización más justa es la satisfacción de las demandas de todas las personas en lo que atañe al»","OIT, párr. 119 OIT, «Por una globalización justa» (2004): «También se consideró que un debate con el Foro Social Mundial podría beneficiar a ambas partes.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Concepto de globalización según el FMI","blocks":[{"text":"Para el Fondo Monetario Internacional (FMI), en su estudio «La globalización: ¿Amenaza u oportunidad?» (abril de 2000), la globalización económica es un proceso histórico, resultado de la innovación humana y el progreso tecnológico. Se refiere a la creciente integración de las economías de todo el mundo, especialmente a través del comercio y los flujos financieros, y a veces también al desplazamiento de personas (mano de obra) y a la transferencia de conocimientos (tecnología) entre países. Abarca además aspectos culturales, políticos y ambientales que el FMI no analiza.","refs":[{"ref":"FMI, ¿Qué es la globalización?","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"La \"globalización\" económica es un proceso histórico, el resultado de la innovación humana y el progreso tecnológico. Se refiere a la creciente integración de las economías de todo el mundo, especialmente a través del comercio y los flujos financieros."},{"ref":"FMI, ¿Qué es la globalización?","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"En algunos casos este término hace alusión al desplazamiento de personas (mano de obra) y la transferencia de conocimientos (tecnología) a través de las fronteras internacionales. La globalización abarca además aspectos culturales, políticos y ambientales más amplios que no se analizan en esta nota."}]},{"text":"El término se usa comúnmente desde los años ochenta, cuando los adelantos tecnológicos facilitaron y aceleraron las transacciones internacionales comerciales y financieras. En el fondo, es la prolongación más allá de las fronteras nacionales de las mismas fuerzas del mercado que durante siglos han actuado en mercados rurales, industrias urbanas o centros financieros. Los mercados promueven la eficiencia mediante la competencia y la división del trabajo, pero no garantizan que esa eficiencia beneficie a todos.","refs":[{"ref":"FMI, ¿Qué es la globalización?","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"El uso de este término se utiliza comúnmente desde los años ochenta, es decir, desde que los adelantos tecnológicos han facilitado y acelerado las transacciones internacionales comerciales y financieras."},{"ref":"FMI, ¿Qué es la globalización?","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"Pero los mercados no garantizan necesariamente que la mayor eficiencia beneficiará a todos."}]}]},{"n":"2","title":"Acepciones de globalización en el Diccionario de la lengua española","blocks":[{"text":"El DLE recoge cuatro acepciones: 1) acción de globalizar; 2) extensión del ámbito propio de instituciones sociales, políticas y jurídicas a un plano internacional (con el ejemplo del Tribunal Penal Internacional); 3) difusión mundial de modos, valores o tendencias que fomenta la uniformidad de gustos y costumbres (la dimensión cultural); y 4) en Economía, proceso por el que las economías y mercados, con el desarrollo de las tecnologías de la comunicación, adquieren una dimensión mundial y dependen cada vez más de los mercados externos y menos de la acción reguladora de los Gobiernos.","refs":[{"ref":"DLE, globalización 2 y 3","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"Extensión del ámbito propio de instituciones sociales, políticas y jurídicas a un plano internacional.El Tribunal Penal Internacional es un efecto de la globalización.3. f. Difusión mundial de modos, valores o tendencias que fomenta la uniformidad de gustos y costumbres."},{"ref":"DLE, globalización 4","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"Proceso por el que las economías y mercados, con el desarrollo de las tecnologías de la comunicación, adquieren una dimensión mundial, de modo que dependen cada vez más de los mercados externos y menos de la acción reguladora de los Gobiernos."}]}]},{"n":"3","title":"La globalización como proceso histórico: el siglo XX","blocks":[{"text":"La globalización no es un fenómeno reciente: algunos analistas sostienen que la economía mundial estaba tan globalizada hace cien años como hoy. Lo nuevo es el grado de desarrollo e integración del comercio y los servicios financieros, sobre todo la integración de los mercados financieros gracias a las comunicaciones electrónicas.","refs":[{"ref":"FMI, Crecimiento sin precedente","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"La globalización no es un fenómeno reciente. Algunos analistas sostienen que la economía mundial estaba tan globalizada hace 100 años como hoy."},{"ref":"FMI, Crecimiento sin precedente","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"El aspecto más sorprendente de este proceso es la integración de los mercados financieros, que ha sido posible gracias a las comunicaciones electrónicas modernas."}]},{"text":"En el siglo XX hubo un crecimiento sin precedente que casi quintuplicó el PIB mundial per cápita, concentrado en la segunda mitad del siglo, con expansión y liberalización del comercio. En cambio, entre las dos guerras mundiales los países cerraron su economía con proteccionismo y control de capitales, y el crecimiento del ingreso per cápita cayó a menos del 1 % entre 1913 y 1950. En el resto del siglo superó el 2 %.","refs":[{"ref":"FMI, Evolución en el siglo XX","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"En el siglo XX hubo un crecimiento económico sin precedente, que casi quintuplicó el PIB mundial per cápita."},{"ref":"FMI, Evolución en el siglo XX","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"los países cerraron su economía y adoptaron medidas proteccionistas y un control generalizado de los capitales. Este fue el principal factor determinante de los devastadores resultados de ese período: el crecimiento del ingreso per cápita se redujo a menos del 1% entre 1913 y 1950."}]}]},{"n":"4","title":"Características: comercio exterior y movimientos de capital","blocks":[{"text":"El FMI describe cuatro aspectos o características de la globalización: comercio exterior, movimientos de capital, migraciones y difusión de los conocimientos y la tecnología. En el comercio exterior, la participación de los países en desarrollo en el comercio mundial pasó del 19 % en 1971 al 29 % en 1999, con grandes diferencias regionales: buenos resultados de las economías asiáticas recientemente industrializadas y desempeño mediocre de África. Crecieron sobre todo las exportaciones de manufacturas, mientras caía el peso de los productos primarios, que suelen venir de los países más pobres.","refs":[{"ref":"FMI, Aspectos de la globalización","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"Considérense cuatro aspectos de la globalización: […] Comercio exterior. […] Movimientos de capital. […] Migraciones. […] Difusión de los conocimientos (y la tecnología)."},{"ref":"FMI, Comercio exterior","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"La participación del conjunto de países en desarrollo en el comercio mundial aumentó del 19% en 1971 al 29% en 1999."}]},{"text":"En cuanto al capital, en los años noventa hubo un fuerte aumento de los flujos privados hacia los países en desarrollo, tras una década de flujos limitados, mientras la ayuda oficial al desarrollo disminuía desde principios de los ochenta. La inversión extranjera directa pasó a ser la categoría más importante; la inversión de cartera y el crédito bancario crecieron, pero fueron más inestables y cayeron con las crisis de finales de los noventa.","refs":[{"ref":"FMI, Movimientos de capital","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"La inversión extranjera directa ha pasado a ser la categoría más importante. La inversión de cartera y el crédito bancario aumentaron, pero han mostrado mayor inestabilidad"},{"ref":"FMI, Movimientos de capital","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"los flujos oficiales netos de \"ayuda\" o asistencia para el desarrollo disminuyeron considerablemente desde principios de los años ochenta"}]}]},{"n":"5","title":"Características: migraciones y difusión de los conocimientos","blocks":[{"text":"Los trabajadores se desplazan de un país a otro en parte en busca de mejores oportunidades de empleo. Su número es todavía pequeño, aunque entre 1965 y 1990 la mano de obra extranjera aumentó alrededor del 50 % en todo el mundo, y la mayor parte de las migraciones se produjeron entre países en desarrollo. La corriente hacia las economías avanzadas probablemente favorezca una convergencia mundial de los salarios.","refs":[{"ref":"FMI, Migraciones","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"Los trabajadores se desplazan de un país a otro en parte en busca de mejores oportunidades de empleo. El número de personas en esta situación aún es bastante pequeño, pero en el período 1965-90 la mano de obra extranjera aumentó alrededor del 50% en todo el mundo. La mayor parte de las migraciones se produjeron entre países en desarrollo."}]},{"text":"La difusión de los conocimientos es un aspecto que a menudo se pasa por alto. La inversión extranjera directa trae capital físico, pero también innovación técnica, y la información sobre métodos de producción, gestión, mercados y políticas económicas está disponible a muy bajo coste, lo que es un recurso valioso para los países en desarrollo.","refs":[{"ref":"FMI, Difusión de los conocimientos","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"El intercambio de información es un aspecto de la globalización que a menudo se pasa por alto. Por ejemplo, la inversión extranjera directa da lugar no sólo a una expansión del capital físico sino también a la innovación técnica."}]}]},{"n":"6","title":"Consecuencias: crecimiento y desigualdades entre regiones","blocks":[{"text":"La globalización ofrece grandes oportunidades, pero no avanza de manera uniforme. Los países que se integran crecen más deprisa y reducen la pobreza: la mayoría de los de Asia oriental, entre los más pobres hace cuarenta años, se han vuelto dinámicos y prósperos con políticas de apertura. En cambio, muchos países de América Latina y África aplicaron en los setenta y ochenta políticas orientadas hacia el interior y su economía se estancó.","refs":[{"ref":"FMI, Introducción","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"La globalización ofrece grandes oportunidades de alcanzar un desarrollo verdaderamente mundial, pero no está avanzando de manera uniforme."},{"ref":"FMI, Introducción","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"En los países que han logrado integrarse, el crecimiento económico es más rápido y la pobreza disminuye."}]},{"text":"El crecimiento del siglo XX no se repartió por igual: se amplió la brecha entre países ricos y pobres y dentro de cada país. Para la cuarta parte más rica de la población mundial el PIB per cápita casi se sextuplicó, y para la cuarta parte más pobre no llegó a triplicarse. Sin embargo, con indicadores de desarrollo humano (educación, esperanza de vida) los países pobres han avanzado considerablemente. El FMI concluye que es erróneo atribuir sin más esa divergencia a la globalización.","refs":[{"ref":"FMI, Tendencias del ingreso","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"Para la cuarta parte de la población mundial más rica el PIB per cápita casi se sextuplicó durante el siglo, en tanto que para la cuarta parte más pobre no llegó a triplicarse"},{"ref":"FMI, Conclusión","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"es erróneo concluir sin más que la globalización ha sido la causa de esta divergencia"}]},{"text":"Para que los países más pobres recuperen terreno, el FMI considera tan importantes como las transferencias financieras la estabilidad económica, el desarrollo institucional y la reforma estructural. Enumera la estabilidad macroeconómica, la apertura al exterior, las reformas que estimulen la competencia, instituciones sólidas y buen gobierno, la educación y la investigación, y una gestión de la deuda externa que permita el desarrollo sostenible, dentro de estrategias nacionales contra la pobreza.","refs":[{"ref":"FMI, Cómo recuperar el terreno perdido","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"La estabilidad económica, el desarrollo institucional y la reforma estructural son al menos tan importantes para el desarrollo a largo plazo como las transferencias financieras, con todo lo indispensables que éstas puedan ser."},{"ref":"FMI, Cómo recuperar el terreno perdido","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"Instituciones sólidas y una administración eficaz que propenda al buen gobierno."}]}]},{"n":"7","title":"Consecuencias: trabajadores, crisis financieras y soberanía nacional","blocks":[{"text":"En las economías avanzadas preocupa la pérdida de empleo y la competencia de las «economías de bajos salarios». Según el FMI, la globalización genera más crecimiento, empleo y bienestar que una economía cerrada, pero sus beneficios no se reparten de forma uniforme; por eso propone educación y formación profesional y protección para quienes pierden su empleo. Las crisis de los noventa (México, Tailandia, Indonesia, Corea, Rusia y Brasil) mostraron el riesgo de la volatilidad de los flujos de capital.","refs":[{"ref":"FMI, Trabajadores de los países avanzados","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"Sin embargo, en la generalidad de los casos estos beneficios no se distribuyen de manera uniforme entre los grupos de población, y algunos de estos grupos posiblemente queden totalmente al margen."},{"ref":"FMI, Crisis periódicas","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"La sucesión de crisis financieras de los años noventa --México, Tailandia, Indonesia, Corea, Rusia y Brasil-- llevan a pensar que algunas de ellas son el resultado directo e inevitable de la globalización."}]},{"text":"Sobre la soberanía nacional, el FMI sostiene que la globalización no la reduce, sino que crea fuertes incentivos para que los países apliquen políticas económicas correctas, aunque los flujos de corto plazo pueden ser excesivamente inestables. Pide a los países avanzados que apoyen a los pobres: en 1998 su asistencia oficial para el desarrollo se redujo al 0,24 % del PIB, frente al objetivo del 0,7 % de Naciones Unidas.","refs":[{"ref":"FMI, Recuadro 1","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"En resumen, la globalización no reduce la soberanía nacional. Crea fuertes incentivos para que los países apliquen políticas económicas correctas."},{"ref":"FMI, Respuesta de la comunidad internacional","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"En los países avanzados la asistencia oficial para el desarrollo se redujo al 0,24% del PIB (1998), frente al objetivo del 0,7% previsto por Naciones Unidas."}]}]},{"n":"8","title":"Reacciones a la globalización: antiglobalización y altermundismo","blocks":[{"text":"La globalización ha adquirido una fuerte carga emotiva. Unos la consideran beneficiosa, inevitable e irreversible; otros la ven con hostilidad o temor porque creen que aumenta la desigualdad, amenaza el empleo y obstaculiza el progreso social. El DLE llama antiglobalización al conjunto de movimientos sociales contrarios a la globalización económica, y altermundismo al movimiento reformista heterogéneo que se opone a la globalización del neoliberalismo y aboga por modelos económicos y sociales alternativos; altermundista es su partidario.","refs":[{"ref":"FMI, Introducción","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"Otros la ven con hostilidad, incluso temor, debido a que consideran que suscita una mayor desigualdad dentro de cada país y entre los distintos países, amenaza el empleo y las condiciones de vida y obstaculiza el progreso social."},{"ref":"DLE, antiglobalización 1.b","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"Conjunto de movimientos sociales contrarios a la globalización económica."},{"ref":"DLE, altermundismo","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"Movimiento reformista heterogéneo que se opone a la globalización del neoliberalismo y aboga por modelos económicos y sociales alternativos."}]},{"text":"El epígrafe pide también las organizaciones, objetivos e historia del movimiento antiglobalización; las fuentes oficiales de la plataforma no los describen, por lo que esa parte no se desarrolla aquí. Sí consta que, según la OIT, el debate público sobre la globalización estaba en un punto muerto, con opiniones reducidas a certezas ideológicas.","refs":[{"ref":"OIT, Una visión del cambio","law":"OIT, «Por una globalización justa» (2004)","url":"https://webapps.ilo.org/public/spanish/wcsdg/docs/report.pdf","quote":"El debate público sobre la globalización se encuentra en un punto muerto."}]}]},{"n":"9","title":"Por una globalización justa (OIT, 2004)","blocks":[{"text":"La Comisión Mundial sobre la Dimensión Social de la Globalización, creada en la OIT, publicó en 2004 «Por una globalización justa: crear oportunidades para todos». Estuvo copresidida por dos Jefes de Estado en ejercicio, un hombre y una mujer, la una del Norte y el otro del Sur, e integrada por miembros de gobiernos, empresas, sindicatos, universidades y sociedad civil. Su tesis central es que los problemas no se deben a la globalización en sí, sino a deficiencias en su gobernanza: mercados globales crecidos sin las instituciones necesarias y reglas de comercio y finanzas poco equitativas.","refs":[{"ref":"OIT, Introducción","law":"OIT, «Por una globalización justa» (2004)","url":"https://webapps.ilo.org/public/spanish/wcsdg/docs/report.pdf","quote":"Copresidida por dos Jefes de Estado en ejercicio, un hombre y una mujer, la una del Norte y el otro del Sur"},{"ref":"OIT, La gobernanza de la globalización","law":"OIT, «Por una globalización justa» (2004)","url":"https://webapps.ilo.org/public/spanish/wcsdg/docs/report.pdf","quote":"Consideramos que los problemas que hemos descrito no se deben a la globalización en sí, sino a deficiencias en su gobernanza."}]},{"text":"La Comisión pide una globalización con fuerte dimensión social, basada en valores universales y en los derechos humanos. Su primera propuesta es un enfoque centrado en las personas: la piedra angular de una globalización más justa es satisfacer las demandas de todas las personas en cuanto al respeto de sus derechos, identidad cultural y autonomía, al trabajo decente y a la implicación de sus comunidades. Añade un Estado democrático y eficaz, desarrollo sostenible, mercados productivos y equitativos, reglas justas, una globalización solidaria y unas Naciones Unidas eficaces.","refs":[{"ref":"OIT, Una visión del cambio","law":"OIT, «Por una globalización justa» (2004)","url":"https://webapps.ilo.org/public/spanish/wcsdg/docs/report.pdf","quote":"Un enfoque centrado en las personas. La piedra angular de una globalización más justa es la satisfacción de las demandas de todas las personas en lo que atañe al"},{"ref":"OIT, Una visión del cambio","law":"OIT, «Por una globalización justa» (2004)","url":"https://webapps.ilo.org/public/spanish/wcsdg/docs/report.pdf","quote":"Un estado democrático y eficaz."},{"ref":"OIT, Una visión del cambio","law":"OIT, «Por una globalización justa» (2004)","url":"https://webapps.ilo.org/public/spanish/wcsdg/docs/report.pdf","quote":"Unas Naciones Unidas eficaces."}]}]},{"n":"10","title":"El Foro Social Mundial","blocks":[{"text":"Las fuentes de la plataforma solo mencionan el Foro Social Mundial en el informe de la OIT, que no explica su origen ni su organización. Según el informe, muchos aspectos de la globalización se examinan en foros como el Foro Económico Mundial y el Foro Social Mundial. En el debate que la Comisión mantuvo con el Foro Económico Mundial en Davos se detectó preocupación por una posible reacción contra la globalización, y se consideró que un debate con el Foro Social Mundial podría beneficiar a ambas partes.","refs":[{"ref":"OIT, nota 113","law":"OIT, «Por una globalización justa» (2004)","url":"https://webapps.ilo.org/public/spanish/wcsdg/docs/report.pdf","quote":"Muchos aspectos relacionados con la globalización ya están siendo examinados en diversos foros, como el Foro Económico Mundial y el Foro Social Mundial."},{"ref":"OIT, párr. 119","law":"OIT, «Por una globalización justa» (2004)","url":"https://webapps.ilo.org/public/spanish/wcsdg/docs/report.pdf","quote":"Existía preocupación por una posible reacción contra la […] y los efectos perjudiciales que podría entrañar. También se consideró que un debate con el Foro Social Mundial podría beneficiar a ambas partes."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"FMI: la globalización integra las economías sobre todo mediante el comercio y los flujos financieros; el término se usa desde los años ochenta.","refs":[{"ref":"FMI, ¿Qué es la globalización?","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"especialmente a través del comercio y los flujos financieros."}]},{"text":"DLE, acepción 3: difusión mundial de modos, valores o tendencias que fomenta la uniformidad de gustos y costumbres.","refs":[{"ref":"DLE, globalización 3","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"Difusión mundial de modos, valores o tendencias que fomenta la uniformidad de gustos y costumbres."}]},{"text":"Cuatro aspectos (FMI): comercio exterior, movimientos de capital, migraciones y difusión de los conocimientos.","refs":[{"ref":"FMI, Aspectos de la globalización","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"Considérense cuatro aspectos de la globalización:"}]},{"text":"Países en desarrollo en el comercio mundial: del 19 % (1971) al 29 % (1999); la inversión extranjera directa es la principal categoría de capital privado.","refs":[{"ref":"FMI, Movimientos de capital","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"La inversión extranjera directa ha pasado a ser la categoría más importante."}]},{"text":"Siglo XX: PIB mundial per cápita casi quintuplicado; entre 1913 y 1950, crecimiento inferior al 1 %.","refs":[{"ref":"FMI, Evolución en el siglo XX","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"que casi quintuplicó el PIB mundial per cápita."}]},{"text":"Antiglobalización: movimientos sociales contrarios a la globalización económica; altermundismo: propone modelos alternativos.","refs":[{"ref":"DLE, antiglobalización 1.b","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"Conjunto de movimientos sociales contrarios a la globalización económica."}]},{"text":"Según el FMI, la globalización no reduce la soberanía nacional.","refs":[{"ref":"FMI, Recuadro 1","law":"FMI, «La globalización: ¿Amenaza u oportunidad?»","url":"https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm","quote":"la globalización no reduce la soberanía nacional."}]},{"text":"OIT 2004: los problemas se deben a deficiencias en la gobernanza; un debate con el Foro Social Mundial podría beneficiar a ambas partes.","refs":[{"ref":"OIT, párr. 119","law":"OIT, «Por una globalización justa» (2004)","url":"https://webapps.ilo.org/public/spanish/wcsdg/docs/report.pdf","quote":"un debate con el Foro Social Mundial podría beneficiar a ambas partes."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm'), 'https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm', null, null, null, 'Otras normas citadas: DLE (RAE) (https://dle.rae.es/), OIT, «Por una globalización justa» (2004) (https://webapps.ilo.org/public/spanish/wcsdg/docs/report.pdf)'
  from public.topics t where t.slug = 'pn-28-globalizacion'
