insert into public.sources (title, url, kind, publisher, published_on) values ('Instituto Geográfico Nacional · Glosario del Atlas Didáctico (términos de geografía de la población, urbana, económica y medio ambiente)', 'https://educativo.ign.es/atlas-didactico/glosario/index.html', 'web_oficial'::public.source_kind, 'Instituto Geográfico Nacional (IGN-CNIG), recurso educativo oficial (CC BY 4.0)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-32-geografia-demografia', 'Tema 32. Geografía humana: la ciudad, la población y la demografía; contaminación y protección del medio ambiente') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-32-geografia-demografia' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"La población: densidad, natalidad, mortalidad y crecimiento"},{"n":"2","title":"Estructura de la población: pirámides y envejecimiento"},{"n":"3","title":"Transición demográfica y fuentes (padrón, censo)"},{"n":"4","title":"La ciudad: concepto, criterios, morfología y planos urbanos"},{"n":"5","title":"Procesos urbanos: éxodo rural, conurbación, ciudad dormitorio, tasa de urbanización"},{"n":"6","title":"Contaminación y medio ambiente: efecto invernadero y lluvia ácida"}]'::jsonb, '["IGN, Glosario: Densidad de población IGN, Glosario del Atlas Didáctico: «Relación entre la población total de un área y su superficie (d = P/S), expresada normalmente en habitantes por km2 (hab./km2).»","IGN, Glosario: Crecimiento natural o vegetativo IGN, Glosario del Atlas Didáctico: «Variación positiva o negativa de la población de un lugar debido a su movimiento natural (natalidad y mortalidad).»","IGN, Atlas Didáctico: Pirámides de población IGN, Atlas Didáctico (población, migraciones y ciudades): «La forma de representar la estructura por edades es la pirámide de población, donde los grupos de edad más jóvenes están en la base, y los grupos de edad mayores están en el vértice.»","IGN, Atlas Didáctico: Tipos de planos urbanos IGN, Atlas Didáctico (población, migraciones y ciudades): «En damero, ortogonal o en cuadrícula Las calles se cortan de manera perpendicular. Por ejemplo, se corresponde con la mayoría de los ensanches de las ciudades españolas.»","IGN, Glosario: Éxodo rural IGN, Glosario del Atlas Didáctico: «Desplazamiento masivo de la población residente en el medio rural hacia las ciudades.»","IGN, Glosario: Padrón IGN, Glosario del Atlas Didáctico: «Registro administrativo donde constan los vecinos del municipio y sus características básicas (edad, sexo, actividad profesional, domicilio...). Sus datos constituyen prueba de residencia en el municipio y del domicilio habitual en el mismo.»","IGN, Glosario: Tasa bruta de natalidad IGN, Glosario del Atlas Didáctico: «Se calcula dividiendo el número de nacimientos ocurridos durante un periodo determinado entre la población total de ese mismo periodo. El resultado se multiplica por mil.»","IGN, Glosario: Transición demográfica IGN, Glosario del Atlas Didáctico: «Proceso demográfico histórico por el que se pasa de un régimen demográfico antiguo caracterizado por unas altas tasas de natalidad y mortalidad, a un régimen demográfico moderno, con valores muy bajos de ambas tasas.»","IGN, Glosario: Envejecimiento de la población IGN, Glosario del Atlas Didáctico: «Proceso que tiene lugar en un país cuando el porcentaje de población con 65 años o más es superior al 12% de la población total.»","IGN, Glosario: Conurbación IGN, Glosario del Atlas Didáctico: «Conjunto de ciudades independientes que crecen espacialmente y se unen formando un continuo urbano mediante la unión física de sus periferias.»","IGN, Glosario: Ciudad dormitorio IGN, Glosario del Atlas Didáctico: «Núcleo urbano ubicado en las proximidades de una ciudad central, en el que buena parte de su población trabaja en otra ciudad más o menos próxima, generando importantes movimientos pendulares.»","IGN, Atlas Didáctico: Criterios para definir una ciudad IGN, Atlas Didáctico (población, migraciones y ciudades): «muestra la población en municipios de más de 10 000 habitantes (límite numérico a partir del cual un municipio se considera urbano en España).»","IGN, Atlas Didáctico: La morfología urbana IGN, Atlas Didáctico (población, migraciones y ciudades): «La morfología urbana es el aspecto externo, es decir, la forma que presenta la ciudad.»","IGN, Glosario: Lluvia ácida IGN, Glosario del Atlas Didáctico: «Está provocada por las emisiones de óxidos de nitrógeno y de azufre de fábricas, centrales térmicas y vehículos»","IGN, Glosario: Efecto invernadero IGN, Glosario del Atlas Didáctico: «Es un fenómeno natural, sin el que la vida sobre la tierra no sería posible tal y como la conocemos, pues sin él la temperatura media de la superficie sería de –18ºC.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Concepto de geografía humana","blocks":[{"text":"Según el glosario del Atlas Didáctico del Instituto Geográfico Nacional (IGN), la geografía es la disciplina científica encargada del estudio de fenómenos y procesos que explican las relaciones entre el medio natural y el ser humano en la superficie terrestre. La geografía física estudia los elementos de la naturaleza (relieve, atmósfera, agua, seres vivos), mientras que la geografía humana estudia los elementos relacionados con los habitantes de estos espacios (geografía de la población), sus actividades económicas (geografía económica, agraria, industrial, de los servicios, del turismo) y las comunicaciones que conectan los territorios (geografía de los transportes). Su lenguaje propio es la cartografía.","refs":[{"ref":"IGN, Glosario: Geografía","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Disciplina científica encargada del estudio de fenómenos y procesos que explican las relaciones entre el medio natural y el ser humano en la superficie terrestre."},{"ref":"IGN, Glosario: Geografía","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"La geografía humana estudia los elementos relacionados con los habitantes de estos espacios (geografía de la población), sus actividades económicas en sentido genérico o en sus especialidades (geografía económica, agraria, industrial, de los servicios, del turismo), así como las comunicaciones necesarias para la conexión entre territorios (geografía de los transportes)"},{"ref":"IGN, Glosario: Geografía","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"La geografía maneja un lenguaje propio, la cartografía"}]}]},{"n":"2","title":"La ciudad: concepto y criterios para definirla","blocks":[{"text":"El IGN define la ciudad como un núcleo de población de ciertas dimensiones, con un poblamiento muy concentrado y alta densidad de edificación, con funciones especializadas que la convierten en lugar central y polo de atracción de su entorno, y con actividades mayoritariamente no agrarias (administración, ocio, comercio, negocios). Para definirla se usan criterios cuantitativos: el tamaño de población, que cada país fija de forma diferente (Japón 30.000, España 10.000, Portugal 3.000, Suecia 300); la densidad de población y edificatoria; y la tasa de ocupación en los sectores secundario y terciario. En España, 10.000 habitantes es el límite a partir del cual un municipio se considera urbano.","refs":[{"ref":"IGN, Atlas Didáctico: Concepto de ciudad","law":"IGN, Atlas Didáctico (población, migraciones y ciudades)","url":"https://educativo.ign.es/atlas-didactico/poblacion-bach/","quote":"Una ciudad es un núcleo de población de ciertas dimensiones, con un poblamiento muy concentrado y alta densidad de edificación."},{"ref":"IGN, Atlas Didáctico: Criterios para definir una ciudad","law":"IGN, Atlas Didáctico (población, migraciones y ciudades)","url":"https://educativo.ign.es/atlas-didactico/poblacion-bach/","quote":"Japón 30.000, España 10.000, Portugal 3.000 o Suecia 300 habitantes"},{"ref":"IGN, Atlas Didáctico: Criterios para definir una ciudad","law":"IGN, Atlas Didáctico (población, migraciones y ciudades)","url":"https://educativo.ign.es/atlas-didactico/poblacion-bach/","quote":"muestra la población en municipios de más de 10 000 habitantes (límite numérico a partir del cual un municipio se considera urbano en España)."}]},{"text":"Los criterios cualitativos son el predominio de las actividades secundarias y terciarias, un parque de viviendas con predominio de viviendas colectivas y edificaciones altas, unas infraestructuras y servicios más completos que en el medio rural, el papel de centro de poder y decisión político y económico, y la función de centro de influencia sobre los núcleos cercanos. Según su función predominante, se habla de ciudades dormitorio, industriales, universitarias, jardín, turísticas o monumentales. El epígrafe menciona también las «corrientes de estudio» de la ciudad, que no aparecen en las fuentes oficiales de la plataforma y por eso no se desarrollan.","refs":[{"ref":"IGN, Atlas Didáctico: Criterios para definir una ciudad","law":"IGN, Atlas Didáctico (población, migraciones y ciudades)","url":"https://educativo.ign.es/atlas-didactico/poblacion-bach/","quote":"Concentración de edificaciones con predominio de viviendas colectivas, edificaciones altas, poco espacio dedicado a zonas verdes, calles anchas y largas."},{"ref":"IGN, Atlas Didáctico: Criterios para definir una ciudad","law":"IGN, Atlas Didáctico (población, migraciones y ciudades)","url":"https://educativo.ign.es/atlas-didactico/poblacion-bach/","quote":"Diferenciación de tipos de ciudades según su función predominante: dormitorio, industrial, universitaria, jardín, turística, monumental, etc."}]}]},{"n":"3","title":"Morfología urbana y tipos de planos","blocks":[{"text":"La morfología urbana es el aspecto externo, es decir, la forma que presenta la ciudad, y depende de la situación, el emplazamiento, la trama urbana, el tipo de edificación y los usos del suelo. El glosario la describe como el paisaje resultante de combinar tres elementos: el plano, las edificaciones y los usos del suelo. La trama urbana es la forma en que se disponen calles, edificios y espacios, resultado de las sucesivas fases de crecimiento.","refs":[{"ref":"IGN, Atlas Didáctico: La morfología urbana","law":"IGN, Atlas Didáctico (población, migraciones y ciudades)","url":"https://educativo.ign.es/atlas-didactico/poblacion-bach/","quote":"La morfología urbana es el aspecto externo, es decir, la forma que presenta la ciudad."},{"ref":"IGN, Atlas Didáctico: La morfología urbana (glosario)","law":"IGN, Atlas Didáctico (población, migraciones y ciudades)","url":"https://educativo.ign.es/atlas-didactico/poblacion-bach/","quote":"el paisaje resultante de la combinación de tres elementos: el plano, las edificaciones y los usos del suelo."}]},{"text":"Hay cuatro planos básicos. El irregular no sigue un patrón geométrico, nace de un crecimiento no planificado y tiene calles sinuosas y estrechas, como los cascos históricos de Toledo, Granada o Soria. El plano en damero, ortogonal o en cuadrícula tiene calles que se cortan perpendicularmente y es el de la mayoría de los ensanches españoles (Barcelona, con la Diagonal de Cerdá). En el radial o radioconcéntrico las calles parten de un punto central, típico de ciudades medievales como Vitoria-Gasteiz. El lineal crece a lo largo de una vía de comunicación, como la Ciudad Lineal de Madrid.","refs":[{"ref":"IGN, Atlas Didáctico: Tipos de planos urbanos","law":"IGN, Atlas Didáctico (población, migraciones y ciudades)","url":"https://educativo.ign.es/atlas-didactico/poblacion-bach/","quote":"No siguen un patrón geométrico definido. Son resultado de un crecimiento no planificado. Las calles suelen ser sinuosas y estrechas."},{"ref":"IGN, Atlas Didáctico: Tipos de planos urbanos","law":"IGN, Atlas Didáctico (población, migraciones y ciudades)","url":"https://educativo.ign.es/atlas-didactico/poblacion-bach/","quote":"En damero, ortogonal o en cuadrícula Las calles se cortan de manera perpendicular. Por ejemplo, se corresponde con la mayoría de los ensanches de las ciudades españolas."},{"ref":"IGN, Atlas Didáctico: Tipos de planos urbanos","law":"IGN, Atlas Didáctico (población, migraciones y ciudades)","url":"https://educativo.ign.es/atlas-didactico/poblacion-bach/","quote":"Las calles parten desde un punto central, normalmente una plaza principal, de manera radial. Suelen darse en ciudades de origen medieval"},{"ref":"IGN, Atlas Didáctico: Tipos de planos urbanos","law":"IGN, Atlas Didáctico (población, migraciones y ciudades)","url":"https://educativo.ign.es/atlas-didactico/poblacion-bach/","quote":"Resultado del crecimiento a lo largo de una vía de comunicación (carretera o ferrocarril) como, por ejemplo, la Ciudad Lineal de Madrid."}]}]},{"n":"4","title":"Procesos urbanos","blocks":[{"text":"El proceso de urbanización es el incremento de las ciudades y su población y de sus funciones, con expansión del espacio urbano hacia la periferia. Se mide con la tasa de urbanización, relación porcentual entre la población urbana y la total; una tasa alta indica un elevado desarrollo humano y España supera el 80 %. Gran parte de ese crecimiento se debió al éxodo rural, desplazamiento masivo de la población del medio rural hacia las ciudades. En los países menos desarrollados, la explosión urbana (rápido incremento de la población de las ciudades) suele crear barrios sin servicios básicos como luz o agua.","refs":[{"ref":"IGN, Glosario: Proceso de urbanización","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Expresión que se refiere al incremento de ciudades y su población, así como de las funciones que se desempeñan en ellas."},{"ref":"IGN, Glosario: Tasa de urbanización","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Se considera que una tasa de urbanización alta indica un elevado nivel de desarrollo humano. España tiene una tasa de urbanización superior al 80%."},{"ref":"IGN, Glosario: Éxodo rural","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Desplazamiento masivo de la población residente en el medio rural hacia las ciudades."},{"ref":"IGN, Glosario: Explosión urbana","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"En los países menos desarrollados, esta circunstancia suele provocar la creación de barrios que carecen de servicios básicos como luz o agua."}]},{"text":"El crecimiento genera nuevas formas. La conurbación es el conjunto de ciudades independientes que crecen y se unen formando un continuo urbano mediante la unión física de sus periferias (Barcelona, Bilbao, Madrid, Sevilla o Valencia con sus municipios vecinos). El área metropolitana integra una ciudad central y su periferia, pudiendo incorporar otros municipios contiguos. La ciudad dormitorio es el núcleo próximo a una ciudad central donde buena parte de la población trabaja en otra ciudad, lo que genera importantes movimientos pendulares.","refs":[{"ref":"IGN, Glosario: Conurbación","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Conjunto de ciudades independientes que crecen espacialmente y se unen formando un continuo urbano mediante la unión física de sus periferias."},{"ref":"IGN, Glosario: Área metropolitana","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Espacio urbanizado que integra una ciudad central y su periferia circundante, pudiendo incorporar otros municipios contiguos."},{"ref":"IGN, Glosario: Ciudad dormitorio","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Núcleo urbano ubicado en las proximidades de una ciudad central, en el que buena parte de su población trabaja en otra ciudad más o menos próxima, generando importantes movimientos pendulares."}]}]},{"n":"5","title":"La población: población absoluta, densidad y fuentes","blocks":[{"text":"La población absoluta cuenta todos los habitantes de un territorio; la relativa, llamada densidad de población, los pone en relación con la superficie: d = P/S, en habitantes por km². Las grandes ciudades españolas superan los 5000 hab./km², frente a municipios rurales con menos de 30. Por provincias, Madrid y Barcelona superan los 700 hab./km², mientras que Teruel y Soria no llegan a 10. El interior (Aragón, Castilla-La Mancha, Extremadura y Castilla y León) tiene una densidad media inferior a 30 hab./km².","refs":[{"ref":"IGN, Glosario: Densidad de población","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Relación entre la población total de un área y su superficie (d = P/S), expresada normalmente en habitantes por km2 (hab./km2)."},{"ref":"IGN, Atlas Didáctico: Población absoluta y relativa","law":"IGN, Atlas Didáctico (población, migraciones y ciudades)","url":"https://educativo.ign.es/atlas-didactico/poblacion-bach/","quote":"resulta que las dos provincias más densamente pobladas son Madrid y Barcelona, con más de 700 habitantes por kilómetro cuadrado. En el extremo opuesto, las provincias menos pobladas como Teruel y Soria, son también las menos densas: menos de 10 habitantes por kilómetro cuadrado."}]},{"text":"Las fuentes demográficas principales son dos. El padrón es el registro administrativo donde constan los vecinos del municipio y sus características básicas, y sus datos prueban la residencia y el domicilio habitual; el balance anual de la población se hace con él. El censo registra características demográficas, socioculturales y económicas; es un documento estático y muy pormenorizado que en España elabora el INE cada diez años (los terminados en 1).","refs":[{"ref":"IGN, Glosario: Padrón","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Registro administrativo donde constan los vecinos del municipio y sus características básicas (edad, sexo, actividad profesional, domicilio...). Sus datos constituyen prueba de residencia en el municipio y del domicilio habitual en el mismo."},{"ref":"IGN, Glosario: Censo de población","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Es un documento estático -refleja el estado de la población en un momento concreto- y muy pormenorizado por la cantidad de datos que aporta."},{"ref":"IGN, Glosario: Censo de población","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"En España lo realiza el Instituto Nacional de Estadística (INE) cada diez años (los terminados en 1)."}]}]},{"n":"6","title":"Natalidad, mortalidad y crecimiento vegetativo","blocks":[{"text":"La tasa bruta de natalidad se calcula dividiendo los nacimientos de un periodo entre la población total de ese periodo y multiplicando por mil; la de mortalidad, igual pero con las defunciones. La mortalidad infantil relaciona las muertes de niños de un año o menos con el total de nacidos, también por mil, y está ligada al desarrollo y la riqueza. En España, durante el baby boom (1960-1975) la natalidad superaba el 20 por mil; hoy está en torno al 8 por mil.","refs":[{"ref":"IGN, Glosario: Tasa bruta de natalidad","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Se calcula dividiendo el número de nacimientos ocurridos durante un periodo determinado entre la población total de ese mismo periodo. El resultado se multiplica por mil."},{"ref":"IGN, Glosario: Tasa bruta de mortalidad","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Se calcula dividiendo el número de defunciones ocurridas durante un periodo determinado entre la población de ese mismo periodo. El resultado se multiplica por mil."},{"ref":"IGN, Glosario: Mortalidad infantil","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Esta tasa se relaciona con las condiciones de desarrollo y riqueza."},{"ref":"IGN, Atlas Didáctico: Dinámica demográfica","law":"IGN, Atlas Didáctico (población, migraciones y ciudades)","url":"https://educativo.ign.es/atlas-didactico/poblacion-bach/","quote":"entre 1960 y 1975 nacieron muchos niños en España. Es lo que se conoce como la generación del baby boom, cuando las tasas de natalidad superaban el 20 por mil. Actualmente la tasa de natalidad en España se sitúa en torno al 8 por mil."}]},{"text":"El crecimiento natural o vegetativo es la variación positiva o negativa de la población debida a su movimiento natural (natalidad y mortalidad). Sumándole el saldo migratorio se obtiene el crecimiento real. El crecimiento cero es el estancamiento que se produce cuando nacimientos y defunciones se igualan; España ha entrado incluso en decrecimiento, con más muertes que nacimientos desde 2015. La transición demográfica es el paso histórico de un régimen antiguo de natalidad y mortalidad altas a uno moderno con ambas tasas muy bajas: primero baja la mortalidad y después la natalidad, lo que genera un alto crecimiento entre ambos momentos.","refs":[{"ref":"IGN, Glosario: Crecimiento natural o vegetativo","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Variación positiva o negativa de la población de un lugar debido a su movimiento natural (natalidad y mortalidad)."},{"ref":"IGN, Glosario: Crecimiento cero","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"donde incluso hemos entrado en decrecimiento al haber más muertes que nacimientos desde 2015"},{"ref":"IGN, Glosario: Transición demográfica","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Proceso demográfico histórico por el que se pasa de un régimen demográfico antiguo caracterizado por unas altas tasas de natalidad y mortalidad, a un régimen demográfico moderno, con valores muy bajos de ambas tasas. En este proceso, primero se controla las tasas de mortalidad, tanto ordinarias como extraordinarias, y posteriormente las de natalidad"}]}]},{"n":"7","title":"Estructura de la población: pirámides y envejecimiento","blocks":[{"text":"La estructura por edades se representa con la pirámide de población: los grupos más jóvenes en la base, los mayores en el vértice, y separación por sexos (hombres a la izquierda, mujeres a la derecha, en intervalos de 5 años). La de España en 1900 era progresiva, en forma de pagoda, con natalidad y mortalidad elevadas; la de 2015 es regresiva, en forma de bulbo, con base estrecha y más peso de los mayores de 65 años.","refs":[{"ref":"IGN, Atlas Didáctico: Pirámides de población","law":"IGN, Atlas Didáctico (población, migraciones y ciudades)","url":"https://educativo.ign.es/atlas-didactico/poblacion-bach/","quote":"La forma de representar la estructura por edades es la pirámide de población, donde los grupos de edad más jóvenes están en la base, y los grupos de edad mayores están en el vértice. Este gráfico también diferencia la población según sexos."},{"ref":"IGN, Atlas Didáctico: Pirámides de población","law":"IGN, Atlas Didáctico (población, migraciones y ciudades)","url":"https://educativo.ign.es/atlas-didactico/poblacion-bach/","quote":"Es una pirámide progresiva, en forma de pagoda."},{"ref":"IGN, Atlas Didáctico: Pirámides de población","law":"IGN, Atlas Didáctico (población, migraciones y ciudades)","url":"https://educativo.ign.es/atlas-didactico/poblacion-bach/","quote":"Es una pirámide regresiva, en forma de bulbo."}]},{"text":"Se habla de envejecimiento cuando la población de 65 años o más supera el 12 % del total; sus causas son el aumento de la esperanza de vida y el descenso de los nacimientos y la fecundidad. La esperanza de vida es el número de años promedio que puede vivir una persona, mayor en las mujeres. Por actividad, la población activa son las personas en edad legal de trabajar que trabajan o buscan empleo: en España, los mayores de 16 años.","refs":[{"ref":"IGN, Glosario: Envejecimiento de la población","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Proceso que tiene lugar en un país cuando el porcentaje de población con 65 años o más es superior al 12% de la población total. Las principales causas del envejecimiento de la población son el aumento de la esperanza de vida y el descenso del número de nacimientos y de la fecundidad."},{"ref":"IGN, Glosario: Esperanza de vida","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Por sexos los resultados son diferentes, siendo mayor la esperanza de vida femenina."},{"ref":"IGN, Glosario: Población activa","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Todas las personas en edad legal de trabajar, que o trabajan o buscan empleo. En España se considera que están en esta situación los mayores de 16 años."}]}]},{"n":"8","title":"Grupos sociales y sociedad de masas","blocks":[{"text":"La sociedad es el conjunto de personas, pueblos o naciones que conviven bajo normas comunes, y la sociedad civil es ese conjunto de ciudadanos considerado desde sus relaciones y actividades privadas, con independencia del ámbito estatal. La cultura es el conjunto de modos de vida, costumbres, conocimientos, creencias y grado de desarrollo que caracterizan una época o a un grupo social, y la cultura popular, las manifestaciones de la vida tradicional de un pueblo. La minoría es la parte de la población diferente de la mayoría por motivos como la etnia, la lengua o la religión.","refs":[{"ref":"DLE, sociedad 1.a","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"Conjunto de personas, pueblos o naciones que conviven bajo normas comunes."},{"ref":"DLE, sociedad civil","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"Conjunto de los ciudadanos de una sociedad (➝ 1a) considerados desde el punto de vista de sus relaciones y actividades privadas, con independencia del ámbito estatal."},{"ref":"DLE, cultura 1.b y cultura popular","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"Conjunto de modos de vida, costumbres, conocimientos, creencias y grado de desarrollo que caracterizan una época o a un grupo social."},{"ref":"DLE, cultura popular","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"Conjunto de las manifestaciones en que se expresa la vida tradicional de un pueblo."},{"ref":"DLE, minoría 1.b","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"Parte de la población que es diferente de la mayoría por motivos como la etnia, la lengua o la religión."}]},{"text":"Las fuentes no contienen una teoría sociológica de la «sociedad de masas», pero el DLE define la masa como muchedumbre o conjunto numeroso de personas (3.d) y como gran conjunto de gente que por su número puede influir en la marcha de los acontecimientos (3.e). «En masa» significa en conjunto, totalmente, con intervención de todos o casi todos los componentes de una colectividad. La masificación es la acción y efecto de masificar.","refs":[{"ref":"DLE, masa 3.d y 3.e","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"3.d. f. Muchedumbre o conjunto numeroso de personas. […] 3.e. f. Gran conjunto de gente que por su número puede influir en la marcha de los acontecimientos."},{"ref":"DLE, en masa","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"En conjunto, totalmente, con intervención de todos o casi todos los componentes de una colectividad."},{"ref":"DLE, masificación","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"1. f. Acción y efecto de masificar."}]}]},{"n":"9","title":"Contaminación: efecto invernadero y lluvia ácida","blocks":[{"text":"El efecto invernadero es la subida de la temperatura de la atmósfera por la concentración de gases como el dióxido de carbono o el metano, que dejan pasar la radiación solar y retienen parte del calor. Es un fenómeno natural sin el cual la temperatura media de la superficie sería de –18 ºC. Tras la Revolución Industrial, la quema de combustibles fósiles ha aumentado esos gases, lo que provoca el calentamiento global que está en la base del cambio climático.","refs":[{"ref":"IGN, Glosario: Efecto invernadero","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Subida de la temperatura de la atmósfera por la concentración de gases como el dióxido de carbono o el metano"},{"ref":"IGN, Glosario: Efecto invernadero","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Es un fenómeno natural, sin el que la vida sobre la tierra no sería posible tal y como la conocemos, pues sin él la temperatura media de la superficie sería de –18ºC. Tras la Revolución Industrial, la quema de combustibles fósiles y las emisiones de ciertas industrias han aumentado la cantidad de los gases de efecto invernadero"}]},{"text":"La lluvia ácida es la precipitación con un grado de acidez superior al normal (pH menor de 5) debido a la contaminación. Está provocada por las emisiones de óxidos de nitrógeno y de azufre de fábricas, centrales térmicas y vehículos, que se mezclan con el vapor de agua y caen con la lluvia. Daña la vegetación, cultivos, suelos, ecosistemas acuáticos e incluso construcciones, y provoca problemas respiratorios.","refs":[{"ref":"IGN, Glosario: Lluvia ácida","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Precipitación con un grado de acidez superior al normal (pH menor de 5) debido a la contaminación. Está provocada por las emisiones de óxidos de nitrógeno y de azufre de fábricas, centrales térmicas y vehículos"},{"ref":"IGN, Glosario: Lluvia ácida","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Provoca graves daños en la vegetación, cultivos, suelos, ecosistemas acuáticos e incluso en construcciones e infraestructuras; también importantes problemas respiratorios."}]}]},{"n":"10","title":"Protección del medio ambiente","blocks":[{"text":"La Constitución reconoce a todos el derecho a disfrutar de un medio ambiente adecuado para el desarrollo de la persona y el deber de conservarlo, y encarga a los poderes públicos velar por la utilización racional de los recursos naturales (art. 45 CE). El Código Penal castiga con prisión de seis meses a dos años a quien, contraviniendo las normas protectoras del medio ambiente, provoque emisiones, vertidos, radiaciones o ruidos que puedan causar daños sustanciales (art. 325.1 CP). La Ley 7/2021, de cambio climático, persigue cumplir el Acuerdo de París y fija para 2030 reducir las emisiones de gases de efecto invernadero al menos un 23 % respecto de 1990.","refs":[{"ref":"Art. 45.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"1. Todos tienen el derecho a disfrutar de un medio ambiente adecuado para el desarrollo de la persona, así como el deber de conservarlo."},{"ref":"Art. 325.1 CP","law":"Código Penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1. Será castigado con las penas de prisión de seis meses a dos años, multa de diez a catorce meses e inhabilitación especial para profesión u oficio por tiempo de uno a dos años el que, contraviniendo las leyes u otras disposiciones de carácter general protectoras del medio ambiente"},{"ref":"Art. 3.1.a Ley 7/2021","law":"Ley 7/2021","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-8447","quote":"a) Reducir en el año 2030 las emisiones de gases de efecto invernadero del conjunto de la economía española en, al menos, un 23 % respecto del año 1990."}]},{"text":"El desarrollo sostenible es el conjunto de vías de progreso económico, social y político capaces de satisfacer las necesidades actuales sin comprometer los recursos de las futuras generaciones. El concepto aparece en 1987 en el informe Nuestro futuro común, de Gro Harlem Brundtland, y se asumió tras la Cumbre de Río de Janeiro de 1992 (se estudia a fondo en el tema 35).","refs":[{"ref":"IGN, Glosario: Desarrollo sostenible","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Conjunto de vías de progreso económico, social y político capaces de satisfacer las necesidades actuales sin comprometer los recursos y posibilidades de las futuras generaciones."},{"ref":"IGN, Glosario: Desarrollo sostenible","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"El concepto aparece en 1987, en el informe Nuestro futuro común, de Gro Harlem Brundtland y fue asumido por la comunidad internacional tras la Cumbre de Medio Ambiente de Río de Janeiro de 1992."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Densidad de población: d = P/S, en hab./km². Madrid y Barcelona superan los 700 hab./km².","refs":[{"ref":"IGN, Glosario: Densidad de población","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Relación entre la población total de un área y su superficie (d = P/S)"}]},{"text":"En España un municipio es urbano a partir de 10.000 habitantes; la tasa de urbanización supera el 80 %.","refs":[{"ref":"IGN, Glosario: Ciudad","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"En España se consideran ciudades los núcleos de población que superan los 10.000 habitantes."}]},{"text":"Plano en damero: calles perpendiculares, típico de los ensanches. Irregular: cascos históricos. Radioconcéntrico: origen medieval.","refs":[{"ref":"IGN, Atlas Didáctico: Tipos de planos urbanos","law":"IGN, Atlas Didáctico (población, migraciones y ciudades)","url":"https://educativo.ign.es/atlas-didactico/poblacion-bach/","quote":"Las calles se cortan de manera perpendicular."}]},{"text":"Tasas brutas de natalidad y mortalidad: se expresan por mil. Natalidad actual en España: en torno al 8 por mil.","refs":[{"ref":"IGN, Atlas Didáctico: Dinámica demográfica","law":"IGN, Atlas Didáctico (población, migraciones y ciudades)","url":"https://educativo.ign.es/atlas-didactico/poblacion-bach/","quote":"Actualmente la tasa de natalidad en España se sitúa en torno al 8 por mil."}]},{"text":"Envejecimiento: mayores de 65 años por encima del 12 %. Pirámide de 2015: regresiva, en forma de bulbo.","refs":[{"ref":"IGN, Glosario: Envejecimiento de la población","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"cuando el porcentaje de población con 65 años o más es superior al 12% de la población total."}]},{"text":"Población activa en España: mayores de 16 años que trabajan o buscan empleo.","refs":[{"ref":"IGN, Glosario: Población activa","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"En España se considera que están en esta situación los mayores de 16 años."}]},{"text":"Conurbación: ciudades que se unen físicamente por sus periferias. Ciudad dormitorio: movimientos pendulares.","refs":[{"ref":"IGN, Glosario: Conurbación","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"se unen formando un continuo urbano mediante la unión física de sus periferias."}]},{"text":"Sin efecto invernadero la temperatura media sería de –18 ºC. La lluvia ácida tiene pH menor de 5.","refs":[{"ref":"IGN, Glosario: Lluvia ácida","law":"IGN, Glosario del Atlas Didáctico","url":"https://educativo.ign.es/atlas-didactico/glosario/index.html","quote":"Precipitación con un grado de acidez superior al normal (pH menor de 5)"}]}]}]'::jsonb, (select id from public.sources where url = 'https://educativo.ign.es/atlas-didactico/glosario/index.html'), 'https://educativo.ign.es/atlas-didactico/glosario/index.html', null, null, null, 'Otras normas citadas: IGN, Atlas Didáctico (población, migraciones y ciudades) (https://educativo.ign.es/atlas-didactico/poblacion-bach/)'
  from public.topics t where t.slug = 'pn-32-geografia-demografia'
