insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 4/2015, de 30 de marzo, de protección de la seguridad ciudadana (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-33-seguridad-delincuencia', 'Tema 33. La seguridad: concepto, seguridad pública y privada, seguridad nacional') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-33-seguridad-delincuencia' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"La seguridad en la Constitución (arts. 104 y 149.1.29.ª CE)"},{"n":"2","title":"Seguridad pública (LOFCS)"},{"n":"3","title":"Seguridad ciudadana: objeto, fines y principios (LO 4/2015)"},{"n":"4","title":"Seguridad privada: concepto, fines y actividades (Ley 5/2014)"},{"n":"5","title":"Seguridad Nacional: concepto, principios, componentes y ámbitos (Ley 36/2015)"}]'::jsonb, '["Art. 104.1 CE: «1\\. Las Fuerzas y Cuerpos de seguridad, bajo la dependencia del Gobierno, tendrán como misión proteger el libre ejercicio de los derechos y libertades y garantizar la seguridad ciudadana.»","Art. 1.1 LO 2/1986: «1\\. La Seguridad Pública es competencia exclusiva del Estado. Su mantenimiento corresponde al Gobierno de la Nación.»","Art. 1.1 LO 4/2015: «1\\. La seguridad ciudadana es un requisito indispensable para el pleno ejercicio de los derechos fundamentales y las libertades públicas, y su salvaguarda, como bien jurídico de carácter colectivo, es función del Estado»","Art. 3 Ley 36/2015: «A los efectos de esta ley se entenderá por Seguridad Nacional la acción del Estado dirigida a proteger la libertad, los derechos y bienestar de los ciudadanos»","Art. 9.1 Ley 36/2015: «1\\. Se consideran componentes fundamentales de la Seguridad Nacional a los efectos de esta ley la Defensa Nacional, la Seguridad Pública y la Acción Exterior»","Art. 1.1 Ley 5/2014: «Todas estas actividades tienen la consideración de complementarias y subordinadas respecto de la seguridad pública.»","Art. 149.1.29.ª CE: «29.ª Seguridad pública, sin perjuicio de la posibilidad de creación de policías por las Comunidades Autónomas en la forma que se establezca en los respectivos Estatutos en el marco de lo que disponga una ley orgánica.»","Art. 1.4 LO 2/1986: «4\\. El mantenimiento de la Seguridad Pública se ejercerá por las distintas Administraciones Públicas a través de las Fuerzas y Cuerpos de Seguridad.»","Art. 1.2 LO 4/2015: «orientadas a la tutela de la seguridad ciudadana, mediante la protección de personas y bienes y el mantenimiento de la tranquilidad de los ciudadanos.»","Art. 3 LO 4/2015: «c) La preservación de la seguridad y la convivencia ciudadanas.»","Art. 4.1 LO 4/2015: «se regirá por los principios de legalidad, igualdad de trato y no discriminación, oportunidad, proporcionalidad, eficacia, eficiencia y responsabilidad, y se someterá al control administrativo y jurisdiccional.»","Art. 4.3 LO 4/2015: «3\\. La actividad de intervención se justifica por la existencia de una amenaza concreta o de un comportamiento objetivamente peligroso que, razonablemente, sea susceptible de provocar un perjuicio real para la seguridad ciudadana»","Art. 4.2 Ley 36/2015: «2\\. Los principios básicos que orientarán la política de Seguridad Nacional son la unidad de acción, anticipación, prevención, eficiencia, sostenibilidad en el uso de los recursos, capacidad de resistencia y recuperación, coordinación y colaboración.»","Art. 2.1 Ley 5/2014: «realizadas o prestados por empresas de seguridad, despachos de detectives privados y personal de seguridad privada para hacer frente a actos deliberados o riesgos accidentales»","Art. 4.c Ley 5/2014: «c) Complementar el monopolio de la seguridad que corresponde al Estado, integrando funcionalmente sus medios y capacidades como un recurso externo de la seguridad pública.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"La seguridad: concepto","blocks":[{"text":"El Diccionario de la lengua española (DLE) define la seguridad, en su primera acepción, como la «cualidad de seguro», y entre sus sinónimos agrupa la ausencia de peligro (protección, amparo, defensa) y la ausencia de duda (certeza, confianza). En la acepción 1.b designa también el servicio encargado de la seguridad de una persona, de una empresa o de un edificio. La locución «de seguridad», dicha de un cuerpo o fuerza de las Administraciones públicas, significa que vela por la seguridad de los ciudadanos, como en «fuerzas de seguridad».","refs":[{"ref":"DLE, seguridad 1.a","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"1.a. f. Cualidad de seguro."},{"ref":"DLE, seguridad 1.b","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"Servicio encargado de la seguridad (➝ 1a) de una persona, de una empresa, de un edificio, etc."},{"ref":"DLE, de seguridad","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"Dicho de un cuerpo o fuerza de las Administraciones públicas, que vela por la seguridad (➝ 1a) de los ciudadanos."}]},{"text":"El DLE recoge además dos formas complejas útiles. La seguridad ciudadana es la situación de tranquilidad pública y de libre ejercicio de los derechos individuales, cuya protección efectiva se encomienda a las fuerzas de orden público. La seguridad jurídica es la cualidad del ordenamiento jurídico que implica la certeza de sus normas y, por tanto, la previsibilidad de su aplicación. Conviene no confundirlas: la primera es una situación de hecho que protege la policía; la segunda, una cualidad de las normas.","refs":[{"ref":"DLE, seguridad ciudadana","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"Situación de tranquilidad pública y de libre ejercicio de los derechos individuales, cuya protección efectiva se encomienda a las fuerzas de orden público."},{"ref":"DLE, seguridad jurídica","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"Cualidad del ordenamiento jurídico que implica la certeza de sus normas y, consiguientemente, la previsibilidad de su aplicación."}]}]},{"n":"2","title":"Seguridad individual y seguridad colectiva","blocks":[{"text":"La seguridad tiene una dimensión individual, como derecho de cada persona. La Declaración Universal de los Derechos Humanos proclama que todo individuo tiene derecho a la vida, a la libertad y a la seguridad de su persona (art. 3), y la Constitución reconoce que toda persona tiene derecho a la libertad y a la seguridad (art. 17.1 CE). Este derecho funciona como garantía frente a privaciones de libertad arbitrarias: nadie puede ser privado de ella sino en los casos y en la forma previstos en la ley.","refs":[{"ref":"Art. 3 DUDH","law":"DUDH","url":"https://www.un.org/es/about-us/universal-declaration-of-human-rights","quote":"Todo individuo tiene derecho a la vida, a la libertad y a la seguridad de su persona."},{"ref":"Art. 17.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"1. Toda persona tiene derecho a la libertad y a la seguridad. Nadie puede ser privado de su libertad, sino con la observancia de lo establecido en este artículo y en los casos y en la forma previstos en la ley."}]},{"text":"La dimensión colectiva aparece en la Ley Orgánica 4/2015, de protección de la seguridad ciudadana (LOPSC): la seguridad ciudadana es un requisito indispensable para el pleno ejercicio de los derechos fundamentales y las libertades públicas, y su salvaguarda, como bien jurídico de carácter colectivo, es función del Estado, con sujeción a la Constitución y a las leyes (art. 1.1). Así, la seguridad individual y la colectiva no se oponen: la segunda es la condición que permite ejercer los derechos de cada uno.","refs":[{"ref":"Art. 1.1 LOPSC","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"1. La seguridad ciudadana es un requisito indispensable para el pleno ejercicio de los derechos fundamentales y las libertades públicas, y su salvaguarda, como bien jurídico de carácter colectivo, es función del Estado, con sujeción a la Constitución y a las Leyes."}]}]},{"n":"3","title":"La seguridad pública en la Constitución y en la LOFCS","blocks":[{"text":"La Constitución encomienda a las Fuerzas y Cuerpos de seguridad, bajo la dependencia del Gobierno, la misión de proteger el libre ejercicio de los derechos y libertades y garantizar la seguridad ciudadana (art. 104.1 CE). En el reparto de competencias, la seguridad pública es competencia exclusiva del Estado, sin perjuicio de la posibilidad de creación de policías por las comunidades autónomas en la forma que establezcan sus Estatutos en el marco de lo que disponga una ley orgánica (art. 149.1.29.ª CE).","refs":[{"ref":"Art. 104.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"1. Las Fuerzas y Cuerpos de seguridad, bajo la dependencia del Gobierno, tendrán como misión proteger el libre ejercicio de los derechos y libertades y garantizar la seguridad ciudadana."},{"ref":"Art. 149.1.29.ª CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"29.ª Seguridad pública, sin perjuicio de la posibilidad de creación de policías por las Comunidades Autónomas en la forma que se establezca en los respectivos Estatutos en el marco de lo que disponga una ley orgánica."}]},{"text":"Esa ley orgánica es la LO 2/1986, de Fuerzas y Cuerpos de Seguridad (LOFCS). Su artículo primero reitera que la Seguridad Pública es competencia exclusiva del Estado y que su mantenimiento corresponde al Gobierno de la Nación. Las comunidades autónomas participan en su mantenimiento en los términos de sus Estatutos y de la propia ley, y las corporaciones locales, en los de la Ley de Bases de Régimen Local. El mantenimiento de la Seguridad Pública se ejerce por las distintas Administraciones Públicas a través de las Fuerzas y Cuerpos de Seguridad (art. 1.4).","refs":[{"ref":"Art. 1.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"1. La Seguridad Pública es competencia exclusiva del Estado. Su mantenimiento corresponde al Gobierno de la Nación."},{"ref":"Art. 1.2 y 1.3 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"2. Las Comunidades Autónomas participarán en el mantenimiento de la Seguridad Pública en los términos que establezcan los respectivos Estatutos y en el marco de esta Ley. 3. Las Corporaciones Locales participarán en el mantenimiento de la seguridad pública en los términos establecidos en la Ley Reguladora de las Bases de Régimen Local"},{"ref":"Art. 1.4 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"4. El mantenimiento de la Seguridad Pública se ejercerá por las distintas Administraciones Públicas a través de las Fuerzas y Cuerpos de Seguridad."}]}]},{"n":"4","title":"La seguridad ciudadana: objeto y fines de la LO 4/2015","blocks":[{"text":"La LOPSC regula un conjunto plural y diversificado de actuaciones de distinta naturaleza orientadas a la tutela de la seguridad ciudadana, mediante la protección de personas y bienes y el mantenimiento de la tranquilidad de los ciudadanos (art. 1.2). Se aplica en todo el territorio nacional, sin perjuicio de las competencias autonómicas, y sin menoscabo de los regímenes legales que regulan ámbitos concretos de la seguridad pública, como la seguridad aérea, marítima, ferroviaria, vial o en los transportes (art. 2.3).","refs":[{"ref":"Art. 1.2 LOPSC","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"2. Esta Ley tiene por objeto la regulación de un conjunto plural y diversificado de actuaciones de distinta naturaleza orientadas a la tutela de la seguridad ciudadana, mediante la protección de personas y bienes y el mantenimiento de la tranquilidad de los ciudadanos."},{"ref":"Art. 2.3 LOPSC","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"3. Asimismo, esta Ley se aplicará sin menoscabo de los regímenes legales que regulan ámbitos concretos de la seguridad pública, como la seguridad aérea, marítima, ferroviaria, vial o en los transportes"}]},{"text":"Entre los fines de la ley y de la acción de los poderes públicos figuran la protección del libre ejercicio de los derechos fundamentales y las libertades públicas, la garantía del normal funcionamiento de las instituciones, la preservación de la seguridad y la convivencia ciudadanas, el respeto a las leyes, a la paz y a la seguridad ciudadana en el ejercicio de los derechos, y la protección de las personas y bienes, con especial atención a los menores y a las personas con discapacidad necesitadas de especial protección (art. 3).","refs":[{"ref":"Art. 3 LOPSC","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"a) La protección del libre ejercicio de los derechos fundamentales y las libertades públicas y los demás derechos reconocidos y amparados por el ordenamiento jurídico. b) La garantía del normal funcionamiento de las instituciones. c) La preservación de la seguridad y la convivencia ciudadanas."},{"ref":"Art. 3.e LOPSC","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"e) La protección de las personas y bienes, con especial atención a los menores y a las personas con discapacidad necesitadas de especial protección."}]}]},{"n":"5","title":"Principios de la acción pública en seguridad ciudadana","blocks":[{"text":"Las potestades en materia de seguridad ciudadana se rigen por los principios de legalidad, igualdad de trato y no discriminación, oportunidad, proporcionalidad, eficacia, eficiencia y responsabilidad, y se someten al control administrativo y jurisdiccional (art. 4.1 LOPSC). Las normas sobre reunión, manifestación, expresión, información, libertad sindical y huelga se interpretan del modo más favorable a la plena efectividad de los derechos. La actuación de los policías está sujeta a los principios básicos del art. 5 de la LOFCS (art. 4.2).","refs":[{"ref":"Art. 4.1 LOPSC","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"se regirá por los principios de legalidad, igualdad de trato y no discriminación, oportunidad, proporcionalidad, eficacia, eficiencia y responsabilidad, y se someterá al control administrativo y jurisdiccional."},{"ref":"Art. 4.2 LOPSC","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"2. En particular, la actuación de los miembros de las Fuerzas y Cuerpos de Seguridad está sujeta a los principios básicos de actuación regulados en el artículo 5 de la Ley Orgánica 2/1986, de 13 de marzo, de Fuerzas y Cuerpos de Seguridad."}]},{"text":"La intervención policial no puede ser arbitraria: se justifica por la existencia de una amenaza concreta o de un comportamiento objetivamente peligroso que, razonablemente, sea susceptible de provocar un perjuicio real para la seguridad ciudadana y, en concreto, atentar contra los derechos y libertades o alterar el normal funcionamiento de las instituciones públicas (art. 4.3). Las palabras clave son «concreta», «objetivamente» y «real».","refs":[{"ref":"Art. 4.3 LOPSC","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"3. La actividad de intervención se justifica por la existencia de una amenaza concreta o de un comportamiento objetivamente peligroso que, razonablemente, sea susceptible de provocar un perjuicio real para la seguridad ciudadana y, en concreto, atentar contra los derechos y libertades individuales y colectivos o alterar el normal funcionamiento de las instituciones públicas."}]}]},{"n":"6","title":"La seguridad privada: concepto y carácter","blocks":[{"text":"La Ley 5/2014, de Seguridad Privada, regula las actividades y servicios de seguridad que prestan personas privadas, contratados voluntaria u obligatoriamente para la protección de personas y bienes, y las investigaciones privadas. Todas estas actividades tienen la consideración de complementarias y subordinadas respecto de la seguridad pública (art. 1.1), y la ley establece el marco para su coordinación con las Fuerzas y Cuerpos de Seguridad, de los que son complementarios (art. 1.2).","refs":[{"ref":"Art. 1.1 Ley 5/2014","law":"Ley 5/2014","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-3649","quote":"Todas estas actividades tienen la consideración de complementarias y subordinadas respecto de la seguridad pública."},{"ref":"Art. 1.2 Ley 5/2014","law":"Ley 5/2014","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-3649","quote":"establece el marco para la más eficiente coordinación de los servicios de seguridad privada con los de las Fuerzas y Cuerpos de Seguridad, de los que son complementarios."}]},{"text":"La seguridad privada es el conjunto de actividades, servicios, funciones y medidas de seguridad adoptadas voluntaria u obligatoriamente por personas físicas o jurídicas, públicas o privadas, realizadas o prestadas por empresas de seguridad, despachos de detectives privados y personal de seguridad privada para hacer frente a actos deliberados o riesgos accidentales, o para realizar averiguaciones sobre personas y bienes (art. 2.1). Fíjate en los tres prestadores: empresas, despachos de detectives y personal.","refs":[{"ref":"Art. 2.1 Ley 5/2014","law":"Ley 5/2014","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-3649","quote":"realizadas o prestados por empresas de seguridad, despachos de detectives privados y personal de seguridad privada para hacer frente a actos deliberados o riesgos accidentales, o para realizar averiguaciones sobre personas y bienes"}]}]},{"n":"7","title":"Fines y actividades de la seguridad privada","blocks":[{"text":"La seguridad privada tiene tres fines (art. 4 Ley 5/2014): satisfacer las necesidades legítimas de seguridad o de información de sus usuarios; contribuir a garantizar la seguridad pública, a prevenir infracciones y a aportar información a los procedimientos; y complementar el monopolio de la seguridad que corresponde al Estado, integrando funcionalmente sus medios y capacidades como un recurso externo de la seguridad pública.","refs":[{"ref":"Art. 4.a y b Ley 5/2014","law":"Ley 5/2014","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-3649","quote":"a) Satisfacer las necesidades legítimas de seguridad o de información de los usuarios de seguridad privada […] b) Contribuir a garantizar la seguridad pública, a prevenir infracciones y a aportar información a los procedimientos relacionados con sus actuaciones e investigaciones."},{"ref":"Art. 4.c Ley 5/2014","law":"Ley 5/2014","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-3649","quote":"c) Complementar el monopolio de la seguridad que corresponde al Estado, integrando funcionalmente sus medios y capacidades como un recurso externo de la seguridad pública."}]},{"text":"Son actividades de seguridad privada, entre otras, la vigilancia y protección de bienes, establecimientos, lugares y eventos; el acompañamiento y protección de personas determinadas (escoltas); el depósito, custodia y transporte de fondos, joyas u obras de arte, y de explosivos o armas; la instalación de sistemas conectados a centrales de alarmas; la explotación de centrales receptoras de alarmas; y la investigación privada en relación a personas, hechos o delitos solo perseguibles a instancia de parte (art. 5.1). Las actividades a) a g) solo pueden prestarlas empresas de seguridad (art. 5.2). El Reglamento de Seguridad Privada no está en las fuentes de la plataforma.","refs":[{"ref":"Art. 5.1.a y b Ley 5/2014","law":"Ley 5/2014","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-3649","quote":"a) La vigilancia y protección de bienes, establecimientos, lugares y eventos, tanto públicos como privados, así como de las personas que pudieran encontrarse en los mismos. b) El acompañamiento, defensa y protección de personas físicas determinadas, incluidas las que ostenten la condición legal de autoridad."},{"ref":"Art. 5.1.h Ley 5/2014","law":"Ley 5/2014","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-3649","quote":"h) La investigación privada en relación a personas, hechos o delitos sólo perseguibles a instancia de parte."},{"ref":"Art. 5.2 Ley 5/2014","law":"Ley 5/2014","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-3649","quote":"2. Los servicios sobre las actividades relacionadas en los párrafos a) a g) del apartado anterior únicamente podrán prestarse por empresas de seguridad privada, sin perjuicio de las competencias de las Fuerzas y Cuerpos de Seguridad."}]}]},{"n":"8","title":"La Seguridad Nacional (Ley 36/2015)","blocks":[{"text":"La Seguridad Nacional es la acción del Estado dirigida a proteger la libertad, los derechos y bienestar de los ciudadanos, a garantizar la defensa de España y sus principios y valores constitucionales, y a contribuir junto a socios y aliados a la seguridad internacional (art. 3 Ley 36/2015). Su política se orienta por los principios de unidad de acción, anticipación, prevención, eficiencia, sostenibilidad en el uso de los recursos, capacidad de resistencia y recuperación, coordinación y colaboración (art. 4.2). La Estrategia de Seguridad Nacional se elabora a iniciativa del Presidente del Gobierno, la aprueba el Consejo de Ministros y se revisa cada cinco años o cuando lo aconsejen las circunstancias (art. 4.3).","refs":[{"ref":"Art. 3 Ley 36/2015","law":"Ley 36/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10389","quote":"A los efectos de esta ley se entenderá por Seguridad Nacional la acción del Estado dirigida a proteger la libertad, los derechos y bienestar de los ciudadanos, a garantizar la defensa de España y sus principios y valores constitucionales, así como a contribuir junto a nuestros socios y aliados a la seguridad internacional"},{"ref":"Art. 4.2 Ley 36/2015","law":"Ley 36/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10389","quote":"2. Los principios básicos que orientarán la política de Seguridad Nacional son la unidad de acción, anticipación, prevención, eficiencia, sostenibilidad en el uso de los recursos, capacidad de resistencia y recuperación, coordinación y colaboración."},{"ref":"Art. 4.3 Ley 36/2015","law":"Ley 36/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10389","quote":"Se elabora a iniciativa del Presidente del Gobierno, quien la somete a la aprobación del Consejo de Ministros, y se revisará cada cinco años o cuando lo aconsejen las circunstancias cambiantes del entorno estratégico."}]},{"text":"Sus componentes fundamentales son la Defensa Nacional, la Seguridad Pública y la Acción Exterior, y los Servicios de Inteligencia e Información apoyan permanentemente al Sistema de Seguridad Nacional con información, análisis y propuestas (art. 9). Son ámbitos de especial interés, entre otros, la ciberseguridad, la seguridad económica y financiera, la marítima, la del espacio aéreo y ultraterrestre, la energética, la sanitaria y la preservación del medio ambiente (art. 10). La seguridad vial no figura en esa lista.","refs":[{"ref":"Art. 9.1 Ley 36/2015","law":"Ley 36/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10389","quote":"1. Se consideran componentes fundamentales de la Seguridad Nacional a los efectos de esta ley la Defensa Nacional, la Seguridad Pública y la Acción Exterior"},{"ref":"Art. 9.2 Ley 36/2015","law":"Ley 36/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10389","quote":"apoyarán permanentemente al Sistema de Seguridad Nacional, proporcionando elementos de juicio, información, análisis, estudios y propuestas"},{"ref":"Art. 10 Ley 36/2015","law":"Ley 36/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10389","quote":"serán, entre otros, la ciberseguridad, la seguridad económica y financiera, la seguridad marítima, la seguridad del espacio aéreo y ultraterrestre, la seguridad energética, la seguridad sanitaria y la preservación del medio ambiente."}]}]},{"n":"9","title":"La inseguridad","blocks":[{"text":"La inseguridad es, según el DLE, la «falta de seguridad», con el ejemplo «según la policía, había descendido la inseguridad en las calles»; sus sinónimos incluyen la incertidumbre, el riesgo y el peligro. Desde el punto de vista legal, la inseguridad es justamente lo que la LOPSC trata de evitar con sus fines de preservar la seguridad y la convivencia. El Código Penal la toma en cuenta, por ejemplo, al agravar los delitos de odio cuando resultan idóneos para crear un grave sentimiento de inseguridad o temor entre los integrantes de un grupo (art. 510.4 CP). Los estudios sobre la percepción de inseguridad no figuran en las fuentes de la plataforma.","refs":[{"ref":"DLE, inseguridad","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"1. f. Falta de seguridad.Según la policía, había descendido la inseguridad en las calles."},{"ref":"Art. 510.4 CP","law":"Código Penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"resulten idóneos para alterar la paz pública o crear un grave sentimiento de inseguridad o temor entre los integrantes del grupo"}]}]},{"n":"10","title":"La delincuencia: concepto, explicación y clases","blocks":[{"text":"La delincuencia tiene cuatro acepciones en el DLE: acción de delinquir; conjunto de delitos, ya en general o referidos a un país, época o especialidad (por ejemplo, «ha aumentado la delincuencia organizada»); colectividad de delincuentes; y cualidad de delincuente. Su sinónimo es criminalidad. La ciencia que la estudia es la criminología, ciencia social que estudia las causas y circunstancias de los distintos delitos, la personalidad de los delincuentes y el tratamiento adecuado para su represión.","refs":[{"ref":"DLE, delincuencia","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"1.a. f. Acción de delinquir."},{"ref":"DLE, delincuencia 1.b","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"Conjunto de delitos, ya en general o ya referidos a un país, época o especialidad en ellos.Ha aumentado la delincuencia organizada."},{"ref":"DLE, delincuencia 1.c y 1.d","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"1.c. f. Colectividad de delincuentes.1.d. f. Cualidad de delincuente."},{"ref":"DLE, criminología","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"Ciencia social que estudia las causas y circunstancias de los distintos delitos, la personalidad de los delincuentes y el tratamiento adecuado para su represión."}]},{"text":"El epígrafe pide estudiar las teorías explicativas de la delincuencia, sus modelos y sus clases. Esas teorías pertenecen a la criminología y no están desarrolladas en las fuentes oficiales de la plataforma, por lo que no se exponen aquí. De la definición de criminología sí se deduce el esquema básico de cualquier explicación: causas y circunstancias del delito, personalidad del delincuente y tratamiento para su represión. El DLE ofrece un ejemplo que enlaza con el tema 34: «A veces la droga conduce a la delincuencia».","refs":[{"ref":"DLE, delincuencia 1.a","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"A veces la droga conduce a la delincuencia."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Art. 104.1 CE: proteger el libre ejercicio de los derechos y libertades y garantizar la seguridad ciudadana.","refs":[{"ref":"Art. 104.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"tendrán como misión proteger el libre ejercicio de los derechos y libertades y garantizar la seguridad ciudadana."}]},{"text":"Seguridad Pública: competencia exclusiva del Estado; su mantenimiento corresponde al Gobierno (art. 1.1 LOFCS).","refs":[{"ref":"Art. 1.1 LOFCS","law":"LO 2/1986","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859","quote":"La Seguridad Pública es competencia exclusiva del Estado."}]},{"text":"Seguridad ciudadana: bien jurídico de carácter colectivo cuya salvaguarda es función del Estado (art. 1.1 LOPSC).","refs":[{"ref":"Art. 1.1 LOPSC","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"como bien jurídico de carácter colectivo, es función del Estado"}]},{"text":"Intervención: amenaza concreta o comportamiento objetivamente peligroso que pueda provocar un perjuicio real (art. 4.3 LOPSC).","refs":[{"ref":"Art. 4.3 LOPSC","law":"LO 4/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442","quote":"La actividad de intervención se justifica por la existencia de una amenaza concreta o de un comportamiento objetivamente peligroso"}]},{"text":"Seguridad privada: complementaria y subordinada; recurso externo de la seguridad pública.","refs":[{"ref":"Art. 4.c Ley 5/2014","law":"Ley 5/2014","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-3649","quote":"como un recurso externo de la seguridad pública."}]},{"text":"Investigación privada: solo sobre delitos perseguibles a instancia de parte.","refs":[{"ref":"Art. 5.1.h Ley 5/2014","law":"Ley 5/2014","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-3649","quote":"delitos sólo perseguibles a instancia de parte."}]},{"text":"Seguridad Nacional: componentes Defensa Nacional, Seguridad Pública y Acción Exterior; Estrategia revisada cada cinco años.","refs":[{"ref":"Art. 9.1 Ley 36/2015","law":"Ley 36/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10389","quote":"la Defensa Nacional, la Seguridad Pública y la Acción Exterior"}]},{"text":"Criminología: causas y circunstancias del delito, personalidad del delincuente y tratamiento para su represión.","refs":[{"ref":"DLE, criminología","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"la personalidad de los delincuentes y el tratamiento adecuado para su represión."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442', null, null, null, 'Otras normas citadas: CE (https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229), LO 2/1986 (https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859), Ley 36/2015 (https://www.boe.es/buscar/act.php?id=BOE-A-2015-10389), Ley 5/2014 (https://www.boe.es/buscar/act.php?id=BOE-A-2014-3649)'
  from public.topics t where t.slug = 'pn-33-seguridad-delincuencia'
