       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Diccionario panhispánico de dudas (RAE-ASALE), 2.ª ed. en línea: puntuación, mayúsculas, números, siglas y gramática', 'https://www.rae.es/dpd/', 'web_oficial'::public.source_kind, 'Real Academia Española y Asociación de Academias de la Lengua Española', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-37-ortografia', 'Tema 37. Ortografía de la lengua española') on conflict (slug) do nothing;
