   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Centro Nacional de Inteligencia · La Inteligencia (el ciclo de Inteligencia)', 'https://www.cni.es/la-inteligencia', 'web_oficial'::public.source_kind, 'Centro Nacional de Inteligencia (web oficial cni.es)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-40-inteligencia-osint', 'Tema 40. Inteligencia: ciclo de inteligencia, fuentes (OSINT) y el Centro Nacional de Inteligencia') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-40-inteligencia-osint' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"La Inteligencia y el ciclo de Inteligencia (CNI)"},{"n":"2","title":"Fases: dirección, planificación, obtención, elaboración y difusión"},{"n":"3","title":"Fuentes de obtención: HUMINT, OSINT, SIGINT y GEOINT"},{"n":"4","title":"El Centro Nacional de Inteligencia: naturaleza, principios y funciones (Ley 11/2002)"},{"n":"5","title":"Directiva de Inteligencia, Comisión Delegada y Secretario de Estado Director"}]'::jsonb, '["CNI, La Inteligencia: Obtención CNI, «La Inteligencia»: «OSINT Información procedente de fuentes abiertas»","CNI, La Inteligencia: Obtención CNI, «La Inteligencia»: «HUMINT Información procedente de fuentes humanas»","CNI, La Inteligencia: Difusión CNI, «La Inteligencia»: «Difusión Es el final del ciclo, resultado de todo el proceso. En esta fase, la Inteligencia se distribuye a sus destinatarios: las autoridades responsables de adoptar decisiones.»","Art. 7.1 Ley 11/2002: «1\\. El Centro Nacional de Inteligencia se adscribe orgánicamente al Ministerio de Defensa.»","Art. 3 Ley 11/2002: «El Gobierno determinará y aprobará anualmente los objetivos del Centro Nacional de Inteligencia mediante la Directiva de Inteligencia, que tendrá carácter secreto.»","Art. 9.1 Ley 11/2002: «El mandato será de cinco años, sin perjuicio de la facultad del Consejo de Ministros de proceder a su sustitución en cualquier momento.»","CNI, La Inteligencia CNI, «La Inteligencia»: «El resultado final del trabajo del CNI es la Inteligencia que entrega a las autoridades para facilitar la toma de decisiones y que se elabora siguiendo un proceso con fases bien definidas, denominado ciclo de Inteligencia.»","CNI, La Inteligencia: Dirección CNI, «La Inteligencia»: «El ciclo de Inteligencia se inicia con la aprobación anual de la Directiva de Inteligencia por parte de la Comisión Delegada del Gobierno para Asuntos de Inteligencia y del presidente del Gobierno.»","CNI, La Inteligencia: Planificación CNI, «La Inteligencia»: «Una vez aprobada la Directiva de Inteligencia, el CNI realiza un proceso de planificación y organización de los recursos disponibles para obtener la información necesaria»","CNI, La Inteligencia: Elaboración CNI, «La Inteligencia»: «Valoración Se analiza la calidad y origen de la información»","CNI, La Inteligencia: Obtención CNI, «La Inteligencia»: «GEOINT Información procedente de la explotación y análisis de imágenes e información geográfica.»","Art. 1 Ley 11/2002: «El Centro Nacional de Inteligencia es el Organismo público responsable de facilitar al Presidente del Gobierno y al Gobierno de la Nación las informaciones, análisis, estudios o propuestas»","Art. 2.3 Ley 11/2002: «3\\. En el desarrollo de sus funciones, el Centro Nacional de Inteligencia actuará bajo los principios de eficacia, especialización y coordinación, de acuerdo con los objetivos de inteligencia definidos por el Gobierno.»","Art. 6.1 Ley 11/2002: «1\\. La Comisión Delegada del Gobierno para Asuntos de Inteligencia velará por la adecuada coordinación de todos los servicios de información e inteligencia del Estado para la formación de una comunidad de inteligencia.»","Art. 5.4 Ley 11/2002: «4\\. Los miembros del Centro Nacional de Inteligencia no tendrán la consideración de agentes de la autoridad, con excepción de aquellos que desempeñen cometidos profesionales relacionados con la protección del personal del Centro y de las instalaciones del mismo.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Dato, información e inteligencia","blocks":[{"text":"La primera distinción del tema es la que separa la materia prima del producto acabado. La guía CCN-STIC-425 del Centro Criptológico Nacional llama información a los datos en bruto que se recopilan, e inteligencia al producto final que se obtiene después de tratarlos. El ciclo de inteligencia es precisamente el conjunto ordenado de actividades que transforman esa información en bruto en inteligencia que puedan usar los responsables políticos, administrativos o gerenciales de la organización. Por eso un dato aislado o una información sin analizar todavía no es inteligencia: lo es cuando ha sido valorada, integrada e interpretada para responder a una necesidad concreta.","refs":[{"ref":"CCN-STIC-425, apdo. 2.2.2, párr. 16","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"El objetivo de esta fase es recopilar los datos en bruto necesarios (información) para producir el producto final deseado (inteligencia)."},{"ref":"CCN-STIC-425, apdo. 2.2, párr. 11","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"el Ciclo de Inteligencia está compuesto por todas aquellas actividades que, de forma ordenada, persiguen la transformación de información en bruto en inteligencia, capaz de ser usada por los responsables políticos, administrativos o gerenciales de la organización de que se trate."}]},{"text":"El Centro Nacional de Inteligencia (CNI) lo resume desde el punto de vista del destinatario: el resultado final de su trabajo es la Inteligencia que entrega a las autoridades para facilitar la toma de decisiones. Esa inteligencia se elabora siguiendo un proceso con fases bien definidas, el ciclo de Inteligencia. La guía CCN-STIC-425 añade que el resultado del análisis es la llamada actionable intelligence: un producto útil que satisface las necesidades de su consumidor de forma directa, sin necesidad de tratamiento posterior.","refs":[{"ref":"CNI, La Inteligencia","law":"CNI, «La Inteligencia»","url":"https://www.cni.es/la-inteligencia","quote":"El resultado final del trabajo del CNI es la Inteligencia que entrega a las autoridades para facilitar la toma de decisiones y que se elabora siguiendo un proceso con fases bien definidas, denominado ciclo de Inteligencia."},{"ref":"CCN-STIC-425, apdo. 2.2.4, párr. 27","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"actionable intelligence, es decir, un producto de inteligencia capaz de resultar útil y satisfacer las necesidades de su consumidor, de forma directa, sin necesidad de ulterior tratamiento."}]},{"text":"Las fuentes de la plataforma no recogen una definición normativa ni de diccionario de «dato» como concepto separado; el tema se estudia aquí con la distinción entre datos en bruto (información) e inteligencia que hacen el CNI y el CCN.","refs":[{"ref":"CCN-STIC-425, apdo. 2.2.3, párr. 24","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"un equipamiento tecnológico sofisticado, capaz de convertir los datos en información útil y procesable."}]}]},{"n":"2","title":"El Centro Nacional de Inteligencia: naturaleza y principios (Ley 11/2002)","blocks":[{"text":"La Ley 11/2002, de 6 de mayo, regula el CNI. Según su artículo 1, es el Organismo público responsable de facilitar al Presidente del Gobierno y al Gobierno de la Nación las informaciones, análisis, estudios o propuestas que permitan prevenir y evitar cualquier peligro, amenaza o agresión contra la independencia o integridad territorial de España, los intereses nacionales y la estabilidad del Estado de derecho y sus instituciones. Se adscribe orgánicamente al Ministerio de Defensa (art. 7.1) y funciona con autonomía funcional, como Organismo público con personalidad jurídica propia y plena capacidad de obrar (art. 7.2). Se estructura en una Dirección con rango de Secretario de Estado, una Secretaría General y las unidades que se determinen reglamentariamente (art. 7.3).","refs":[{"ref":"Art. 1 LCNI","law":"Ley 11/2002","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2002-8628","quote":"El Centro Nacional de Inteligencia es el Organismo público responsable de facilitar al Presidente del Gobierno y al Gobierno de la Nación las informaciones, análisis, estudios o propuestas que permitan prevenir y evitar cualquier peligro, amenaza o agresión contra la independencia o integridad territorial de España"},{"ref":"Art. 7.1 y 7.3 LCNI","law":"Ley 11/2002","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2002-8628","quote":"1. El Centro Nacional de Inteligencia se adscribe orgánicamente al Ministerio de Defensa. […] 3. El Centro Nacional de Inteligencia se estructura en una Dirección, cuyo titular tendrá rango de Secretario de Estado, una Secretaría General y en las unidades que se determinen reglamentariamente."}]},{"text":"El CNI se rige por el principio de sometimiento al ordenamiento jurídico y está sujeto a control parlamentario y judicial (art. 2.1 y 2.2). En el desarrollo de sus funciones actúa bajo los principios de eficacia, especialización y coordinación, de acuerdo con los objetivos de inteligencia definidos por el Gobierno (art. 2.3). El control parlamentario se ejerce ante la Comisión del Congreso que controla los créditos destinados a gastos reservados, presidida por el Presidente de la Cámara, cuyas sesiones son secretas (art. 11.1); el control judicial previo se regula en una Ley Orgánica complementaria (art. 12).","refs":[{"ref":"Art. 2.3 LCNI","law":"Ley 11/2002","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2002-8628","quote":"En el desarrollo de sus funciones, el Centro Nacional de Inteligencia actuará bajo los principios de eficacia, especialización y coordinación, de acuerdo con los objetivos de inteligencia definidos por el Gobierno."},{"ref":"Art. 11.1 LCNI","law":"Ley 11/2002","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2002-8628","quote":"a través de la Comisión que controla los créditos destinados a gastos reservados, presidida por el Presidente de la Cámara, la información apropiada sobre su funcionamiento y actividades. El contenido de dichas sesiones y sus deliberaciones será secreto."}]}]},{"n":"3","title":"Funciones y actividades del CNI","blocks":[{"text":"El artículo 4 enumera las funciones del CNI. Entre ellas: obtener, evaluar e interpretar información y difundir la inteligencia necesaria para proteger y promover los intereses de España, dentro o fuera del territorio nacional (letra a); prevenir, detectar y posibilitar la neutralización de las actividades de servicios extranjeros, grupos o personas que pongan en riesgo el ordenamiento constitucional o la seguridad del Estado, que es la contrainteligencia (letra b); cooperar con servicios de otros países (letra c); obtener, evaluar e interpretar el tráfico de señales de carácter estratégico (letra d); coordinar los medios de cifra y la seguridad de las tecnologías de la información (letra e); y velar por la protección de la información clasificada (letra f).","refs":[{"ref":"Art. 4.a LCNI","law":"Ley 11/2002","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2002-8628","quote":"a) Obtener, evaluar e interpretar información y difundir la inteligencia necesaria para proteger y promover los intereses políticos, económicos, industriales, comerciales y estratégicos de España, pudiendo actuar dentro o fuera del territorio nacional."},{"ref":"Art. 4.b LCNI","law":"Ley 11/2002","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2002-8628","quote":"b) Prevenir, detectar y posibilitar la neutralización de aquellas actividades de servicios extranjeros, grupos o personas que pongan en riesgo, amenacen o atenten contra el ordenamiento constitucional"},{"ref":"Art. 4.d LCNI","law":"Ley 11/2002","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2002-8628","quote":"d) Obtener, evaluar e interpretar el tráfico de señales de carácter estratégico, para el cumplimiento de los objetivos de inteligencia señalados al Centro."}]},{"text":"Sus actividades, organización, medios, procedimientos, personal, instalaciones y fuentes de información constituyen información clasificada con el grado de secreto (art. 5.1). El Centro puede usar medios y actividades bajo cobertura e identidades, matrículas y permisos reservados (art. 5.3). Un dato muy preguntado: sus miembros no tienen la consideración de agentes de la autoridad, salvo los que se ocupan de la protección del personal y de las instalaciones del Centro (art. 5.4).","refs":[{"ref":"Art. 5.1 LCNI","law":"Ley 11/2002","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2002-8628","quote":"constituyen información clasificada, con el grado de secreto, de acuerdo con lo dispuesto en la legislación reguladora de los secretos oficiales"},{"ref":"Art. 5.4 LCNI","law":"Ley 11/2002","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2002-8628","quote":"Los miembros del Centro Nacional de Inteligencia no tendrán la consideración de agentes de la autoridad, con excepción de aquellos que desempeñen cometidos profesionales relacionados con la protección del personal del Centro y de las instalaciones del mismo."}]}]},{"n":"4","title":"Directiva de Inteligencia, Comisión Delegada y Secretario de Estado Director","blocks":[{"text":"El Gobierno determina y aprueba cada año los objetivos del CNI mediante la Directiva de Inteligencia, que tiene carácter secreto (art. 3). La propuesta de esos objetivos corresponde a la Comisión Delegada del Gobierno para Asuntos de Inteligencia, que los eleva al Presidente del Gobierno (art. 6.4.a). Esta Comisión vela por la adecuada coordinación de todos los servicios de información e inteligencia del Estado para formar una comunidad de inteligencia (art. 6.1). El texto consolidado advierte que el apartado 2 del art. 6, sobre su composición, fue anulado por la STC 110/2021 en la redacción dada por el Real Decreto-ley 8/2020.","refs":[{"ref":"Art. 3 LCNI","law":"Ley 11/2002","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2002-8628","quote":"El Gobierno determinará y aprobará anualmente los objetivos del Centro Nacional de Inteligencia mediante la Directiva de Inteligencia, que tendrá carácter secreto."},{"ref":"Art. 6.1 y 6.4.a LCNI","law":"Ley 11/2002","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2002-8628","quote":"1. La Comisión Delegada del Gobierno para Asuntos de Inteligencia velará por la adecuada coordinación de todos los servicios de información e inteligencia del Estado para la formación de una comunidad de inteligencia. […] a) Proponer al Presidente del Gobierno los objetivos anuales del Centro Nacional de Inteligencia que han de integrar la Directiva de Inteligencia."},{"ref":"Art. 6.2 LCNI","law":"Ley 11/2002","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2002-8628","quote":"Téngase en cuenta que se declara inconstitucional y nula la redacción dada al apartado 2 por la disposición final 2 del Real Decreto-ley 8/2020, de 17 de marzo."}]},{"text":"El Secretario de Estado Director del CNI es nombrado por Real Decreto a propuesta del Ministro de Defensa, con un mandato de cinco años, aunque el Consejo de Ministros puede sustituirlo en cualquier momento (art. 9.1). Además de impulsar y coordinar el Centro, desempeña las funciones de Autoridad Nacional de Inteligencia y Contrainteligencia y la dirección del Centro Criptológico Nacional (art. 9.2.f). El Secretario general, con rango de Subsecretario, le sustituye en ausencia, vacante o enfermedad (art. 10.1).","refs":[{"ref":"Art. 9.1 LCNI","law":"Ley 11/2002","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2002-8628","quote":"será nombrado por Real Decreto a propuesta del Ministro de Defensa. El mandato será de cinco años, sin perjuicio de la facultad del Consejo de Ministros de proceder a su sustitución en cualquier momento."},{"ref":"Art. 9.2.f LCNI","law":"Ley 11/2002","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2002-8628","quote":"f) Desempeñar las funciones de Autoridad Nacional de Inteligencia y Contrainteligencia y la dirección del Centro Criptológico Nacional."},{"ref":"Art. 10.1 LCNI","law":"Ley 11/2002","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2002-8628","quote":"El Secretario general del Centro Nacional de Inteligencia, con rango de Subsecretario, será nombrado por Real Decreto a propuesta del Ministro de Defensa"}]}]},{"n":"5","title":"Tipologías de inteligencia","blocks":[{"text":"No todas las organizaciones consumidoras de inteligencia tienen las mismas necesidades, por lo que lo primero que debe definir cada una es el tipo de inteligencia que necesita. La clasificación más usada atiende a la fuente: el CNI distingue HUMINT (fuentes humanas), OSINT (fuentes abiertas), SIGINT (fuentes técnicas) y GEOINT (explotación y análisis de imágenes e información geográfica). La guía CCN-STIC-425 recoge las mismas cuatro disciplinas, aunque su texto anuncia «cinco fuentes básicas» y solo enumera cuatro.","refs":[{"ref":"CCN-STIC-425, párr. 8","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"lo primero que ha de definir una organización es el tipo de inteligencia que necesita obtener para el más adecuado desempeño de sus funciones o competencias."},{"ref":"CNI, La Inteligencia: Obtención","law":"CNI, «La Inteligencia»","url":"https://www.cni.es/la-inteligencia","quote":"HUMINT Información procedente de fuentes humanas OSINT Información procedente de fuentes abiertas SIGINT Información procedente de fuentes técnicas GEOINT Información procedente de la explotación y análisis de imágenes e información geográfica."},{"ref":"CCN-STIC-425, párr. 17","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"La recolección de la información en bruto puede tener lugar a través de cinco fuentes básicas"}]},{"text":"Por su contenido y horizonte temporal, la guía distingue productos de análisis como la Inteligencia Actual (Current Intelligence), que aborda los acontecimientos del día a día y advierte de consecuencias a corto plazo, y el Análisis de Tendencias (Trend Analysis), también llamado «Informes de Segunda Fase». Dentro de la HUMINT diferencia la Inteligencia de Alto Nivel, relativa a la Seguridad Nacional o estratégica, y la Inteligencia Específica, de naturaleza táctica.","refs":[{"ref":"CCN-STIC-425, párr. 33","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"La denominada Inteligencia Actual (Current Intelligence) aborda los acontecimientos del día a día […] El Análisis de Tendencias (Trend Analysis) –también conocido como \"Informes de Segunda Fase\"- puede proporcionar información sobre un evento o una serie de eventos."},{"ref":"CCN-STIC-425, párr. 20","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"Existen distintos tipos de HUMINT, desde la denominada Inteligencia de Alto Nivel, que comprende información relativa a la Seguridad Nacional o estratégica; hasta la denominada Inteligencia Específica, que comprende información de naturaleza táctica."}]}]},{"n":"6","title":"HUMINT, SIGINT y GEOINT","blocks":[{"text":"La HUMINT se genera recopilando información, por vía oral o documental, directamente de una fuente humana. Es el único tipo de inteligencia en el que quienes recaban la información, los oficiales de obtención, la obtienen directamente de las fuentes, con su conocimiento o no, y pueden incluso dirigir la respuesta de la fuente. Puede ser abierta, cuando el recolector se presenta como representante oficial (declaraciones, informes diplomáticos o policiales), o confidencial, cuando localiza discretamente a una persona con acceso a la información; el reclutamiento puede durar meses o años.","refs":[{"ref":"CCN-STIC-425, párr. 20","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"Se trata del único tipo de inteligencia en la que los encargados de recabar la información (denominados oficiales de obtención) la obtienen directamente de las fuentes (con su conocimiento o no), pudiendo incluso controlar el tema tratado y dirigir la respuesta de la fuente."},{"ref":"CCN-STIC-425, párr. 20","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"En la recolección abierta, el recolector se reúne con las fuentes, evidenciando abiertamente su condición de representante oficial."}]},{"text":"La SIGINT se recaba de las transmisiones de datos e incluye la COMINT (comunicaciones, mediante análisis de tráfico y del significado de las comunicaciones), la ELINT (señales electrónicas que no contienen voz o texto, cuyas fuentes más comunes son las señales de radar) y la FISINT (interceptación de emisiones electromagnéticas extranjeras). La GEOINT consiste en la explotación y análisis de imágenes o información geoespacial para describir, evaluar y representar visualmente las características físicas de los objetos de estudio.","refs":[{"ref":"CCN-STIC-425, párr. 22 y nota 3","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"La Inteligencia de Señales (SIGINT) es aquella que se recaba de las transmisiones de datos […] ELINT es la información derivada básicamente de señales electrónicas que no contienen voz o texto (consideradas COMINT). Las fuentes más comunes de ELINT son las señales de radar."},{"ref":"CCN-STIC-425, nota 3","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"FISINT es la información derivada de la interceptación de las emisiones electromagnéticas extranjeras"},{"ref":"CCN-STIC-425, párr. 19","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"La Inteligencia Geoespacial (GEOINT) consiste en la explotación y análisis de imágenes o información geoespacial, para describir, evaluar y representar visualmente las características físicas de los objetos de estudio"}]}]},{"n":"7","title":"Inteligencia de Fuentes Abiertas (OSINT)","blocks":[{"text":"La OSINT es la inteligencia que se produce a partir de información públicamente accesible. La guía CCN-STIC-425 agrupa sus fuentes en cuatro bloques: medios de comunicación (prensa, radio, televisión, internet); datos públicos (informes gubernamentales, presupuestos, demografía, debates parlamentarios, ruedas de prensa, organigramas públicos); literatura gris, que es material de acceso controlado dirigido a comunidades o foros específicos (informes técnicos, tesis, estudios de mercado, encuestas…); y observación e informes, como las imágenes tomadas desde drones, aviones o satélites, por ejemplo Google Earth.","refs":[{"ref":"CCN-STIC-425, párr. 21","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"La Inteligencia de Fuentes Abiertas (OSINT) es aquella que se produce a través de información públicamente accesible."},{"ref":"CCN-STIC-425, párr. 21","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"Medios de comunicación: prensa, radio, televisión, internet..."},{"ref":"CCN-STIC-425, párr. 21","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"Literatura Gris: material de acceso controlado, dirigido a comunidades o foros específicos"}]},{"text":"El último bloque explica el crecimiento de la OSINT: herramientas como las imágenes de satélite públicas han aumentado la posibilidad de adquirir y procesar información que antes solo conocían los Servicios de Inteligencia. Para el examen, recuerda que OSINT es la información procedente de fuentes abiertas y que la literatura gris se centra sobre todo en disciplinas científicas, políticas, socioeconómicas y militares.","refs":[{"ref":"CCN-STIC-425, párr. 21","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"instrumentos que han venido a incrementar la posibilidad de adquirir y procesar información pública que, con anterioridad, sólo podía ser conocida por los Servicios de Inteligencia."},{"ref":"CCN-STIC-425, párr. 21","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"Generalmente, el material que comprende la Literatura Gris se centra en disciplinas científicas, políticas, socioeconómicas y militares."}]}]},{"n":"8","title":"El ciclo de Inteligencia según el CNI","blocks":[{"text":"El CNI describe cinco fases. La dirección empieza con la aprobación anual de la Directiva de Inteligencia por la Comisión Delegada del Gobierno para Asuntos de Inteligencia y por el presidente del Gobierno; es un documento secreto que recoge las necesidades de Inteligencia del Gobierno. En la planificación, el CNI organiza los recursos disponibles para obtener la información y elaborar la Inteligencia que se le pide. En la obtención se recurre a las fuentes HUMINT, OSINT, SIGINT y GEOINT, apoyándose también en la Inteligencia Artificial.","refs":[{"ref":"CNI, La Inteligencia: Dirección","law":"CNI, «La Inteligencia»","url":"https://www.cni.es/la-inteligencia","quote":"El ciclo de Inteligencia se inicia con la aprobación anual de la Directiva de Inteligencia por parte de la Comisión Delegada del Gobierno para Asuntos de Inteligencia y del presidente del Gobierno. La directiva es un documento con carácter secreto que recoge los objetivos o necesidades de Inteligencia del Gobierno."},{"ref":"CNI, La Inteligencia: Planificación","law":"CNI, «La Inteligencia»","url":"https://www.cni.es/la-inteligencia","quote":"Una vez aprobada la Directiva de Inteligencia, el CNI realiza un proceso de planificación y organización de los recursos disponibles para obtener la información necesaria"},{"ref":"CNI, La Inteligencia: Obtención","law":"CNI, «La Inteligencia»","url":"https://www.cni.es/la-inteligencia","quote":"Nos apoyamos en la Inteligencia Artificial para optimizar nuestros procesos y el tratamiento de la información que obtenemos."}]},{"text":"La elaboración tiene cinco pasos: valoración (se analiza la calidad y origen de la información), examen (se estudia toda la información disponible), integración (se integra la información de distintas fuentes), interpretación (según distintos contextos) y redacción del producto final, la Inteligencia. La difusión es el final del ciclo: la Inteligencia se distribuye a sus destinatarios, las autoridades responsables de adoptar decisiones.","refs":[{"ref":"CNI, La Inteligencia: Elaboración","law":"CNI, «La Inteligencia»","url":"https://www.cni.es/la-inteligencia","quote":"Valoración Se analiza la calidad y origen de la información Examen Se estudia toda la información disponible. Integración Se integra toda la información procedente de distintas fuentes. Redacción Se redacta el producto final: la Inteligencia. Interpretación Se interpreta la información según distintos contextos."},{"ref":"CNI, La Inteligencia: Difusión","law":"CNI, «La Inteligencia»","url":"https://www.cni.es/la-inteligencia","quote":"Difusión Es el final del ciclo, resultado de todo el proceso. En esta fase, la Inteligencia se distribuye a sus destinatarios: las autoridades responsables de adoptar decisiones."}]}]},{"n":"9","title":"El ciclo de Inteligencia según la guía CCN-STIC-425","blocks":[{"text":"La guía CCN-STIC-425 agrupa las actividades en seis fases que se desarrollan cíclicamente: Dirección y Planificación, Recolección, Transformación, Análisis y Producción, Difusión y Evaluación. La Evaluación tiene lugar tras cada una de las otras cinco y sirve para alinear en cada momento los resultados con los objetivos. En la Dirección y Planificación se fijan los requisitos de inteligencia y las acciones para obtenerla: la sub-fase de Dirección responde al QUÉ y la de Planificación al CÓMO.","refs":[{"ref":"CCN-STIC-425, párr. 9","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"Las actividades de inteligencia pueden agruparse en las siguientes seis fases: […] Dirección y Planificación. […] Recolección. […] Transformación. […] Análisis y Producción. […] Difusión. […] Evaluación."},{"ref":"CCN-STIC-425, párr. 11","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"La última fase de Evaluación tiene lugar tras la ejecución de cada una de las cinco fases restantes, y su objetivo es alinear en cada momento del ciclo los resultados obtenidos de la ejecución de cada fase con sus objetivos."},{"ref":"CCN-STIC-425, párr. 15","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"En la sub-fase de Dirección (QUÉ) […] durante la sub-fase de Planificación (CÓMO)"}]},{"text":"La Recolección recopila los datos en bruto. La Transformación convierte su formato en otros que permitan tratarlos y analizarlos: traducción, descifrado, conversión de datos telemétricos o de informes HUMINT en contenido comprensible. El Análisis y Producción integra, evalúa, analiza y prepara la información ya procesada para obtener inteligencia; lo realizan analistas especializados, que elaboran un «estado de situación» y un pronóstico, sabiendo que sus resultados no deben tomarse como verdades absolutas.","refs":[{"ref":"CCN-STIC-425, párr. 23","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"Esta fase tiene por objeto convertir el formato de los datos en bruto recabados de las distintas fuentes, en aquellos otros formatos que posibiliten su posterior tratamiento y análisis."},{"ref":"CCN-STIC-425, párr. 25","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"El objeto de esta fase es integrar, evaluar, analizar y preparar la información previamente procesada, de cara a obtener el producto final deseado (inteligencia)."},{"ref":"CCN-STIC-425, párr. 32","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"los resultados obtenidos de una actividad de análisis no deben tomarse como verdades absolutas."}]}]},{"n":"10","title":"Surface Web y Deep Web","blocks":[{"text":"INCIBE compara Internet con un iceberg. Cuando navegamos por contenido indexado, el que encuentran motores de búsqueda como Google, Bing o Yahoo, estamos en el «Internet superficial» (Surface Web). La Deep Web constituye la mayor parte del contenido de Internet, pero permanece oculta para los buscadores tradicionales. Eso no significa que sea oculta o ilegal: incluye información protegida a la que se accede con credenciales o enlaces directos, sin herramientas especiales, como cuentas bancarias, informes médicos, expedientes académicos, una intranet corporativa o los resultados de búsquedas internas generados en tiempo real.","refs":[{"ref":"INCIBE, Deep web y Dark web","law":"INCIBE","url":"https://www.incibe.es/ciudadania/blog/deep-web-y-dark-web-descubre-que-son-y-en-que-se-diferencian","quote":"Cuando navegamos por este contenido indexado (el que se puede encontrar a través de los motores búsqueda como Google, Bing o Yahoo entre otros), leemos noticias o usamos nuestras redes sociales, estamos en lo que se conoce como \"Internet superficial\"."},{"ref":"INCIBE, Deep web y Dark web","law":"INCIBE","url":"https://www.incibe.es/ciudadania/blog/deep-web-y-dark-web-descubre-que-son-y-en-que-se-diferencian","quote":"La Deep Web constituye la mayor parte del contenido disponible en Internet, pero permanece oculta para los motores de búsqueda tradicionales. Esto no significa que sean contenidos ocultos o ilegales"},{"ref":"INCIBE, Deep web y Dark web","law":"INCIBE","url":"https://www.incibe.es/ciudadania/blog/deep-web-y-dark-web-descubre-que-son-y-en-que-se-diferencian","quote":"Por ejemplo, los datos de una cuenta bancaria, informes médicos o expedientes académicos almacenados en plataformas protegidas, o una intranet corporativa."}]},{"text":"En la Deep Web pueden existir espacios cerrados, como foros o canales, donde se desarrollen actividades ilícitas, pero INCIBE subraya que eso no es una característica propia de la Deep Web, sino un posible uso de algunos de sus espacios.","refs":[{"ref":"INCIBE, Deep web y Dark web","law":"INCIBE","url":"https://www.incibe.es/ciudadania/blog/deep-web-y-dark-web-descubre-que-son-y-en-que-se-diferencian","quote":"Esta circunstancia no es, sin embargo, una característica propia de la Deep Web, sino un posible uso de algunos de sus espacios."}]}]},{"n":"11","title":"Dark Web y Dark Net","blocks":[{"text":"La Dark Web es una sección específica y más reducida dentro de la propia Deep Web. Sus servicios están pensados para ser accesibles a través de redes específicas que dan mayor anonimato, como Tor (The Onion Router), que dificulta identificar tanto al usuario como al servidor. Usa direcciones terminadas en «.onion», que no se abren con navegadores tradicionales, y la comunicación se cifra en múltiples capas. La utilizan activistas, periodistas o ciudadanos que necesitan proteger su identidad frente a la censura, pero también alberga compraventa de datos personales, drogas, armas y otros bienes ilegales.","refs":[{"ref":"INCIBE, Deep web y Dark web","law":"INCIBE","url":"https://www.incibe.es/ciudadania/blog/deep-web-y-dark-web-descubre-que-son-y-en-que-se-diferencian","quote":"La Dark Web es una sección específica y más reducida dentro de la propia Deep Web previamente descrita."},{"ref":"INCIBE, Deep web y Dark web","law":"INCIBE","url":"https://www.incibe.es/ciudadania/blog/deep-web-y-dark-web-descubre-que-son-y-en-que-se-diferencian","quote":"Este entorno se caracteriza por el uso de direcciones web terminadas en \".onion\", que no pueden abrirse con navegadores tradicionales y que son accesibles a través de la red Tor. La comunicación entre quienes acceden y los sitios web se cifra en múltiples capas"},{"ref":"INCIBE, Deep web y Dark web","law":"INCIBE","url":"https://www.incibe.es/ciudadania/blog/deep-web-y-dark-web-descubre-que-son-y-en-que-se-diferencian","quote":"también es conocida por albergar actividades ilícitas, como la compraventa de datos personales, drogas, armas y otros bienes o servicios ilegales."}]},{"text":"El simple acceso a la Dark Web no es ilegal en sí mismo, pero participar en actividades delictivas dentro de ella sí puede tener consecuencias legales graves; además, muchas webs contienen software malicioso. El epígrafe menciona también la «Dark Net»: las fuentes oficiales de la plataforma no la definen por separado, de modo que solo puede estudiarse aquí a través de lo que INCIBE dice de las redes específicas de anonimato como Tor.","refs":[{"ref":"INCIBE, Deep web y Dark web","law":"INCIBE","url":"https://www.incibe.es/ciudadania/blog/deep-web-y-dark-web-descubre-que-son-y-en-que-se-diferencian","quote":"El simple acceso a la Dark Web no es ilegal en sí mismo, pero participar en actividades delictivas o ilegales dentro de esta red sí puede tener consecuencias legales graves."},{"ref":"INCIBE, Deep web y Dark web","law":"INCIBE","url":"https://www.incibe.es/ciudadania/blog/deep-web-y-dark-web-descubre-que-son-y-en-que-se-diferencian","quote":"la Dark Web hace referencia a servicios accesibles a través de redes específicas, como Tor, y requiere herramientas específicas para acceder a determinados servicios"}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Información = datos en bruto; inteligencia = producto final útil para decidir.","refs":[{"ref":"CCN-STIC-425, párr. 16","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"recopilar los datos en bruto necesarios (información) para producir el producto final deseado (inteligencia)."}]},{"text":"CNI: adscrito al Ministerio de Defensa; principios de eficacia, especialización y coordinación.","refs":[{"ref":"Art. 7.1 LCNI","law":"Ley 11/2002","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2002-8628","quote":"El Centro Nacional de Inteligencia se adscribe orgánicamente al Ministerio de Defensa."}]},{"text":"La Directiva de Inteligencia es anual y secreta; con ella empieza el ciclo.","refs":[{"ref":"Art. 3 LCNI","law":"Ley 11/2002","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2002-8628","quote":"aprobará anualmente los objetivos del Centro Nacional de Inteligencia mediante la Directiva de Inteligencia, que tendrá carácter secreto."}]},{"text":"Director del CNI: Secretario de Estado, mandato de cinco años, dirige también el Centro Criptológico Nacional.","refs":[{"ref":"Art. 9.1 LCNI","law":"Ley 11/2002","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2002-8628","quote":"El mandato será de cinco años"}]},{"text":"Los miembros del CNI no son agentes de la autoridad, salvo los de protección de personal e instalaciones.","refs":[{"ref":"Art. 5.4 LCNI","law":"Ley 11/2002","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2002-8628","quote":"no tendrán la consideración de agentes de la autoridad"}]},{"text":"HUMINT humanas, OSINT abiertas, SIGINT técnicas, GEOINT imágenes e información geográfica; ELINT: sobre todo señales de radar.","refs":[{"ref":"CCN-STIC-425, nota 3","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"Las fuentes más comunes de ELINT son las señales de radar."}]},{"text":"CNI: dirección, planificación, obtención, elaboración y difusión. CCN: seis fases, con la Evaluación tras cada una.","refs":[{"ref":"CNI, La Inteligencia: Difusión","law":"CNI, «La Inteligencia»","url":"https://www.cni.es/la-inteligencia","quote":"Es el final del ciclo, resultado de todo el proceso."}]},{"text":"Surface Web indexada; Deep Web, la mayor parte y no indexada; Dark Web, parte reducida de la Deep Web, con «.onion» y Tor.","refs":[{"ref":"INCIBE, Deep web y Dark web","law":"INCIBE","url":"https://www.incibe.es/ciudadania/blog/deep-web-y-dark-web-descubre-que-son-y-en-que-se-diferencian","quote":"sus servicios están diseñados para ser accesibles a través de redes específicas que proporcionan un mayor grado de anonimato, como Tor (The Onion Router)"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.cni.es/la-inteligencia'), 'https://www.cni.es/la-inteligencia', null, null, null, 'Otras normas citadas: Ley 11/2002 (https://www.boe.es/buscar/act.php?id=BOE-A-2002-8628)'
  from public.topics t where t.slug = 'pn-40-inteligencia-osint'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('INCIBE · Glosario de términos de ciberseguridad: una guía de aproximación para el empresario (2021)', 'https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf', 'web_oficial'::public.source_kind, 'Instituto Nacional de Ciberseguridad (INCIBE)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-41-ciberdelincuencia', 'Tema 41. Ciberdelincuencia y agentes de la amenaza') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-41-ciberdelincuencia' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Malware: virus, gusanos, troyanos, ransomware y spyware"},{"n":"2","title":"Ingeniería social: phishing, spear phishing, fraude del CEO, cartas nigerianas"},{"n":"3","title":"Ataques técnicos: DoS/DDoS, botnets, pharming, spoofing, inyección SQL, XSS, zero-day"},{"n":"4","title":"Agentes de la amenaza: hacktivistas, insiders, APT"},{"n":"5","title":"Cibercriminalidad en la Estrategia Nacional de Ciberseguridad 2019"}]'::jsonb, '["Glosario INCIBE, Ransomware Glosario INCIBE: «Malware cuya funcionalidad es «secuestrar» un dispositivo (en sus inicios) o la información que contiene de forma que si la víctima no paga el rescate, no podrá acceder a ella.»","Glosario INCIBE, Phishing Glosario INCIBE: «Técnica o tipo de ataque en el que alguien suplanta a una entidad/servicio mediante un correo electrónico o mensaje instantáneo para conseguir las credenciales o información de la tarjeta de crédito de un usuario.»","Glosario INCIBE, Botnet Glosario INCIBE: «Una botnet es un conjunto de ordenadores (denominados bots) controlados remotamente por un atacante que pueden ser utilizados en conjunto para realizar actividades maliciosas como envío de spam, ataques de DDoS, etc.»","Glosario INCIBE, Denegación de servicio Glosario INCIBE: «Ataque a un sistema, aplicación o dispositivo para dejarlo fuera de servicio debido a una saturación de peticiones.»","Glosario INCIBE, Spyware Glosario INCIBE: «Es un malware que recopila información de un ordenador y después la envía a una entidad remota sin el conocimiento o el consentimiento del propietario del ordenador.»","Glosario INCIBE, Insider Glosario INCIBE: «Persona perteneciente a una organización o empresa que divulga información sensible sobre dicha empresa de forma intencionada.»","Glosario INCIBE, Pharming Glosario INCIBE: «Ataque informático que aprovecha una vulnerabilidad del software de los servidores DNS y que consiste en modificar o sustituir el archivo del servidor de nombres de dominio cambiando la dirección IP legítima de una entidad»","Glosario INCIBE, Spear phishing Glosario INCIBE: «Modalidad de phishing dirigido contra un usuario u organización en concreto en la que los atacantes intentan mediante un correo electrónico, que aparenta ser de un amigo o de empresa conocida, conseguir información confidencial.»","Glosario INCIBE, Fraude del CEO Glosario INCIBE: «Ataque de ingeniería social, variante del spear phishing, que se caracteriza porque el fraude está dirigido a miembros concretos de la organización, principalmente ejecutivos de alto nivel»","Glosario INCIBE, Ingeniería social Glosario INCIBE: «Conjunto de técnicas que los delincuentes usan para engañar a los usuarios de sistemas/servicios TIC para que les faciliten datos que les aporten valor, ya sean credenciales, información sobre los sistemas, servicios instalados etc.»","Glosario INCIBE, Inyección SQL Glosario INCIBE: «Es un tipo de ataque que se aprovecha de una vulnerabilidad en la validación de los contenidos introducidos en un formulario web y que puede permitir la obtención de forma ilegítima de los datos almacenados en la base de datos del sitio web, entre ellos las credenciales de acceso.»","Glosario INCIBE, XSS Glosario INCIBE: «XSS viene del acrónimo en inglés de Secuencias de comandos en sitios cruzados (Cross-site Scripting).»","Glosario INCIBE, Zero-day Glosario INCIBE: «Son aquellas vulnerabilidades en sistemas o programas informáticos que son únicamente conocidas por determinados atacantes y son desconocidas por los fabricantes y usuarios. Al ser desconocidas por los fabricantes, no existe un parche de seguridad para solucionarlas.»","Glosario INCIBE, Hacktivista Glosario INCIBE: «Ciberdelincuente que haciendo uso de sus conocimientos en materia informática y herramientas digitales los usa para promover su ideología política.»","Glosario INCIBE, Cartas nigerianas Glosario INCIBE: «Se trata de una comunicación inesperada mediante correo electrónico carta o mensajería instantánea en las que el remitente promete negocios muy rentables.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Ciberamenazas y cibercriminalidad","blocks":[{"text":"La Estrategia Nacional de Ciberseguridad 2019 define las ciberamenazas como todas aquellas disrupciones o manipulaciones maliciosas que afectan a elementos tecnológicos; se caracterizan por su diversidad de capacidades y motivaciones y no distinguen fronteras. Entre las acciones que usan el ciberespacio con fines maliciosos distingue el ciberespionaje y la cibercriminalidad. Esta última es un problema de seguridad ciudadana de primer orden: el conjunto de actividades ilícitas cometidas en el ciberespacio en cuya planificación, desarrollo y ejecución resulta determinante la utilización de herramientas tecnológicas.","refs":[{"ref":"Estrategia Nacional de Ciberseguridad 2019, cap. 2","law":"Estrategia Nacional de Ciberseguridad 2019","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-6347","quote":"Las ciberamenazas son todas aquellas disrupciones o manipulaciones maliciosas que afectan a elementos tecnológicos."},{"ref":"Estrategia Nacional de Ciberseguridad 2019, cap. 2","law":"Estrategia Nacional de Ciberseguridad 2019","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-6347","quote":"El término Cibercriminalidad, hace referencia al conjunto de actividades ilícitas cometidas en el ciberespacio que tienen por objeto los elementos, sistemas informáticos o cualesquiera otros bienes jurídicos, siempre que en su planificación, desarrollo y ejecución resulte determinante la utilización de herramientas tecnológicas"}]},{"text":"Según la naturaleza del hecho punible, la autoría, la motivación o los daños infligidos, dentro de la cibercriminalidad se puede hablar de ciberterrorismo, de ciberdelito o de hacktivismo. La Estrategia añade que los ciberdelincuentes operan bajo esquemas de crimen organizado y buscan modelos de negocio lucrativos y de bajo riesgo, amparados por la difícil trazabilidad de sus acciones, y que el uso de criptomonedas para servicios ilícitos, extorsión o fraude es un serio desafío.","refs":[{"ref":"Estrategia Nacional de Ciberseguridad 2019, cap. 2","law":"Estrategia Nacional de Ciberseguridad 2019","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-6347","quote":"en función de la naturaleza del hecho punible en sí, de la autoría, de su motivación, o de los daños infligidos, se podrá hablar así de ciberterrorismo, de ciberdelito, o en su caso, de hacktivismo."},{"ref":"Estrategia Nacional de Ciberseguridad 2019, cap. 2","law":"Estrategia Nacional de Ciberseguridad 2019","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-6347","quote":"Los ciberdelincuentes operan bajo esquemas de crimen organizado y continúan explorando de manera incesante técnicas sobre las que construir modelos de negocio lucrativo y de bajo riesgo, amparados por la difícil trazabilidad de sus acciones."}]}]},{"n":"2","title":"Malware: virus, gusanos y troyanos","blocks":[{"text":"El malware (de malicious software) es el software que tiene como objetivo dañar o infiltrarse en un sistema de información sin el consentimiento de su propietario. Abarca virus, gusanos, troyanos, backdoors, spyware y otros programas cuya nota común es su carácter dañino. El virus se caracteriza porque infecta ficheros ejecutables o sectores de arranque de dispositivos de almacenamiento. El gusano destaca por su alto grado de «dispersabilidad»: a diferencia del troyano, que depende de que el usuario visite una web maliciosa o ejecute un fichero infectado, el gusano hace copias de sí mismo y se propaga automáticamente por la red, sin acción humana.","refs":[{"ref":"Glosario INCIBE, Malware","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"Es un tipo de software que tiene como objetivo dañar o infiltrarse sin el consentimiento de su propietario en un sistema de información."},{"ref":"Glosario INCIBE, Virus","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"Malware que tiene como característica principal que infecta ficheros ejecutables o sectores de arranque de dispositivos de almacenamiento"},{"ref":"Glosario INCIBE, Gusano","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"Mientras que los troyanos dependen de que un usuario acceda a una web maliciosa o ejecute un fichero infectado, los gusanos realizan copias de sí mismos, infectan a otros ordenadores y se propagan automáticamente en una red independientemente de la acción humana."}]},{"text":"El troyano es un malware con múltiples utilidades; la más común es crear una puerta trasera en el equipo infectado para descargar actualizaciones y nuevas funcionalidades, y está diseñado para ser controlado desde un centro de comando y control (C&C). Sus funciones habituales incluyen keylogger, robo de datos, minado de criptomonedas o descarga de otro malware como ransomware. Suele distribuirse por correo electrónico con un adjunto o enlace. Dato de examen: más del 80 % del malware actual son troyanos, y los equipos infectados se llaman bots o zombis.","refs":[{"ref":"Glosario INCIBE, Troyano","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"Malware diseñado para tener múltiples utilidades, la más común es crear una puerta trasera en el equipo infectado, para poder descargar actualizaciones y nuevas funcionalidades."},{"ref":"Glosario INCIBE, Troyano","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"La mayor parte del malware actual son Troyanos, más del 80%. Los ordenadores infectados con un troyano se denominan Bots o Zombi, y un grupo de bot controlados por un C&C se denomina Botnet o Red Zombie."}]}]},{"n":"3","title":"Ransomware, spyware y cryptojacking","blocks":[{"text":"El ransomware es el malware que «secuestra» un dispositivo (en sus inicios) o la información que contiene, de modo que la víctima no puede acceder a ella si no paga el rescate. El spyware o programa espía recopila información de un ordenador y la envía a una entidad remota sin el conocimiento ni el consentimiento del propietario; el término se usa también, más ampliamente, para adware, falsos antivirus o troyanos.","refs":[{"ref":"Glosario INCIBE, Ransomware","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"Malware cuya funcionalidad es «secuestrar» un dispositivo (en sus inicios) o la información que contiene de forma que si la víctima no paga el rescate, no podrá acceder a ella."},{"ref":"Glosario INCIBE, Spyware","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"Es un malware que recopila información de un ordenador y después la envía a una entidad remota sin el conocimiento o el consentimiento del propietario del ordenador."}]},{"text":"El término cryptojacking une Cryptocurrency (criptomonedas) y Hijacking (secuestro): es el secuestro de un dispositivo sin el consentimiento o conocimiento del usuario para usar su capacidad de procesamiento en el minado de criptomonedas. Según INCIBE surgió por primera vez en 2011 y creció con el alza de las monedas virtuales a finales de 2017. Se infecta por webs manipuladas con código inyectado en el navegador o por malware en adjuntos y plugins; sus síntomas son lentitud, bloqueos, sobrecalentamiento y alto consumo eléctrico.","refs":[{"ref":"INCIBE, Cryptojacking","law":"INCIBE","url":"https://www.incibe.es/ciudadania/blog/deep-web-y-dark-web-descubre-que-son-y-en-que-se-diferencian","quote":"El término cryptojacking deriva de la conjunción de Cryptocurrency (Criptomonedas) y Hijacking (Secuestro). Como se puede deducir, se refiere al secuestro de un dispositivo electrónico sin el consentimiento o conocimiento del usuario"},{"ref":"INCIBE, Cryptojacking","law":"INCIBE","url":"https://www.incibe.es/ciudadania/blog/deep-web-y-dark-web-descubre-que-son-y-en-que-se-diferencian","quote":"Este tipo de ataques surgió por primera vez en 2011, aunque su auge se ha producido al calor del alza de las cotizaciones de las monedas virtuales, a finales de 2017."},{"ref":"INCIBE, Cryptojacking","law":"INCIBE","url":"https://www.incibe.es/ciudadania/blog/deep-web-y-dark-web-descubre-que-son-y-en-que-se-diferencian","quote":"Los principales síntomas son que funcionan lento, se quedan colgados constantemente o que la velocidad de conexión a Internet se ralentiza."}]}]},{"n":"4","title":"Botnet y denegación de servicio","blocks":[{"text":"Una botnet es un conjunto de ordenadores (bots) controlados remotamente por un atacante que pueden usarse en conjunto para actividades maliciosas como el envío de spam o ataques DDoS. Se caracterizan por un servidor central de mando y control (C&C) al que se conectan los bots, aunque existen botnets P2P sin servidor C&C único. El ordenador zombie es el controlado remotamente por un ciberdelincuente tras ser infectado.","refs":[{"ref":"Glosario INCIBE, Botnet","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"Una botnet es un conjunto de ordenadores (denominados bots) controlados remotamente por un atacante que pueden ser utilizados en conjunto para realizar actividades maliciosas como envío de spam, ataques de DDoS, etc."},{"ref":"Glosario INCIBE, Botnet","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"Existen también las llamadas botnets P2P que se caracterizan por carecer de un servidor C&C único."}]},{"text":"La denegación de servicio (DoS) es el ataque a un sistema, aplicación o dispositivo para dejarlo fuera de servicio por saturación de peticiones. La denegación de servicio distribuida (DDoS) es un DoS en el que las peticiones llegan desde diversos orígenes, por lo que es más efectivo y más difícil de detener y de rastrear.","refs":[{"ref":"Glosario INCIBE, Denegación de servicio","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"Ataque a un sistema, aplicación o dispositivo para dejarlo fuera de servicio debido a una saturación de peticiones."},{"ref":"Glosario INCIBE, Denegación de servicio distribuida","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"Es un Dos pero las peticiones se hacen desde diversos orígenes, de esta forma es más efectivo, y más complicado de detener y determinar su origen."}]}]},{"n":"5","title":"Ingeniería social, phishing, spear phishing y fraude del CEO","blocks":[{"text":"La ingeniería social es el conjunto de técnicas que usan los delincuentes para engañar a los usuarios de sistemas o servicios TIC y que les faciliten datos de valor: credenciales, información sobre los sistemas, servicios instalados, etc. Su forma más conocida es el phishing, en el que alguien suplanta a una entidad o servicio mediante correo electrónico o mensaje instantáneo para obtener las credenciales o los datos de la tarjeta de crédito del usuario, normalmente mediante un enlace a una web que imita a la legítima.","refs":[{"ref":"Glosario INCIBE, Ingeniería social","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"Conjunto de técnicas que los delincuentes usan para engañar a los usuarios de sistemas/servicios TIC para que les faciliten datos que les aporten valor, ya sean credenciales, información sobre los sistemas, servicios instalados etc."},{"ref":"Glosario INCIBE, Phishing","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"Técnica o tipo de ataque en el que alguien suplanta a una entidad/servicio mediante un correo electrónico o mensaje instantáneo para conseguir las credenciales o información de la tarjeta de crédito de un usuario."}]},{"text":"El spear phishing es un phishing dirigido contra un usuario u organización concretos, con un correo que aparenta venir de un amigo o empresa conocida; suele ir precedido de una fase de reconocimiento. El fraude del CEO (whaling) es una variante del spear phishing dirigida a miembros concretos de la organización, principalmente ejecutivos de alto nivel, para obtener claves y acceso a los sistemas de la empresa.","refs":[{"ref":"Glosario INCIBE, Spear phishing","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"Modalidad de phishing dirigido contra un usuario u organización en concreto en la que los atacantes intentan mediante un correo electrónico, que aparenta ser de un amigo o de empresa conocida, conseguir información confidencial. Este tipo de ataques suelen contar previamente con una fase de reconocimiento"},{"ref":"Glosario INCIBE, Fraude del CEO","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"Ataque de ingeniería social, variante del spear phishing, que se caracteriza porque el fraude está dirigido a miembros concretos de la organización, principalmente ejecutivos de alto nivel"},{"ref":"Glosario INCIBE, Fraude del CEO","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"Sinónimo: Whaling"}]}]},{"n":"6","title":"Cartas nigerianas y Business E-mail Compromise","blocks":[{"text":"Las cartas nigerianas (estafa nigeriana) son una comunicación inesperada por correo electrónico, carta o mensajería instantánea en la que el remitente promete negocios muy rentables. El gancho es la expectativa de ganar mucho dinero con sencillas gestiones; el remitente suele hacerse pasar por abogado o allegado de alguien fallecido que dejó una gran suma, pide discreción y gastos por adelantado, y envía documentos falsos, pero la transferencia prometida nunca llega.","refs":[{"ref":"Glosario INCIBE, Cartas nigerianas","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"Se trata de una comunicación inesperada mediante correo electrónico carta o mensajería instantánea en las que el remitente promete negocios muy rentables."},{"ref":"Glosario INCIBE, Cartas nigerianas","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"procurando que finalmente transfiera una fuerte cantidad de dinero para llevar a cabo la operación."}]},{"text":"El fraude BEC (Business E-mail Compromise, correo electrónico corporativo comprometido) es un fraude contra empresas que realizan transferencias electrónicas de dinero. El ciberdelincuente suplanta a un proveedor e intercepta los correos de facturación, cambiando la cuenta bancaria para que la empresa pague a una cuenta que él controla. Puede ocurrir porque está comprometida la cuenta de la propia empresa (por ejemplo, con una regla que reenvía el correo) o la del proveedor.","refs":[{"ref":"INCIBE, Fraude email comprometido","law":"INCIBE","url":"https://www.incibe.es/ciudadania/blog/deep-web-y-dark-web-descubre-que-son-y-en-que-se-diferencian","quote":"BEC del inglés Business E-mail Compromise o correo electrónico corporativo comprometido es un tipo de fraude contra empresas que realizan transferencias electrónicas de dinero."},{"ref":"INCIBE, Fraude email comprometido","law":"INCIBE","url":"https://www.incibe.es/ciudadania/blog/deep-web-y-dark-web-descubre-que-son-y-en-que-se-diferencian","quote":"El ciberdelincuente suplanta a uno de nuestros proveedores (Proveedor S.L.) e intercepta los correos de facturación que nos envía, cambiando la cuenta del banco donde realizar los pagos"}]}]},{"n":"7","title":"Pharming y spoofing","blocks":[{"text":"El pharming aprovecha una vulnerabilidad del software de los servidores DNS y modifica o sustituye el archivo del servidor de nombres de dominio, cambiando la dirección IP legítima de una entidad, normalmente un banco. Así, cuando el usuario escribe el nombre de dominio correcto, el navegador le lleva automáticamente a una web falsa que suplanta a la entidad y le roba las claves.","refs":[{"ref":"Glosario INCIBE, Pharming","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"Ataque informático que aprovecha una vulnerabilidad del software de los servidores DNS y que consiste en modificar o sustituir el archivo del servidor de nombres de dominio cambiando la dirección IP legítima de una entidad"},{"ref":"Glosario INCIBE, Pharming","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"el navegador redirigirá automáticamente al usuario a una dirección IP donde se aloja una web falsa que suplantará la identidad legítima de la entidad"}]},{"text":"El spoofing es una técnica de suplantación de identidad en la Red. Según la tecnología, INCIBE distingue: IP spoofing (suplanta la IP de origen de un paquete TCP/IP), ARP spoofing (falsea la tabla ARP que relaciona dirección MAC e IP, de modo que lo enviado a un usuario llega al atacante), DNS spoofing (relación falsa entre IP y nombre de dominio), web spoofing (página web falsa; el phishing es un tipo de web spoofing) y mail spoofing (suplantación de correo para envío masivo de spam).","refs":[{"ref":"Glosario INCIBE, Spoofing","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"Es una técnica de suplantación de identidad en la Red, llevada a cabo por un ciberdelincuente generalmente gracias a un proceso de investigación o con el uso de malware."},{"ref":"Glosario INCIBE, Spoofing","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"ARP spoofing: es la suplantación de identidad por falsificación de tabla ARP. ARP (Address Resolution Protocol) es un protocolo de nivel de red que relaciona una dirección MAC con la dirección IP del ordenador. Por lo tanto, al falsear la tabla ARP de la víctima, todo lo que se envíe a un usuario, será direccionado al atacante."},{"ref":"Glosario INCIBE, Spoofing","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"Los ataques de phishing son un tipo de Web spoofing."}]}]},{"n":"8","title":"Inyección SQL, XSS y zero-day","blocks":[{"text":"La inyección SQL aprovecha una vulnerabilidad en la validación de los contenidos introducidos en un formulario web y puede permitir obtener ilegítimamente los datos de la base de datos del sitio, incluidas las credenciales. El XSS (Cross-site Scripting, «secuencias de comandos en sitios cruzados») es una vulnerabilidad de páginas web generadas dinámicamente que permite insertar en un formulario un pequeño programa malicioso y hacer que se ejecute; sus puntos de entrada habituales son buscadores, foros, blogs y formularios.","refs":[{"ref":"Glosario INCIBE, Inyección SQL","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"Es un tipo de ataque que se aprovecha de una vulnerabilidad en la validación de los contenidos introducidos en un formulario web y que puede permitir la obtención de forma ilegítima de los datos almacenados en la base de datos del sitio web, entre ellos las credenciales de acceso."},{"ref":"Glosario INCIBE, XSS","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"XSS viene del acrónimo en inglés de Secuencias de comandos en sitios cruzados (Cross-site Scripting)."},{"ref":"Glosario INCIBE, XSS","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"es posible insertar en un formulario un pequeño programa malicioso, ocultándolo entre solicitudes legítimas y hacer que éste se ejecute."}]},{"text":"Las vulnerabilidades zero-day (0-day) son las que solo conocen determinados atacantes y desconocen fabricantes y usuarios. Como el fabricante no las conoce, no existe parche de seguridad, y por eso son muy peligrosas: el atacante puede explotarlas sin que el usuario sepa que es vulnerable.","refs":[{"ref":"Glosario INCIBE, Zero-day","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"Son aquellas vulnerabilidades en sistemas o programas informáticos que son únicamente conocidas por determinados atacantes y son desconocidas por los fabricantes y usuarios. Al ser desconocidas por los fabricantes, no existe un parche de seguridad para solucionarlas."}]}]},{"n":"9","title":"Skimming, e-skimming y carding","blocks":[{"text":"Tradicionalmente, el robo de tarjetas o skimming se hacía directamente en los cajeros automáticos, donde los delincuentes clonaban las tarjetas y robaban el PIN. El skimmer es un pequeño dispositivo que se instala en los lectores de tarjetas y roba la información cuando se usan. El fraude pasó al mundo digital como e-skimming o web skimming: los ciberdelincuentes acceden a una tienda online legítima, modifican su código y roban los datos bancarios y personales de los clientes para venderlos en el mercado negro o usarlos en su beneficio.","refs":[{"ref":"INCIBE, E-skimming","law":"INCIBE","url":"https://www.incibe.es/ciudadania/blog/deep-web-y-dark-web-descubre-que-son-y-en-que-se-diferencian","quote":"Tradicionalmente, el robo de tarjetas de crédito o skimming se hacía directamente en los cajeros automáticos."},{"ref":"INCIBE, Carding","law":"INCIBE","url":"https://www.incibe.es/ciudadania/blog/deep-web-y-dark-web-descubre-que-son-y-en-que-se-diferencian","quote":"un skimmer, un pequeño dispositivo que se instala en los lectores de tarjetas bancarias y que roba la información cuando lo usamos."},{"ref":"INCIBE, E-skimming","law":"INCIBE","url":"https://www.incibe.es/ciudadania/blog/deep-web-y-dark-web-descubre-que-son-y-en-que-se-diferencian","quote":"El e-skimming o web skimming es una técnica utilizada por ciberdelincuentes para obtener información bancaria y personal de tiendas online legítimas que posteriormente será vendida en el mercado negro, o utilizada directamente por los ciberdelincuentes en su propio beneficio."}]},{"text":"En el carding, el ciberdelincuente prueba datos de tarjetas robadas con pequeñas compras en comercios electrónicos, a menudo mediante bots, hasta dar con las válidas, que después vende o usa para compras de gran valor. Los listados de tarjetas se obtienen a menudo en la Dark Web o mediante keyloggers y phishing.","refs":[{"ref":"INCIBE, Carding","law":"INCIBE","url":"https://www.incibe.es/ciudadania/blog/deep-web-y-dark-web-descubre-que-son-y-en-que-se-diferencian","quote":"Para probar que esos datos robados son válidos, realizan pequeñas compras en comercios electrónicos hasta que dan con las que funcionan. A esta técnica se le llama carding"},{"ref":"INCIBE, Carding","law":"INCIBE","url":"https://www.incibe.es/ciudadania/blog/deep-web-y-dark-web-descubre-que-son-y-en-que-se-diferencian","quote":"Una forma muy común de obtener estos listados de tarjetas de crédito es a través de la Dark Web"}]}]},{"n":"10","title":"Agentes de la amenaza: cibercriminales, hacktivistas e insiders","blocks":[{"text":"El ciberdelincuente es quien realiza actividades delictivas en la red contra personas o sistemas, causando daños económicos o reputacionales mediante robo, filtrado de información, deterioro de software o hardware, fraude y extorsión; casi siempre busca fines económicos. El hacktivista usa sus conocimientos informáticos para promover su ideología política, con acciones como defacement, redirecciones, ataques DoS o robo de información, bajo la premisa de la desobediencia civil.","refs":[{"ref":"Glosario INCIBE, Ciberdelincuente","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"Persona que realiza actividades delictivas en la red contra personas o sistemas informáticos, pudiendo provocar daños económicos o reputacionales mediante robo, filtrado de información, deterioro de software o hardware, fraude y extorsión. Casi siempre están orientados a la obtención de fines económicos."},{"ref":"Glosario INCIBE, Hacktivista","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"Ciberdelincuente que haciendo uso de sus conocimientos en materia informática y herramientas digitales los usa para promover su ideología política."}]},{"text":"El insider (amenaza interna) es la persona perteneciente a una organización o empresa que divulga información sensible sobre ella de forma intencionada. El epígrafe cita también el «Crime as a Service»: las fuentes oficiales de la plataforma no lo definen; solo la Estrategia de 2019 describe que los ciberdelincuentes operan con esquemas de crimen organizado y modelos de negocio lucrativos.","refs":[{"ref":"Glosario INCIBE, Insider","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"Persona perteneciente a una organización o empresa que divulga información sensible sobre dicha empresa de forma intencionada."},{"ref":"Estrategia Nacional de Ciberseguridad 2019, cap. 2","law":"Estrategia Nacional de Ciberseguridad 2019","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-6347","quote":"Debido a la revolución de Internet, Estados, grupos organizados, colectivos y hasta individuos aislados pueden alcanzar un nivel de poder y una capacidad de influir impensable en otros tiempos."}]}]},{"n":"11","title":"APT y Cyber Kill Chain","blocks":[{"text":"La amenaza avanzada persistente (APT, Advanced Persistent Threat) es un ataque que se realiza con sigilo, permaneciendo activo y oculto durante mucho tiempo y con diferentes formas de ataque. Suele estar patrocinada por compañías, mafias o un estado, busca vigilar, exfiltrar datos o modificar recursos de forma continuada y aprovecha a menudo vulnerabilidades zero-day. La Estrategia de 2019 añade que las mayores capacidades de ciberespionaje corresponden a actores estatales, que operan sobre todo mediante APT.","refs":[{"ref":"Glosario INCIBE, Amenaza avanzada persistente","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"consiste en un tipo de ataque informático que se caracteriza por realizarse con sigilo, permaneciendo activo y oculto durante mucho tiempo, utilizando diferentes formas de ataque. Suelen estar patrocinados por compañías, mafias o un estado."},{"ref":"Estrategia Nacional de Ciberseguridad 2019, cap. 2","law":"Estrategia Nacional de Ciberseguridad 2019","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-6347","quote":"Las mayores capacidades corresponden principalmente a actores estatales (organismos de inteligencia o militares), que fundamentalmente operan a través de las denominadas Amenazas Persistentes Avanzadas (APT)."}]},{"text":"El modelo Kill Chain se desarrolló esencialmente para analizar las APT. Divide la acción del adversario en siete fases: Reconocimiento, Código Dañino, Entrega, Explotación, Instalación, Mando y Control (C2) y Acción en el Objetivo. Para cada fase contempla seis líneas de acción de la víctima: Detección, Denegación, Disrupción, Degradación, Engaño y Destrucción. Permite medir la eficacia de las defensas y planificar inversiones.","refs":[{"ref":"CCN-STIC-425, párr. 181","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"fue desarrollado para abordar, esencialmente, el análisis de APTs"},{"ref":"CCN-STIC-425, párr. 183","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"Kill Chain divide la acción del adversario en fases: Reconocimiento, Código Dañino, Entrega, Explotación, Instalación, Mando y Control (C2) y Acción en el Objetivo"},{"ref":"CCN-STIC-425, párr. 185","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"el modelo Kill Chain contempla seis posibles líneas de acción (Detección, Denegación, Disrupción, Degradación, Engaño y Destrucción)"}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Cibercriminalidad según la ENCS 2019: ciberterrorismo, ciberdelito o hacktivismo.","refs":[{"ref":"Estrategia Nacional de Ciberseguridad 2019, cap. 2","law":"Estrategia Nacional de Ciberseguridad 2019","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2019-6347","quote":"se podrá hablar así de ciberterrorismo, de ciberdelito, o en su caso, de hacktivismo."}]},{"text":"Troyanos: más del 80 % del malware actual. Gusanos: se propagan solos, sin acción humana.","refs":[{"ref":"Glosario INCIBE, Troyano","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"La mayor parte del malware actual son Troyanos, más del 80%."}]},{"text":"Ransomware secuestra; spyware espía y envía; cryptojacking mina criptomonedas (desde 2011).","refs":[{"ref":"INCIBE, Cryptojacking","law":"INCIBE","url":"https://www.incibe.es/ciudadania/blog/deep-web-y-dark-web-descubre-que-son-y-en-que-se-diferencian","quote":"Este tipo de ataques surgió por primera vez en 2011"}]},{"text":"Spear phishing: dirigido y con fase de reconocimiento; fraude del CEO (whaling): a directivos.","refs":[{"ref":"Glosario INCIBE, Fraude del CEO","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"variante del spear phishing"}]},{"text":"Pharming: manipulación de servidores DNS; ARP spoofing: falsea la tabla MAC-IP.","refs":[{"ref":"Glosario INCIBE, Pharming","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"aprovecha una vulnerabilidad del software de los servidores DNS"}]},{"text":"XSS = secuencias de comandos en sitios cruzados; zero-day = sin parche porque el fabricante no la conoce.","refs":[{"ref":"Glosario INCIBE, Zero-day","law":"Glosario INCIBE","url":"https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf","quote":"no existe un parche de seguridad para solucionarlas."}]},{"text":"BEC: fraude contra empresas que hacen transferencias; carding: pequeñas compras para probar tarjetas.","refs":[{"ref":"INCIBE, Fraude email comprometido","law":"INCIBE","url":"https://www.incibe.es/ciudadania/blog/deep-web-y-dark-web-descubre-que-son-y-en-que-se-diferencian","quote":"es un tipo de fraude contra empresas que realizan transferencias electrónicas de dinero."}]},{"text":"Kill Chain: siete fases, de Reconocimiento a Acción en el Objetivo; seis líneas de acción, la última Destrucción.","refs":[{"ref":"CCN-STIC-425, párr. 185","law":"CCN-STIC-425","url":"https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file","quote":"Engaño y Destrucción"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf'), 'https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf', null, null, null, null
  from public.topics t where t.slug = 'pn-41-ciberdelincuencia'
