insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 137/1993, de 29 de enero, Reglamento de Armas (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-42-armas', 'Tema 42. Armas de fuego: definición, clasificación y categorías, armas prohibidas y documentación (Reglamento de Armas)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-42-armas' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Definiciones del Reglamento de Armas (art. 2)"},{"n":"2","title":"Categorías de armas (art. 3)"},{"n":"3","title":"Armas prohibidas (arts. 4 y 5)"},{"n":"4","title":"Armas de guerra (art. 6)"},{"n":"5","title":"Licencias y documentación de armas"}]'::jsonb, '["Art. 2.12 Reglamento de Armas: «12. Arma de fuego: Toda arma portátil que tenga cañón y que lance, esté concebida para lanzar o pueda transformarse fácilmente para lanzar un perdigón, una bala o un proyectil por la acción de un combustible propulsor.»","Art. 2.13 Reglamento de Armas: «13. Arma de fuego corta: Arma de fuego cuyo cañón no exceda de 30 cm o cuya longitud total no exceda de 60 cm.»","Art. 2.5 y 2.21 Reglamento de Armas: «21. Arma semiautomática: Arma de fuego que después de cada disparo se recarga automáticamente y con la que solo es posible efectuar un disparo al accionar el disparador cada vez.»","Art. 2.2 Reglamento de Armas: «2. Arma antigua: Arma de fuego cuyo modelo o cuyo año de fabricación es anterior al 1 de enero de 1890.»","Art. 2.29 Reglamento de Armas: «29. Munición: Cartucho completo o sus componentes, incluidas las vainas, los cebos, la carga propulsora, las balas o los proyectiles utilizados en un arma de fuego, siempre que estos componentes estén autorizados en territorio nacional.»","Art. 3 Reglamento de Armas: «1.ª categoría: Armas de fuego cortas: Comprende las pistolas y revólveres.»","Art. 3 Reglamento de Armas: «3. Armas accionadas por aire u otro gas comprimido, sean lisas o rayadas, siempre que la energía cinética del proyectil en boca exceda de 24,2 julios.»","Art. 3 Reglamento de Armas: «7.ª categoría: 1. Armas de inyección anestésica capaces de lanzar proyectiles que faciliten la captura o control de animales, anestesiándolos a distancia durante algún tiempo. 2. Las ballestas.»","Art. 3 Reglamento de Armas: «8.ª categoría: Armas acústicas y de salvas. 9.ª categoría: Armas inutilizadas.»","Art. 4.1.f) Reglamento de Armas: «f) Los bastones-estoque, los puñales de cualquier clase y las navajas llamadas automáticas. Se considerarán puñales a estos efectos las armas blancas de hoja menor de 11 centímetros, de dos filos y puntiaguda.»","Art. 4.1.c) Reglamento de Armas: «c) Las pistolas y revólveres que lleven adaptado un culatín.»","Art. 5.1.k) y m) Reglamento de Armas: «k) Los silenciadores adaptables a armas de fuego.»","Art. 5.1.j) Reglamento de Armas: «1. Queda prohibida la publicidad, compraventa, tenencia y uso, salvo por funcionarios especialmente habilitados, y de acuerdo con lo que dispongan las respectivas normas reglamentarias de: […] j) Las defensas eléctricas, las defensas de goma o extensibles, y las tonfas o similares.»","Art. 6.1 Reglamento de Armas: «a) Armas de fuego o sistemas de armas de fuego de calibre igual o superior a 20 milímetros.»","Art. 96.3 Reglamento de Armas: «3. La licencia de armas A, con la eficacia de las licencias B, D y E, reguladas en los artículos 99 a 104 de este Reglamento, documentará las armas de las categorías 1.ª, 2.ª y 3.ª de propiedad privada del personal de los Cuerpos Específicos de los Ejércitos, de los Cuerpos Comunes de las Fuerzas Armadas, de las Fuerzas y Cuerpos de Seguridad y del Servicio de Vigilancia Aduanera.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Origen de las armas de fuego y objeto del Reglamento de Armas","blocks":[{"text":"El epígrafe empieza por el origen histórico de las armas de fuego, pero esa historia no está en las fuentes oficiales de la plataforma; aquí solo puede recordarse que el Reglamento usa la fecha del 1 de enero de 1890 para separar las armas antiguas de las modernas. La norma de referencia es el Reglamento de Armas aprobado por el Real Decreto 137/1993, que regula la fabricación, reparación, circulación, comercio, adquisición, tenencia y utilización de las armas y sus componentes esenciales, con el objeto de salvaguardar la seguridad pública (art. 1.1).","refs":[{"ref":"Art. 2.2 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"2. Arma antigua: Arma de fuego cuyo modelo o cuyo año de fabricación es anterior al 1 de enero de 1890."},{"ref":"Art. 1.1 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"el presente Reglamento regula los requisitos y condiciones de la fabricación y reparaciones de armas, sus imitaciones y réplicas, y de sus componentes esenciales, así como todo lo concerniente a su circulación, almacenamiento y comercio, su adquisición y enajenación, su tenencia y utilización"}]},{"text":"Ojo a dos detalles. El art. 1.1 sigue citando la Ley Orgánica 1/1992 de Protección de la Seguridad Ciudadana, hoy sustituida por la LO 4/2015, por lo que esa remisión está desactualizada en el texto. Y el art. 1.4 excluye del Reglamento la adquisición, tenencia y uso de armas por las Fuerzas Armadas, las Fuerzas y Cuerpos de Seguridad y el CNI, que se rigen por su normativa especial.","refs":[{"ref":"Art. 1.1 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"De conformidad con lo dispuesto en los artículos 6, 7, 23 y siguientes de la Ley Orgánica 1/1992, de 21 de febrero, sobre Protección de la Seguridad Ciudadana"},{"ref":"Art. 1.4 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"Quedan excluidos del ámbito de aplicación de este Reglamento, y se regirán por la normativa especial dictada al efecto, la adquisición, tenencia y uso de armas por las Fuerzas Armadas, las Fuerzas y Cuerpos de Seguridad y el Centro Nacional de Inteligencia."}]}]},{"n":"2","title":"Definición de arma de fuego y componentes esenciales","blocks":[{"text":"Arma de fuego es toda arma portátil que tenga cañón y que lance, esté concebida para lanzar o pueda transformarse fácilmente para lanzar un perdigón, una bala o un proyectil por la acción de un combustible propulsor (art. 2.12). Es corta la que tiene un cañón que no excede de 30 cm o una longitud total que no excede de 60 cm (art. 2.13); larga es cualquier otra (art. 2.14). Un objeto se considera transformable cuando tiene apariencia de arma de fuego y, por su construcción o material, puede transformarse así.","refs":[{"ref":"Art. 2.12 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"12. Arma de fuego: Toda arma portátil que tenga cañón y que lance, esté concebida para lanzar o pueda transformarse fácilmente para lanzar un perdigón, una bala o un proyectil por la acción de un combustible propulsor."},{"ref":"Art. 2.13 y 2.14 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"13. Arma de fuego corta: Arma de fuego cuyo cañón no exceda de 30 cm o cuya longitud total no exceda de 60 cm. 14. Arma de fuego larga: Cualquier arma de fuego que no sea un arma de fuego corta."}]},{"text":"Son componentes esenciales, en las armas cortas, el armazón, el cañón, el tambor y la corredera o el cerrojo; en las largas, la caja o cajón de los mecanismos, el cañón, el cerrojo o báscula y el cierre. Considerados por separado, tienen el mismo régimen jurídico que el arma de la que forman parte (art. 1.2). La adquisición y tenencia de municiones se rige por las mismas reglas que las armas a que se destinan (art. 1.3).","refs":[{"ref":"Art. 1.2 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"a) El armazón, el cañón, el tambor y la corredera o el cerrojo de las armas de fuego cortas."},{"ref":"Art. 1.2 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"los componentes esenciales considerados como objetos separados, tendrán el mismo régimen jurídico que las armas de las que formen parte"},{"ref":"Art. 1.3 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"Las disposiciones para la adquisición y tenencia de municiones serán las mismas que las que se apliquen a la adquisición y tenencia de las armas a las que se destinen."}]}]},{"n":"3","title":"Funcionamiento: clasificación por el sistema de carga y disparo","blocks":[{"text":"Según cómo se recargan y disparan, el art. 2 distingue: arma automática, que se recarga sola y permite varios disparos sucesivos mientras se mantiene accionado el disparador; semiautomática, que se recarga sola pero solo hace un disparo cada vez que se acciona el disparador; de repetición, que se recarga tras cada disparo mediante un mecanismo accionado por el tirador que introduce en el cañón un cartucho del depósito; y de un solo tiro, sin depósito, que se recarga antes de cada disparo introduciendo manualmente el cartucho.","refs":[{"ref":"Art. 2.5 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"5. Arma automática: Arma de fuego que recarga automáticamente después de cada disparo y con la que es posible efectuar varios disparos sucesivos mientras permanezca accionado el disparador."},{"ref":"Art. 2.21 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"21. Arma semiautomática: Arma de fuego que después de cada disparo se recarga automáticamente y con la que solo es posible efectuar un disparo al accionar el disparador cada vez."},{"ref":"Art. 2.15 y 2.16 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"15. Arma de repetición: Arma de fuego que se recarga después de cada disparo, mediante un mecanismo accionado por el tirador que introduce en el cañón un cartucho colocado previamente en el depósito de municiones. 16. Arma de un solo tiro: Arma de fuego sin depósito de municiones, que se recarga antes de cada disparo mediante la introducción manual de un cartucho en la recámara o en un alojamiento especial a la entrada del cañón."}]},{"text":"El arma basculante, sin depósito, se carga introduciendo a mano el cartucho en la recámara y cierra mediante báscula; puede tener uno o varios cañones. En el arma de avancarga, la carga de proyección y el proyectil se introducen por la boca del cañón o del tambor, y la carga es de pólvora negra o similar. El arma Flobert usa munición de ese calibre, es siempre de percusión anular y su energía en boca no puede pasar de cien julios para ningún calibre.","refs":[{"ref":"Art. 2.6 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"6. Arma basculante: Arma de fuego que, sin depósito de municiones, se carga mediante la introducción manual de un cartucho en la recámara y tiene un sistema de cierre mediante báscula. Puede tener uno o varios cañones."},{"ref":"Art. 2.11 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"11. Arma de avancarga: Arma de fuego en la que la carga de proyección y el proyectil se introducen por la boca del cañón o, en su caso, por la boca de la recámara del tambor."},{"ref":"Art. 2.17 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"Dicha arma siempre es de percusión anular y puede llevar una pequeña carga de pólvora o solo la carga iniciadora. La energía cinética en boca no puede sobrepasar los cien (100) J para ningún calibre."}]}]},{"n":"4","title":"Otras definiciones del Reglamento","blocks":[{"text":"Arma antigua es la de modelo o año de fabricación anterior al 1 de enero de 1890; histórica, la relacionada con un hecho o personaje histórico relevante; artística, la que tiene un valor especial por sus materiales o diseño. El arma inutilizada es la que se ha vuelto permanentemente inservible conforme a la ITC 2. El arma acústica o de salvas es un arma de fuego transformada para usar solo cartuchos de fogueo en recreaciones, filmaciones y espectáculos. La imitación o réplica puede inducir a confusión sobre su naturaleza aunque no pueda transformarse en arma.","refs":[{"ref":"Art. 2.1 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"1. Arma acústica y arma de salvas: Arma de fuego transformada de forma específica para su uso exclusivo con cartuchos de fogueo en recreaciones históricas, filmaciones, artes escénicas y espectáculos públicos."},{"ref":"Art. 2.18 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"18. Arma histórica: Arma de fuego que se signifique especialmente por su relación con un hecho o personaje histórico relevante, convenientemente acreditada."},{"ref":"Art. 2.27 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"27. Imitación o réplica de un arma: Objeto que por su apariencia física o características externas puede inducir a confusión sobre su auténtica naturaleza, aunque no pueda transformarse en un arma."}]},{"text":"El arma asimilada a arma de fuego es la que, por sus características y peligrosidad, tiene el mismo régimen que esta; en todo caso lo son las de las categorías 3.ª.3 y 7.ª.2 y 3. El arma blanca es la constituida por una hoja metálica u otro material semejante, cortante o punzante.","refs":[{"ref":"Art. 2.3 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"En todo caso, se considerarán armas asimiladas, las armas reglamentadas de las categorías 3.ª 3 7.ª 2 y 3."},{"ref":"Art. 2.7 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"7. Arma blanca: Arma constituida por una hoja metálica u otro material de características físicas semejantes, cortante o punzante."}]}]},{"n":"5","title":"Categorías de armas (I): de la 1.ª a la 4.ª","blocks":[{"text":"El art. 3 clasifica las armas reglamentadas según sus características, peligrosidad y destino. La 1.ª categoría son las armas de fuego cortas: pistolas y revólveres. La 2.ª, las armas largas para vigilancia y guardería y las largas rayadas para caza mayor. La 3.ª comprende las largas rayadas de tiro deportivo de calibre 5,6 mm (.22 americano) de percusión anular, las escopetas y armas largas de ánima lisa, y las de aire o gas comprimido cuya energía en boca supere 24,2 julios. La 4.ª, carabinas, pistolas y revólveres de aire o gas comprimido no asimiladas a escopetas.","refs":[{"ref":"Art. 3 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"1.ª categoría: Armas de fuego cortas: Comprende las pistolas y revólveres."},{"ref":"Art. 3 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"2. Armas de fuego largas rayadas: Se comprenden aquellas armas utilizables para caza mayor."},{"ref":"Art. 3 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"3. Armas accionadas por aire u otro gas comprimido, sean lisas o rayadas, siempre que la energía cinética del proyectil en boca exceda de 24,2 julios."},{"ref":"Art. 3 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"1. Carabinas y pistolas, de tiro semiautomático y de repetición ; y revólveres de doble acción, accionadas por aire u otro gas comprimido no asimiladas a escopetas."}]}]},{"n":"6","title":"Categorías de armas (II): de la 5.ª a la 9.ª","blocks":[{"text":"La 5.ª categoría son las armas blancas no prohibidas y los cuchillos o machetes militares o sus imitaciones. La 6.ª, las armas de fuego antiguas o históricas en museos autorizados, las anteriores al 1 de enero de 1890 y sus réplicas, las conservadas por su carácter histórico o artístico y, en general, las de avancarga. La 7.ª incluye las armas de inyección anestésica para la captura de animales, las ballestas, las armas para lanzar cabos, las de sistema Flobert, los arcos y fusiles de pesca submarina, y las armas de alarma y señales. La 8.ª son las armas acústicas y de salvas, y la 9.ª las inutilizadas.","refs":[{"ref":"Art. 3 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"1. Las armas blancas y en general las de hoja cortante o punzante no prohibidas."},{"ref":"Art. 3 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"4. En general, las armas de avancarga."},{"ref":"Art. 3 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"7.ª categoría: 1. Armas de inyección anestésica capaces de lanzar proyectiles que faciliten la captura o control de animales, anestesiándolos a distancia durante algún tiempo. 2. Las ballestas."},{"ref":"Art. 3 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"8.ª categoría: Armas acústicas y de salvas. 9.ª categoría: Armas inutilizadas."}]}]},{"n":"7","title":"El cartucho: definición y componentes","blocks":[{"text":"El Diccionario de la lengua española define el cartucho como la carga de pólvora y municiones, o de pólvora sola, correspondiente a cada tiro de un arma de fuego, envuelta en papel o lienzo o encerrada en un tubo metálico. El Reglamento define la munición como el cartucho completo o sus componentes: vainas, cebos, carga propulsora, balas o proyectiles, siempre que estén autorizados en territorio nacional (art. 2.29). La vaina es la parte metálica de la munición que contiene la carga explosiva; el fulminante, la materia capaz de hacer estallar cargas explosivas, como la del cartucho.","refs":[{"ref":"DLE, cartucho 1.a","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"Carga de pólvora y municiones, o de pólvora sola, correspondiente a cada tiro de algún arma de fuego, envuelta en papel o lienzo o encerrada en un tubo metálico, para cargar de una vez."},{"ref":"Art. 2.29 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"29. Munición: Cartucho completo o sus componentes, incluidas las vainas, los cebos, la carga propulsora, las balas o los proyectiles utilizados en un arma de fuego, siempre que estos componentes estén autorizados en territorio nacional."},{"ref":"DLE, vaina 2.c y fulminante 1.c","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"Parte metálica de la munición, que contiene la carga explosiva. […] Dicho de una materia, capaz de hacer estallar cargas explosivas."}]},{"text":"Para entender el disparo conviene conocer más términos del DLE: el ánima es el hueco del cañón; la recámara, el lugar del ánima opuesto a la boca donde se coloca el cartucho; el percutor, el martillo o aguja que hace detonar el cebo del cartucho; y el calibre, el diámetro interior de las armas de fuego o el de un proyectil. El Reglamento distingue además municiones especiales: perforante, explosiva e incendiaria (de uso militar) y expansiva, cuyos proyectiles se deforman al impactar en un blanco similar al tejido carnoso para transferir el máximo de energía.","refs":[{"ref":"DLE, ánima 3","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"En las piezas de artillería y en toda arma de fuego, en general, el hueco del cañón."},{"ref":"DLE, recámara 1.a","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"En las armas de fuego, lugar del ánima del cañón al extremo opuesto a la boca, en el cual se coloca el cartucho."},{"ref":"DLE, percutor","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"Pieza que golpea en cualquier máquina, y especialmente el martillo o la aguja con que se hace detonar el cebo del cartucho en las armas de fuego."},{"ref":"Art. 2.33 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"33. Munición de bala expansiva: Munición con proyectiles de diferente composición, estructura y diseño con el fin de que, al impactar estos en un blanco similar al tejido carnoso, se deformen expandiéndose y transfiriendo el máximo de energía en estos blancos."}]}]},{"n":"8","title":"Armas prohibidas (art. 4)","blocks":[{"text":"El art. 4 prohíbe la fabricación, importación, circulación, publicidad, compraventa, tenencia y uso, entre otras, de: las armas de fuego de fabricación ilícita o modificadas sin autorización; las armas largas con dispositivos para alojar pistolas; las pistolas y revólveres con culatín adaptado; las armas de fuego ocultas en bastones u otros objetos o simuladas bajo otra apariencia; los bastones-estoque, los puñales de cualquier clase y las navajas automáticas; las armas de fuego o de aire combinadas con armas blancas; y las defensas de alambre o plomo, rompecabezas, llaves de pugilato, tiragomas y cerbatanas perfeccionados, munchacos y xiriquetes.","refs":[{"ref":"Art. 4.1 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"Se prohíbe la fabricación, importación, circulación, publicidad, compraventa, tenencia y uso de las siguientes armas o de sus imitaciones"},{"ref":"Art. 4.1.c) RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"c) Las pistolas y revólveres que lleven adaptado un culatín."},{"ref":"Art. 4.1.h) RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"h) Las defensas de alambre o plomo ; los rompecabezas; las llaves de pugilato, con o sin púas; los tiragomas y cerbatanas perfeccionados; los munchacos y xiriquetes"}]},{"text":"A estos efectos, son puñales las armas blancas de hoja menor de 11 centímetros, de dos filos y puntiaguda. Los museos y coleccionistas del art. 107 pueden tener estas armas con los requisitos que allí se fijan (art. 4.2).","refs":[{"ref":"Art. 4.1.f) RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"f) Los bastones-estoque, los puñales de cualquier clase y las navajas llamadas automáticas. Se considerarán puñales a estos efectos las armas blancas de hoja menor de 11 centímetros, de dos filos y puntiaguda."},{"ref":"Art. 4.2 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"No se considerará prohibida la tenencia de las armas relacionadas en el presente artículo por los museos, coleccionistas u organismos a que se refiere el artículo 107"}]}]},{"n":"9","title":"Armas prohibidas salvo a funcionarios habilitados y armas de guerra","blocks":[{"text":"El art. 5.1 prohíbe la publicidad, compraventa, tenencia y uso, salvo por funcionarios especialmente habilitados, de: armas cortas semiautomáticas de percusión central con capacidad superior a 21 cartuchos y largas de más de 11; armas largas de cañones recortados; cargadores de más de 20 cartuchos (cortas) o 10 (largas); sprays de defensa personal no autorizados; las defensas eléctricas, de goma o extensibles y las tonfas; los silenciadores; las municiones perforantes, explosivas o incendiarias; y las municiones «dum-dum» o de punta hueca para pistolas y revólveres. También se prohíben las navajas no automáticas de hoja superior a 11 cm, salvo en el domicilio con fines de ornato y coleccionismo (art. 5.3).","refs":[{"ref":"Art. 5.1 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"Queda prohibida la publicidad, compraventa, tenencia y uso, salvo por funcionarios especialmente habilitados, y de acuerdo con lo que dispongan las respectivas normas reglamentarias de"},{"ref":"Art. 5.1.j), k) y m) RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"j) Las defensas eléctricas, las defensas de goma o extensibles, y las tonfas o similares. k) Los silenciadores adaptables a armas de fuego. […] m) Las municiones para pistolas y revólveres con proyectiles ‘‘dum-dum’’ o de punta hueca, así como los propios proyectiles."},{"ref":"Art. 5.3 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"También se prohíbe la comercialización, publicidad, compraventa, tenencia y uso de las navajas no automáticas cuya hoja exceda de 11 centímetros"}]},{"text":"Son armas de guerra, prohibidas a los particulares: las armas de fuego de calibre igual o superior a 20 milímetros, las de calibre inferior que el Ministerio de Defensa considere de guerra, las armas de fuego automáticas, sus municiones y componentes, y las bombas, misiles, cohetes, torpedos, minas y granadas (art. 6.1). El Gobierno determina cuáles pueden ser dotación de las Fuerzas y Cuerpos de Seguridad (art. 6.2).","refs":[{"ref":"Art. 6.1 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"a) Armas de fuego o sistemas de armas de fuego de calibre igual o superior a 20 milímetros."},{"ref":"Art. 6.1.c) RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"c) Armas de fuego automáticas."},{"ref":"Art. 6.2 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"Corresponde al Gobierno, a propuesta conjunta de los Ministerios de Defensa y del Interior, determinar las armas comprendidas en este artículo que pueden ser utilizadas como dotación de los miembros de las Fuerzas y Cuerpos de Seguridad."}]}]},{"n":"10","title":"Documentación que ampara la tenencia y el porte: licencias y tarjetas","blocks":[{"text":"Nadie puede llevar ni poseer armas de fuego en España sin la autorización correspondiente (art. 96.1). Las categorías 1.ª, 2.ª y 3.ª requieren licencia. La licencia A, con eficacia de las B, D y E, documenta las armas de esas categorías de propiedad privada de militares, miembros de las Fuerzas y Cuerpos de Seguridad y del Servicio de Vigilancia Aduanera. La B es para armas cortas de particulares; la C, para armas de dotación del personal de vigilancia y seguridad; la D, para armas largas rayadas de caza mayor; la E, para las categorías 3.ª y 7.ª.2 y 3; y la F, para armas de concurso de tiro deportivo de federados.","refs":[{"ref":"Art. 96.3 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"3. La licencia de armas A, con la eficacia de las licencias B, D y E, reguladas en los artículos 99 a 104 de este Reglamento, documentará las armas de las categorías 1.ª, 2.ª y 3.ª de propiedad privada del personal de los Cuerpos Específicos de los Ejércitos, de los Cuerpos Comunes de las Fuerzas Armadas, de las Fuerzas y Cuerpos de Seguridad y del Servicio de Vigilancia Aduanera."},{"ref":"Art. 96.4 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"a) La licencia de armas B para armas de fuego cortas de particulares. b) La licencia C, para armas de dotación del personal de vigilancia y seguridad no comprendido en el apartado 3. c) La licencia D de arma larga rayada para caza mayor."},{"ref":"Art. 96.5 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"La licencia de armas F documentará las armas de concurso de tiro deportivo de afiliados de federaciones deportivas"}]},{"text":"Para llevar y usar armas de la 4.ª categoría basta la tarjeta de armas (art. 96.6), que conceden los Alcaldes y vale solo en su término municipal; la tarjeta A (categoría 4.ª.1) documenta hasta seis armas y dura cinco años, y la B (4.ª.2) es de número ilimitado y validez permanente (art. 105). Además, cada arma de las categorías 1.ª, 2.ª, 3.ª, 6.ª, 7.ª.1 a 4 y 8.ª debe estar documentada con su guía de pertenencia, que la acompaña siempre en uso, depósito y transporte (arts. 88 y 89).","refs":[{"ref":"Art. 96.6 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"Para llevar y usar armas de la categoría 4.ª se necesita obtener tarjeta de armas."},{"ref":"Art. 105.1 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"Las tarjetas de armas serán concedidas y retiradas, en su caso, por los Alcaldes de los municipios en que se encuentren avecindados o residiendo los solicitantes"},{"ref":"Art. 88 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"Para la tenencia de las armas de las categorías 1.ª, 2.ª, 3.ª, 6.ª, 7.ª, 1, 2, 3, 4 y 8.ª, cada arma habrá de estar documentada con su correspondiente guía de pertenencia."}]}]},{"n":"11","title":"Licencias B, D y E: requisitos y vigencia","blocks":[{"text":"La licencia B solo se expide a quien tenga necesidad y la concede la Dirección General de la Guardia Civil. La defensa de personas o bienes, por sí sola, no justifica su concesión, que es restrictiva y se limita a supuestos de riesgo especial y de necesidad (art. 99.2). Dura cinco años, nadie puede tener más de una licencia B y cada licencia ampara un solo arma (art. 99.6). La D tiene cinco años de validez y autoriza hasta cinco armas de la categoría 2.ª.2; la E, también de cinco años, ampara como máximo seis escopetas o seis armas largas rayadas de tiro deportivo, y doce armas en total; ambas las concede el Jefe de la Comandancia de la Guardia Civil.","refs":[{"ref":"Art. 99.2 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"la razón de defensa de personas o bienes, por sí sola, no justifica la concesión de la licencia, cuya expedición tendrá carácter restrictivo, limitándose a supuestos de existencia de riesgo especial y de necesidad."},{"ref":"Art. 99.6 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"Estas licencias tendrán cinco años de validez […] Nadie podrá poseer más de una licencia B, y cada licencia no amparará más de un arma."},{"ref":"Art. 100.2 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"Nadie podrá poseer más de una licencia D, que tendrá cinco años de validez y autorizará para llevar y usar hasta cinco armas de la categoría 2.ª, 2."},{"ref":"Art. 101.1 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"Su número no excederá de seis escopetas o de seis armas largas rayadas para tiro deportivo, ni de doce armas en total."}]},{"text":"Las licencias de las categorías 1.ª, 2.ª y 3.ª solo se expiden a españoles y extranjeros residentes mayores de edad (art. 102.1). La solicitud se presenta en la Intervención de Armas de la Guardia Civil del domicilio, con certificado de antecedentes penales, documento de identidad e informe de aptitudes psicofísicas (art. 97.1). Una condena por delito doloso violento se considera indicativa de riesgo (art. 98.1). A los mayores de 67 años la licencia se les visa a los tres años (art. 104.1).","refs":[{"ref":"Art. 102.1 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"Las licencias para armas de las categorías 1.ª, 2.ª y 3.ª solamente podrán ser expedidas a los españoles y extranjeros con residencia en España, que sean mayores de edad."},{"ref":"Art. 98.1 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"el hecho de haber tenido una condena por un delito doloso violento se considerará indicativo de dicho riesgo."},{"ref":"Art. 104.1 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"las expedidas a mayores de sesenta y siete años necesitarán ser visadas a los tres años desde la fecha de su expedición"}]}]},{"n":"12","title":"Balística forense","blocks":[{"text":"El DLE define la balística como el estudio del movimiento y efectos de los proyectiles de las armas de fuego, y pone como ejemplo que la Policía Judicial cuenta con expertos en balística. El desarrollo técnico de la balística forense (balística interior, exterior y de efectos, identificación de vainas y proyectiles) no está en las fuentes oficiales de la plataforma, por lo que no se desarrolla aquí.","refs":[{"ref":"DLE, balística 1.a","law":"DLE (RAE)","url":"https://dle.rae.es/","quote":"Estudio del movimiento y efectos de los proyectiles de las armas de fuego.La Policía Judicial cuenta con expertos en balística."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Arma de fuego corta: cañón de hasta 30 cm o longitud total de hasta 60 cm.","refs":[{"ref":"Art. 2.13 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"cuyo cañón no exceda de 30 cm o cuya longitud total no exceda de 60 cm."}]},{"text":"Semiautomática: un disparo por cada accionamiento; automática: ráfaga y es arma de guerra.","refs":[{"ref":"Art. 6.1.c) RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"c) Armas de fuego automáticas."}]},{"text":"1.ª categoría: pistolas y revólveres; aire comprimido de más de 24,2 julios: 3.ª; ballestas: 7.ª; inutilizadas: 9.ª.","refs":[{"ref":"Art. 3 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"2. Las ballestas."}]},{"text":"Arma antigua: anterior al 1 de enero de 1890. Flobert: máximo 100 J.","refs":[{"ref":"Art. 2.17 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"La energía cinética en boca no puede sobrepasar los cien (100) J para ningún calibre."}]},{"text":"Puñal prohibido: hoja menor de 11 cm, dos filos y puntiaguda.","refs":[{"ref":"Art. 4.1.f) RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"armas blancas de hoja menor de 11 centímetros, de dos filos y puntiaguda."}]},{"text":"Silenciadores, tonfas y defensas eléctricas: prohibidos salvo a funcionarios especialmente habilitados.","refs":[{"ref":"Art. 5.1.k) RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"k) Los silenciadores adaptables a armas de fuego."}]},{"text":"Arma de guerra: calibre igual o superior a 20 mm.","refs":[{"ref":"Art. 6.1.a) RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"calibre igual o superior a 20 milímetros."}]},{"text":"Licencia A: armas particulares de FCS y militares; C: vigilantes; 4.ª categoría: tarjeta de armas.","refs":[{"ref":"Art. 96.4.b) RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"La licencia C, para armas de dotación del personal de vigilancia y seguridad"}]},{"text":"Licencia B: cinco años, una sola licencia y un solo arma.","refs":[{"ref":"Art. 99.6 RA","law":"Reglamento de Armas","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202","quote":"cada licencia no amparará más de un arma."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202', null, null, null, null
  from public.topics t where t.slug = 'pn-42-armas'
